impl ErasedSnapshotRetirement for ArtifactEditMessageLedgerRejected {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active.close_step(maximum_items, maximum_bytes)? {
                SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(SnapshotRetirementStep::Pending { released_items, released_bytes }),
                SnapshotRetirementStep::Pending { .. } => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "rejected artifact edit-message owner exceeded its exact close grant")),
                SnapshotRetirementStep::Blocked => Ok(SnapshotRetirementStep::Blocked),
                SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "rejected artifact edit-message owner reported Complete without its terminal witness"));
                    }
                    drop(self.active.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
            };
        }
        if !self.entries_terminal {
            if let Some(entry) = self.entries.pop() {
                *self.active = Some(ArtifactStoreMessageLedgerRetirement::new(entry.edit_id, entry.messages));
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            drop(unsafe { std::mem::ManuallyDrop::take(&mut self.entries) });
            self.entries_terminal = true;
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.entries_terminal && self.active.is_none()
    }
}

impl Drop for ArtifactEditMessageLedgerRejected {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "rejected artifact edit-message authority reached Drop before every exact payload owner was cursor-retired: {}", self.reason);
    }
}

impl Drop for ArtifactEditMessageLedger {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "artifact edit-message fixed ledger reached Drop before every exact payload owner was cursor-retired");
    }
}

//#region 📬️OneItemPublication
#[path = "🧵️canonical-edit/🦀️.rs"]
mod canonical_edit;
pub use canonical_edit::{
    ARTIFACT_CANONICAL_JSON_CHUNK_BYTES, ARTIFACT_CANONICAL_JSON_DEPTH, ArtifactCanonicalJson, ArtifactCanonicalJsonArray, ArtifactCanonicalJsonCursor, ArtifactCanonicalJsonEncodeError, ArtifactCanonicalJsonNode, ArtifactCanonicalJsonObject,
    ArtifactCanonicalJsonReader, ArtifactCanonicalJsonValue, ArtifactCanonicalValue, ArtifactCanonicalValueAdmission, ArtifactCanonicalValueCheckpoint, ArtifactCanonicalValueCloseStep, ArtifactCanonicalValueGrant, ArtifactCanonicalValueLimits,
    ArtifactCanonicalValueStep, ArtifactStoreOneItemSealCheckpoint, ArtifactStoreOneItemSealer,
};

pub const ARTIFACT_STORE_ONE_ITEM_MAXIMUM_WORK_ITEMS: usize = 65_536;
pub const ARTIFACT_STORE_ONE_ITEM_MAXIMUM_BYTES: usize = 1_048_576;
pub const ARTIFACT_STORE_ONE_ITEM_MAXIMUM_RETRIES: u8 = 2;
pub const ARTIFACT_STORE_ONE_ITEM_ID_BYTES: usize = 256;

/// 🧮 Exact capacity declaration checked before a retained one-item preparation receives
/// the immutable base root or mutation owner.
///
/// `work_items` counts **staged edit ROWS**, never mutations: one durable item always contributes
/// its single `forwards` row PLUS every row its `inverse` yields, and
/// [`ArtifactStore::fold_batch_item`] / the `PreflightingCommit` gate both compare
/// `forwards.len() + inverse.len()` against the gesture-wide merged declaration. A point-invertible
/// mutation therefore costs **2**, not 1 — declaring 1 fail-closes EVERY single-mutation durable
/// gesture with `batched item candidate failed its exact fixed fold contract` and every multi-item
/// one with `batched prepared candidate failed its exact fixed commit contract`. Never write the
/// number at a call site: a durable lane declares through [`ArtifactStoreOneItemFootprint::for_leaf`], whose inverse rows
/// the leaf payload schema declares (`x-semio-inverse-rows`, design §20.5), and an ephemeral lane through
/// [`ArtifactStoreOneItemFootprint::for_ephemeral_item`] (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
#[derive(Clone, Copy, Debug, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct ArtifactStoreOneItemFootprint {
    pub work_items: usize,
    pub retained_bytes: usize,
}

/// 🧾️ Staged edit rows ONE point-invertible durable item folds: its single forward row plus the
/// single inverse row `Mutation::inverse` yields for it.
pub const ARTIFACT_STORE_ONE_ITEM_INVERTIBLE_WORK_ITEMS: usize = 2;

impl ArtifactStoreOneItemFootprint {
    pub fn is_admissible(self) -> bool {
        self.work_items != 0 && self.work_items <= ARTIFACT_STORE_ONE_ITEM_MAXIMUM_WORK_ITEMS && self.retained_bytes <= ARTIFACT_STORE_ONE_ITEM_MAXIMUM_BYTES
    }

    /// 🧺️ The ONE declaration a durable lane makes for `mutation`: its forward row plus the inverse rows its leaf payload
    /// schema declares — the upper bound the lane can prove from the mutation alone, since `preflight` never sees the base.
    pub fn for_leaf<P, M: crate::os_spr::Mutation<P>>(mutation: &M, retained_bytes: usize) -> Self {
        Self { work_items: mutation.inverse_rows().saturating_add(1), retained_bytes }
    }

    /// 🫧️ The declaration of one ephemeral (presence, transient, window-transient) item: its single forward row, which no
    /// inverse ever accompanies.
    pub fn for_ephemeral_item(retained_bytes: usize) -> Self {
        Self { work_items: 1, retained_bytes }
    }

    /// ➕️ Folds one more admitted item into the gesture-wide declaration a batched publication is
    /// admitted against.
    pub fn merged(self, item: Self) -> Self {
        Self { work_items: self.work_items.saturating_add(item.work_items), retained_bytes: self.retained_bytes.max(item.retained_bytes) }
    }
}

/// 🎟️ One scheduler grant. A preparation owner must consume at most one semantic unit even
/// when both limits are larger than one.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct ArtifactStoreOneItemGrant {
    pub maximum_items: usize,
    pub maximum_bytes: usize,
}

impl ArtifactStoreOneItemGrant {
    pub fn permits_one(self) -> bool {
        self.maximum_items != 0 && self.maximum_bytes != 0
    }
}

/// 📍 Fixed-width replay checkpoint emitted after every accepted preparation unit.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct ArtifactStoreOneItemCheckpoint {
    pub cursor: u32,
    pub completed_items: u32,
    pub completed_bytes: u64,
    pub digest: [u8; 32],
}

/// 🛠️ Result of one domain-owned preparation turn.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactStoreOneItemPreparationStep {
    Progress(ArtifactStoreOneItemCheckpoint),
    Prepared(ArtifactStoreOneItemCheckpoint),
    Blocked,
}

/// 🪪 Exact live publication metadata minted by the Store and shared immutably with the
/// domain preparation owner. Apps cannot invent cursor position, sequence, clock, or actor.
pub struct ArtifactStoreOneItemLiveAuthority {
    operation: semio_framework_job::OperationId,
    generation: semio_framework_job::Generation,
    base_revision: [u8; 32],
    base_applied_edit_count: usize,
    next_sequence_number: i32,
    next_clock: HybridLogicalTimestamp,
    actor: String,
    line: Option<String>,
    group_id: Option<String>,
    stamped_edit_id: Option<String>,
}

impl ArtifactStoreOneItemLiveAuthority {
    pub fn operation(&self) -> semio_framework_job::OperationId {
        self.operation
    }

    pub fn generation(&self) -> semio_framework_job::Generation {
        self.generation
    }

    pub fn base_revision(&self) -> [u8; 32] {
        self.base_revision
    }

    pub fn base_applied_edit_count(&self) -> usize {
        self.base_applied_edit_count
    }

    pub fn next_sequence_number(&self) -> i32 {
        self.next_sequence_number
    }

    pub fn next_clock(&self) -> HybridLogicalTimestamp {
        self.next_clock
    }

    pub fn actor(&self) -> &str {
        &self.actor
    }

    /// 🪪️ The globally unique identity of the edit this authority publishes — content-addressed
    /// over the actor, the sequence and the HLC tick the Store minted, so two replicas' edits never
    /// share an identity the way a replica-local counter would. The Store stamps it on the staged edit.
    ///
    /// 🔏 A server-stamped publication instead publishes under the identity its durable
    /// decision was hashed over: the approval's own mutation id, itself content-addressed over the
    /// job and the proposal, so the uniqueness argument above still holds and the committed edit
    /// carries the identity every downstream verifier (WAL, ledger, actor frontier) binds against.
    pub fn edit_id(&self) -> String {
        if let Some(stamped) = self.stamped_edit_id.as_ref() {
            return stamped.clone();
        }
        let mut material = Vec::with_capacity(self.actor.len() + 48);
        material.extend_from_slice(&(self.actor.len() as u64).to_le_bytes());
        material.extend_from_slice(self.actor.as_bytes());
        material.extend_from_slice(&self.next_sequence_number.to_le_bytes());
        for part in [self.next_clock.actor, self.next_clock.physical_ms, self.next_clock.logical] {
            material.extend_from_slice(&part.to_le_bytes());
        }
        let digest = semio_framework_hash::hash(&material);
        let mut id = String::with_capacity(21);
        id.push_str("edit-");
        for byte in &digest.as_bytes()[..8] {
            id.push_str(&format!("{byte:02x}"));
        }
        id
    }

    /// 🌿️ The immutable authored branch of this Store publication.
    pub fn line_id(&self) -> Option<&str> {
        self.line.as_deref()
    }

    pub fn group_id(&self) -> Option<&str> {
        self.group_id.as_deref()
    }

    /// 🔏 The server-stamped identity this publication was minted under, or `None` for every
    /// local gesture. The fold reads it to keep the stamped mutation id on the first folded item
    /// instead of rewriting it to the store's `<edit-id>#<position>` form.
    pub fn stamped_edit_id(&self) -> Option<&str> {
        self.stamped_edit_id.as_deref()
    }

    /// 🧾️ The ONE semantic edit a one-item preparation publishes: `forward` with its `inverse` rows, minted entirely from
    /// this authority (identity, actor, line, group, sequence, clock, base version) so no domain hand-builds an edit or
    /// invents a field the Store validates. It carries no hand-written description (design §20.6): the fold stamps semantic
    /// kind, label and transaction, and history labels the row from the leaf.
    pub fn next_edit<Mutation>(&self, forward: Mutation, inverse: Vec<Mutation>) -> Edit<Mutation> {
        let id = self.edit_id();
        Edit {
            line: self.line.clone(),
            mutation_meta: vec![MutationMeta {
                mutation_id: Some(MutationId(format!("{id}#0"))),
                dependencies: Vec::new(),
                base_version: self.base_applied_edit_count as u64,
                author_id: Some(ActorId(self.actor.clone())),
                timestamp: self.next_clock,
                undo_policy: UndoPolicy::ExactBaseOnly,
                payload_hash: None,
                semantic_kind: None,
                label: None,
                group_id: self.group_id.clone(),
                origin: Default::default(),
                transaction: None,
            }],
            id,
            actor: Some(self.actor.clone()),
            forwards: vec![forward],
            inverse,
            description: None,
            verb: None,
            sequence_number: self.next_sequence_number,
            started_at: String::new(),
            finished_at: None,
        }
    }

    /// 🧹️ Transfers the authority Arc and its final actor/group strings into byte-bounded retirement.
    pub fn retire(self: Arc<Self>) -> Box<dyn ErasedSnapshotRetirement> {
        Box::new(canonical_edit::ArtifactStoreOneItemAuthorityRetirement::new(self))
    }

    fn validate_semantic_edit<Mutation>(&self, edit: &Edit<Mutation>) -> Result<(), String> {
        let meta = edit.mutation_meta.first().ok_or_else(|| "one-item edit lacks its exact authority metadata".to_string())?;
        if edit.id.is_empty()
            || edit.id.len() > ARTIFACT_STORE_ONE_ITEM_ID_BYTES
            || edit.sequence_number != self.next_sequence_number
            || edit.forwards.len() != 1
            || edit.mutation_meta.len() != 1
            || edit.actor.as_deref() != Some(self.actor.as_str())
            || edit.line != self.line
            || meta.author_id.as_ref().map(|actor| actor.0.as_str()) != Some(self.actor.as_str())
            || meta.timestamp != self.next_clock
            || meta.group_id.as_deref() != self.group_id.as_deref()
        {
            return Err("one-item semantic edit disagrees with its immutable Store authority".into());
        }
        Ok(())
    }

    /// 🔏 Canonical oracle for explicitly bounded edits; retained large edits use the byte sealer.
    pub fn prepared_edit_digest<Mutation: ToValue>(&self, edit: &Edit<Mutation>) -> Result<[u8; 32], String> {
        self.validate_semantic_edit(edit)?;
        Ok(CursorRevisionAccumulator::edit_digest(edit))
    }

    /// 📦 Seals an explicitly bounded semantic edit into exact Store-owned publication authority.
    pub fn prepare_one_item<P, Mutation: ToValue>(self: &Arc<Self>, edit: Edit<Mutation>, post_snapshot: Arc<P>) -> Result<ArtifactStoreOneItemPrepared<P, Mutation>, String> {
        let edit_digest = self.prepared_edit_digest(&edit)?;
        Ok(self.seal_prepared(Box::new(edit), post_snapshot, edit_digest))
    }

    /// 🧵️ Moves the exact edit and post root into retained canonical preparation without encoding.
    pub fn begin_one_item_seal<P, Mutation>(
        self: &Arc<Self>,
        edit: Edit<Mutation>,
        post_snapshot: Arc<P>,
        mutation_retirement: Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>,
        snapshot_retirement: Arc<dyn SnapshotRetirementFactory<P>>,
    ) -> ArtifactStoreOneItemSealer<P, Mutation> {
        ArtifactStoreOneItemSealer::new(Arc::clone(self), edit, post_snapshot, mutation_retirement, snapshot_retirement)
    }

    fn seal_prepared<P, Mutation>(self: &Arc<Self>, edit: Box<Edit<Mutation>>, post_snapshot: Arc<P>, edit_digest: [u8; 32]) -> ArtifactStoreOneItemPrepared<P, Mutation> {
        let edit_id = edit.id.clone();
        let identities = [self.actor.clone(), edit_id.clone(), edit_id];
        self.seal_prepared_owned(edit, post_snapshot, edit_digest, identities)
    }

    fn seal_prepared_owned<P, Mutation>(self: &Arc<Self>, edit: Box<Edit<Mutation>>, post_snapshot: Arc<P>, edit_digest: [u8; 32], identities: [String; 3]) -> ArtifactStoreOneItemPrepared<P, Mutation> {
        let [actor, applied_edit_id, tail_edit_id] = identities;
        let seal = ArtifactStoreOneItemSeal { authority: Arc::clone(self), edit_address: edit.as_ref() as *const Edit<Mutation> as usize, post_address: Arc::as_ptr(&post_snapshot) as usize, digest: edit_digest };
        ArtifactStoreOneItemPrepared { edit, post_snapshot, next_clock: self.next_clock, edit_digest, local_actor: Some(actor), applied_edit_id, tail_edit_id, seal }
    }

    fn validate_prepared<P, Mutation>(self: &Arc<Self>, prepared: &ArtifactStoreOneItemPrepared<P, Mutation>) -> Result<(), String> {
        self.validate_semantic_edit(&prepared.edit)?;
        if !Arc::ptr_eq(self, &prepared.seal.authority)
            || prepared.seal.edit_address != prepared.edit.as_ref() as *const Edit<Mutation> as usize
            || prepared.seal.post_address != Arc::as_ptr(&prepared.post_snapshot) as usize
            || prepared.seal.digest != prepared.edit_digest
        {
            return Err("one-item private Store seal disagrees with exact authority or moved owners".into());
        }
        Ok(())
    }
}

struct ArtifactStoreOneItemSeal {
    authority: Arc<ArtifactStoreOneItemLiveAuthority>,
    edit_address: usize,
    post_address: usize,
    digest: [u8; 32],
}

/// 📦 Fully prepared one-item candidate. The domain must build every potentially unbounded
/// mutation inverse/diff/apply/encoding result inside its retained cursor before exposing this
/// value. The store publication turn only validates fixed authorities and moves these owners.
pub struct ArtifactStoreOneItemPrepared<P, Mutation> {
    edit: Box<Edit<Mutation>>,
    post_snapshot: Arc<P>,
    next_clock: HybridLogicalTimestamp,
    edit_digest: [u8; 32],
    local_actor: Option<String>,
    applied_edit_id: String,
    tail_edit_id: String,
    seal: ArtifactStoreOneItemSeal,
}

impl<P, Mutation> ArtifactStoreOneItemPrepared<P, Mutation> {
    pub fn edit_digest(&self) -> [u8; 32] {
        self.edit_digest
    }
}

/// 🧳 Exact owner bundle transferred to a domain preparation factory only after preflight.
pub struct ArtifactStoreOneItemPreparationRequest<P, Mutation> {
    pub operation: semio_framework_job::OperationId,
    pub generation: semio_framework_job::Generation,
    pub base_revision: [u8; 32],
    pub lane: HistoryLane,
    pub authority: Arc<ArtifactStoreOneItemLiveAuthority>,
    pub description: Option<String>,
    pub base: SnapshotRead<P>,
    pub mutation: Mutation,
}

impl<P, Mutation> ArtifactStoreOneItemPreparationRequest<P, Mutation> {
    pub fn into_owners(self) -> (SnapshotRead<P>, Mutation, Option<String>) {
        (self.base, self.mutation, self.description)
    }
}

/// 🧩 Domain-owned retained mutation preparation. Generic `Mutation` is intentionally not
/// invoked by the store: a domain that cannot split its mutation semantics into these turns is
/// rejected at admission instead of receiving false resumability credit.
pub trait ArtifactStoreOneItemPreparation<P, Mutation>: Send {
    fn advance(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemPreparationStep, String>;
    fn checkpoint(&self) -> ArtifactStoreOneItemCheckpoint;
    fn prepared(&self) -> Option<&ArtifactStoreOneItemPrepared<P, Mutation>>;
    fn take_prepared(&mut self) -> Option<ArtifactStoreOneItemPrepared<P, Mutation>>;
    fn cancel(&mut self);
    fn begin_close(&mut self);
    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>;
    fn terminal_is_empty(&self) -> bool;
}

/// 🏭️ Exact app-owned factory. `preflight` must not allocate, copy the mutation, or retain
/// the supplied references; `begin` receives ownership only after the declared footprint passes.
pub trait ArtifactStoreOneItemPreparationFactory<P, Mutation>: Send + Sync {
    fn preflight(&self, mutation: &Mutation, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String>;
    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, Mutation>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, Mutation>>;

    /// 🕰️ Declares a server-derived publication clock the factory will stamp on its prepared edit,
    /// so the Store mints the authority at that exact tick instead of its own wall-clock one. A
    /// factory that returns `None` keeps the Store's clock, which is what every local gesture wants.
    fn stamped_clock(&self) -> Option<HybridLogicalTimestamp> {
        None
    }

    /// 🔏 Declares the server-derived mutation identity the factory will stamp on its prepared edit.
    /// A stamped publication is hashed into a durable decision under this exact identity before the
    /// Store ever sees it, so the Store must publish under it rather than mint its own — otherwise
    /// the committed edit carries an identity no verifier can bind to the approval it executed.
    /// `None` keeps the Store's content-addressed mint, which is what every local gesture wants.
    fn stamped_mutation_id(&self) -> Option<MutationId> {
        None
    }
}

//#region 🧺️BatchSource
