    assert_paged_route_admits(&AppCommand::MediaOut { seq: 15, port: "vector:out".to_string(), request: Vec::new() }).await;
    assert_paged_route_admits(&AppCommand::MediaFingerprint { seq: 16, port: "camera".to_string() }).await;
}

