    drawing_factory: Option<Arc<dyn super::ArtifactStoreOneItemPreparationFactory<DrawingP, DrawingMutation>>>,
    value_factory: Option<Arc<dyn super::ArtifactStoreOneItemPreparationFactory<ValueP, ValueMutation>>>,
