impl dsl::ToValue for CapabilityToken {
    fn to_value(&self) -> DslValue {
        DslValue::String(self.0.to_string())
    }
}
impl dsl::FromValue for CapabilityToken {
    fn from_value(value: DslValue) -> Result<Self, dsl::ValueError> {
        match value {
            DslValue::String(s) => s.parse().map(CapabilityToken).map_err(|_| dsl::ValueError::new(dsl::ValueRefusalKind::InvalidValue, format!("expected a u128 decimal string for CapabilityToken, found {s:?}"))),
            other => Err(dsl::ValueError::new(dsl::ValueRefusalKind::InvalidValue, format!("expected a string for CapabilityToken, found {other:?}"))),
        }
    }
}

