        match self {
            Self::Schema { .. } => "schema",
            Self::Dimensions { .. } => "dimensions",
            Self::FrameRate { .. } => "frameRate",
            Self::Empty => "empty",
            Self::TooLong { .. } => "tooLong",
            Self::Timeline { .. } => "timeline",
            Self::PathVerbs { .. } => "pathVerbs",
            Self::ImageUrl { .. } => "imageUrl",
            Self::PathIndex { .. } => "pathIndex",
            Self::ImageIndex { .. } => "imageIndex",
