//#region 🔖️FaultNotices
/// 📣️ The localized notice of a refused dispatch (design §20.12): the code it was told under and its text in one shell
/// axis pair.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FaultNotice {
    pub code: String,
    pub text: String,
}

/// 📣️ The notice a fault earns: its own code, then each cause's, is looked up in the framework's table
/// ([`HISTORY_NOTICE_LABELS`]) first and the refusing app's published table (`AppDefinition::fault_notices`) second; the
/// first declared code decides, its `{name}` placeholders filled from `Fault.params` only. `None` when no code is declared
/// or a placeholder has no value — the shell then shows its generic refusal, never a raw code. Corpus
/// `🛂️manifest/🧫️fixtures/🧫️fault-notices`; TS twin `faultNotice`.
pub fn fault_notice(fault: &Fault, notices: &[crate::manifest::FaultNoticeDefinition], terminology: semio_framework_ui_locale::Terminology, locale: semio_framework_ui_locale::Locale) -> Option<FaultNotice> {
    let params = fault.params.as_deref();
    let code = std::iter::once(&fault.code).chain(fault.causes.iter().filter_map(|cause| cause.code.as_ref())).map(|code| code.0.as_str()).find(|code| history_notice(code).is_some() || notices.iter().any(|notice| notice.code == *code))?;
    let text = match history_notice(code) {
        Some((en, de)) => crate::manifest::fill_fault_notice(semio_framework_ui_locale::LocalizedLabel::native(en, de).resolve(terminology, locale), params),
        None => crate::manifest::fault_notice_text(notices, code, params, terminology, locale),
    }?;
    Some(FaultNotice { code: code.to_string(), text })
}

