        pub fn namespace(&self) -> &ArtifactIdentityNamespace {
            &self.namespace
        }

        /// 🧭️ Returns the exact identity value; MIME and extension values are deliberately not rewritten.
        pub fn value(&self) -> &str {
            &self.value
        }
    }

