    //#region 🔖️InteractionConfig
    /// 🐁️ The ephemeral, never-persisted half of the interaction mechanism — `VcsArtifactApp`'s hover
    /// map, one `DomainHover` per domain (mirrors `protocol::InteractionState.hover`'s own shape; see
    /// that field's doc for why one slot per domain, not per channel). Deliberately a plain type alias,
    /// not a generic `TransientStore<P, M>` instance: hover here is applied directly by the interaction
    /// dispatch interception, never through an app's own `Emit`/ephemeral lane, so the `Mutation`-trait
    /// machinery `TransientStore` requires would be unused ceremony.
    pub type InteractionHoverState = BTreeMap<String, protocol::DomainHover>;

    pub use crate::local_interaction::mutations::{InteractionConfigMutation, SetInteractionState};

    impl InteractionConfigMutation {
        pub fn set_state(state: protocol::InteractionState) -> Self {
            Self::SetInteractionState(SetInteractionState { state })
        }
    }

    /// 🕹️ `MutationDiff`'s supertrait bound — a "no-op" default, never dispatched as a real mutation
    /// (only `apply`/`absorb` are ever called on a diff value; a `Self::Diff` is never itself the
    /// starting point of a fresh mutation).
    impl Default for InteractionConfigMutation {
        fn default() -> Self {
            InteractionConfigMutation::set_state(protocol::InteractionState::default())
        }
    }

    impl ::protocol::MutationDiff<protocol::InteractionState> for InteractionConfigMutation {
        fn apply(&self, _base: &protocol::InteractionState) -> protocol::MutationApplyResult<protocol::InteractionState> {
            let InteractionConfigMutation::SetInteractionState(state) = self;
            state.apply()
        }
        fn absorb(&mut self, other: Self) {
            *self = other;
        }
    }

    impl ::protocol::OpText for InteractionConfigMutation {
        fn print_op(&self) -> String {
            let InteractionConfigMutation::SetInteractionState(state) = self;
            format!("set-interaction-state {}", semio_framework_pack_json::to_json_string(state))
        }
        fn parse_op(line: &str) -> Result<Self, ::semio_framework_diagnostic::TextError> {
            let body = line
                .strip_prefix("set-interaction-state ")
                .ok_or_else(|| ::semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("unknown interaction config op '{line}'"), ::semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            let state: protocol::InteractionState = semio_framework_pack_json::from_json_str(body, semio_framework_pack_json::JsonMemberPolicy::Reject)
                .map_err(|error| ::semio_framework_diagnostic::TextError::from_value_error(error, ::semio_framework_diagnostic::TextSpan::at(1, 1)))?;
            Ok(InteractionConfigMutation::set_state(state))
        }
    }

    impl ::protocol::OpBinary for InteractionConfigMutation {
        fn encode_op(&self) -> Result<Vec<u8>, ::protocol::ProtocolError> {
            let InteractionConfigMutation::SetInteractionState(state) = self;
            Ok(semio_framework_pack_json::to_json_string(state).into_bytes())
        }
        fn decode_op(bytes: &[u8]) -> Result<Self, ::protocol::ProtocolError> {
            let text = std::str::from_utf8(bytes).map_err(|error| ::protocol::ProtocolError::Malformed { what: "interaction-config-mutation", offset: 0, detail: error.to_string() })?;
            let state: protocol::InteractionState = semio_framework_pack_json::from_json_str(text, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| ::protocol::ProtocolError::Malformed {
                what: "interaction-config-mutation",
                offset: 0,
                detail: error.to_string(),
            })?;
            Ok(InteractionConfigMutation::set_state(state))
        }
    }
    //#endregion 🔖️InteractionConfig

    //#region 🔖️CommandLog
    /// 🎚️ Tri-state operations filter of the framework history panel — `All` is the default.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub enum HistoryCommandFilter {
        #[default]
        All,
        WithoutMutations,
        OnlyMutations,
    }

    /// ⏪️ A stored, replayable inverse for a `View`/`🐚️Shell`-kind command — the memory-only
    /// counterpart to a VCS edit's `Mutation::inverse`. `action_id` is a plugin action id (`View` rows —
    /// replayed locally via `dispatch_action`) or a shell command id (`🐚️Shell` rows — bubbled out as
    /// `Effect::ReplayShellCommand` since the plugin has no access to shell-owned state). Never
    /// persisted: it lives only on the in-memory `CommandLogEntry`/`CommandView`.
    #[derive(Clone, Debug, PartialEq)]
    pub struct InverseAction {
        pub action_id: String,
        pub args: Option<DslValue>,
    }

    /// ⏪️ One undone shell row waiting on the redo stack — chrome-order counterpart to VCS redo.
    struct ShellHistoryReplay {
        seq: u64,
        redo: InverseAction,
    }

    /// 🗝️ What a backfilled command-log row references: a document edit (with the verb that authored it) or a
    /// `Supersede` history transition.
    enum CommandLogAppendKey {
        Edit { edit_id: String, verb: Option<String>, child_edit_ids: Vec<String> },
        Members { edit_ids: Vec<String> },
        Transition(String),
    }

    /// 🏷️ A backfilled edit row's label: the registry label of the verb that authored it, else its first operation's label
    /// `first` (a document leaf's localized `SemanticMutation::label`) — the rule a live row records; an edit without
    /// operations is named by its id. An edit's stored description is never a label (design §20.6).
    fn backfilled_edit_label<Mu>(edit: &protocol::Edit<Mu>, verb_label: Option<LocalizedLabel>, first: impl FnOnce(&Mu) -> LocalizedLabel) -> LocalizedLabel {
        verb_label.unwrap_or_else(|| edit.forwards.first().map_or_else(|| LocalizedLabel::data(edit.id.clone()), first))
    }

    /// 🧾️ Inputs for one appended session command before its sequence and timestamp are assigned.
    struct CommandLogAppend<'a> {
        action_id: &'a str,
        label: LocalizedLabel,
        kind: ActionKind,
        edit_id: Option<String>,
        transition_id: Option<String>,
        timestamp: Option<String>,
        inverse: Option<InverseAction>,
    }

    /// 🧾️ One appended session-command record — runtime-only, never persisted (the VCS envelope
    /// is the persisted half; see `CommandView::op_lines`, derived live from `envelope.vcs.edits`).
    /// Append-only: `VcsArtifactApp` only ever pushes to `command_log`, including for undo/redo.
    #[derive(Clone, Debug, PartialEq)]
    pub struct CommandLogEntry {
        pub seq: u64,
        pub action_id: String,
        pub label: LocalizedLabel,
        pub kind: ActionKind,
        pub timestamp: String,
        /// 🔗️ Set iff this command created/amended a DOCUMENT VCS edit — `None` for pure cursor motion (undo/redo/revert).
        /// A config-lane edit is never a history row (design §20.13, L4), so no row carries one and a config-only dispatch
        /// records nothing.
        pub edit_id: Option<String>,
        /// 🧩️ UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM (C1): every CHILD document edit id this command's composite `dispatch_group`
        /// call produced — one entry per touched CHILD member of a single group dispatch (never folded — a group dispatch
        /// always issues a plain `Apply`, see `Emit::child_emits`'s own doc comment).
        pub child_edit_ids: Vec<String>,
        /// ✏️ Set iff this row is a `Supersede` history transition of the DOCUMENT store's event log (a history edit, or
        /// the undo or redo of one) — backfilled from the transitions, never from a live dispatch, so local, remote and
        /// reloaded history edits are rows alike (`VcsArtifactApp::backfill_command_log`).
        pub transition_id: Option<String>,
        /// 🔢️ How many consecutive identical `View`/`🐚️Shell` dispatches folded into this one row —
        /// see `VcsArtifactApp::record_command`. Always `1` for `Mutation`/`History`/`Clipboard` entries
        /// and for anything carrying an `edit_id`, which never fold.
        pub count: u32,
        /// ⏪️ A real inverse for a `🐚️Shell`-kind row with no `edit_id`
        /// (`noteShellCommand`-authored — shell-owned state this plugin cannot touch itself) — see
        /// `InverseAction`. `None` means this row has no working inverse (not just unauthored/foreign),
        /// which is the normal case for chrome the shell notes without declaring `inverseCommandId`
        /// (window activation/resize/move): such a row is logged but is never an undo target, so `undo`
        /// reaches the user's own document edit instead of replaying chrome into the guest.
        pub inverse: Option<InverseAction>,
    }

    /// 🧾️ One row of the merged command+operation timeline handed to renderers — `CommandLogEntry`
    /// plus everything derived live from the current `envelope.vcs.edits` state.
    #[derive(Clone, Debug, PartialEq)]
    pub struct CommandView {
        pub seq: u64,
        pub action_id: String,
        pub label: LocalizedLabel,
        pub kind: ActionKind,
        pub timestamp: String,
        pub edit_id: Option<String>,
        /// 🧩️ Verbatim `CommandLogEntry::child_edit_ids` — see that field's own doc comment.
        pub child_edit_ids: Vec<String>,
        /// ✏️ Verbatim `CommandLogEntry::transition_id`; such a row's label, `applied` and `revertible` derive from the
        /// supersede ledger (`SupersedeLedger`).
        pub transition_id: Option<String>,
        /// 🖋️ The actor who authored this row's document edit or history transition.
        pub author: Option<String>,
        /// 📜️ The LAST [`HISTORY_ROW_OPERATION_PREVIEW`] forward operations of this entry's edit, printed via
        /// `OpText::print_op`, newest last — a bounded preview, so reading the history costs the same per key at the end of a
        /// long coalesced typing run as at its start; empty for cursor-motion entries and for a dangling `edit_id` (document
        /// replaced mid-session).
        pub op_lines: Vec<String>,
        /// 🔢️ Forward operations of this entry's edit when `op_lines` was printed — a sealed row's preview is reused only while
        /// its edit still has exactly that many.
        pub op_count: usize,
        /// ✅️ The linked DOCUMENT edit is currently on the applied stack (`false` once undone) —
        /// `false` (not meaningful) for a row with no `edit_id`.
        pub applied: bool,
        /// ⏪️ Either (document edit-linked) `applied` AND authored by the local actor, (config
        /// edit-linked) the config edit is similarly applied+local, (child edit-linked) one of this
        /// row's `child_edit_ids` is a live child's TAIL applied edit, or (memory-only) this row
        /// carries a stored `inverse` — only these entries offer "inverse".
        pub revertible: bool,
        /// 🔢️ See `CommandLogEntry::count`.
        pub count: u32,
        /// ⏪️ See `CommandLogEntry::inverse`.
        pub inverse: Option<InverseAction>,
        /// 🛠️ The committed tool transaction this row's edit carries (`MutationMeta.transaction` of its first op).
        pub transaction: Option<protocol::TransactionRef>,
        /// ✏️ The applied mutations of this row's edit (at most [`HISTORY_ROW_MUTATION_ROWS`]), durable outcomes only;
        /// a history edit overlays its replay on them when projected.
        pub mutations: Vec<MutationView>,
    }

    /// ✏️ One applied mutation of a history row: its replica-independent id, applied position and index in its edit,
    /// localized label (of its effective input), durable outcome and supersession state, and whether history editing
    /// may replace its inputs.
    #[derive(Clone, Debug, PartialEq)]
    pub struct MutationView {
        pub mutation_id: String,
        pub position: u32,
        pub op_index: u32,
        pub label: LocalizedLabel,
        pub worst: Option<semio_framework_diagnostic::Severity>,
        pub messages: Vec<protocol::MutationMessage>,
        pub superseded: bool,
        pub withdrawn: bool,
        pub editable: bool,
        pub store: Option<String>,
    }

    /// 📜️ Operations a history row previews: its edit's newest ones (see `CommandView::op_lines`).
    pub const HISTORY_ROW_OPERATION_PREVIEW: usize = 8;

    /// 🏷️ A history row labelled by its edit's first leaf: the leaf's own localized label (`SemanticMutation::label`, resolved
    /// at projection time so a reload keeps every locale), with `(+N)` for the edit's other operations.
    // 🚫️async: a pure label composition.
    pub fn history_leaf_row_label(leaf: &LocalizedLabel, op_count: usize) -> LocalizedLabel {
        let (leaf, more) = (leaf.clone(), op_count.saturating_sub(1));
        LocalizedLabel::from_fn(move |terminology, locale| {
            let first = leaf.resolve(terminology, locale);
            if more > 0 {
                format!("{first} (+{more})")
            } else {
                first.to_string()
            }
        })
    }

    /// ⏳️ The fault code every verb but a view verb answers while a whole-document load still runs (gap N17); its en/de
    /// notice is the kernel's `history_notice("document.loading")`.
    pub const DOCUMENT_LOADING_CODE: &str = "document.loading";

    /// 🫥️ The fault code of a history verb, a history query or a history-carrying document lane on a head-only pure
    /// evaluation (`📓️api-stepped-document-load.md` §4); its en/de notice is the kernel's
    /// `history_notice("pure.history-unavailable")`.
    pub const PURE_HISTORY_UNAVAILABLE_CODE: &str = "pure.history-unavailable";

    /// 📚️ The framework's catalogue route: `setActiveExample` of an app that declares no such action loads the app's
    /// catalogue document ([`ArtifactApp::catalogue_example_document`]).
    pub const CATALOGUE_EXAMPLE_ACTION_ID: &str = "setActiveExample";

    /// 🏷️ The framework's own label, in every shell locale, of a runtime verb no app declares (design §20.6): a history row
    /// the runtime records for it never reads a hand-written description. `None` for every other verb.
    // 🚫️async: a pure label lookup.
    pub fn runtime_verb_label(verb: &str) -> Option<LocalizedLabel> {
        match verb {
            CATALOGUE_EXAMPLE_ACTION_ID => Some(LocalizedLabel::native("Load example", "Beispiel laden")),
            _ => None,
        }
    }

    /// 🎯️ The leaf label of a tool transaction's history row (design §19.1): the first of the edit's applied `ops` whose kind
    /// the authoring `tool` declares as its intent ([`ArtifactApp::tool_intent_kinds`]), read from its mutation row in
    /// `mutations` (its effective input) or labelled afresh when that row is windowed out; `None` when the tool declares no
    /// kind any operation has, so the first leaf labels the row as before.
    // 🚫️async: a pure lookup over the projected operations.
    pub fn history_intent_label<A: ArtifactApp>(tool: &str, ops: &[&store::AppliedMutation<'_, A::Mutation>], mutations: &[MutationView]) -> Option<LocalizedLabel> {
        let intents = A::tool_intent_kinds(tool);
        let intent = ops.iter().take(if intents.is_empty() { 0 } else { ops.len() }).find(|op| intents.contains(&protocol::SemanticMutation::<A::Snapshot>::semantics(op.operation).kind))?;
        Some(mutations.iter().find(|row| row.mutation_id == intent.mutation_id.0).map_or_else(|| time_travel::time_travel_mutation_label::<A>(intent.operation), |row| row.label.clone()))
    }

    /// 🙈️ Whether a dispatch of `kind` is a history row: never an interaction verb, and a `View` only when it edited a
    /// store (`edited`) or carries an inverse — a pure view verb changes no history and undo cannot reach it.
    // 🚫️async: a pure total predicate over the dispatch's own facts.
    pub fn history_row_is_recorded(kind: ActionKind, edited: bool, inverse: bool) -> bool {
        match kind {
            ActionKind::Interaction => false,
            ActionKind::View => edited || inverse,
            ActionKind::Mutation | ActionKind::History | ActionKind::Clipboard | ActionKind::Shell => true,
        }
    }

    /// 📜️ Checkpoint/alternative history summary for this viewer — the swimlane columns, the
    /// undo/redo availability, this viewer's head, and the merged command+operation timeline.
    /// `active_alternative_id` and `current_checkpoint_id` are this replica's head. `alternatives`
    /// stays the shared registration. Built once per store generation.
    #[derive(Clone, Debug, PartialEq)]
    pub struct HistoryView {
        pub columns: Vec<HistoryColumn>,
        pub can_undo: bool,
        pub can_redo: bool,
        /// 👁 The alternative this viewer is on. `None` is the canonical trunk.
        pub active_alternative_id: Option<String>,
        /// 🌿️ Every alternative of the artifact's history, in declaration order ([`history_alternative_views`]).
        pub alternatives: Vec<AlternativeView>,
        /// 👁 The checkpoint this viewer is looking at: the tip of the active line, or an explicit checkout.
        pub current_checkpoint_id: Option<String>,
        /// 📜️ The session command log merged with live VCS op-text, newest first. Every edit in
        /// `envelope.vcs.edits` is referenced by exactly one entry (see `VcsArtifactApp::backfill_command_log`).
        pub commands: Vec<CommandView>,
        pub command_filter: HistoryCommandFilter,
    }

    impl HistoryView {
        /// 🕳️ An empty view for hand-built test/fixture `ArtifactView`s that don't exercise history.
        pub fn empty() -> Self {
            Self { columns: Vec::new(), can_undo: false, can_redo: false, active_alternative_id: None, alternatives: Vec::new(), current_checkpoint_id: None, commands: Vec::new(), command_filter: HistoryCommandFilter::default() }
        }
    }

    /// 🌿️ One alternative of the artifact's history as the history body lists it: its id and name, whether it is the
    /// current one, who branched it and when (its `Branch` transition's actor and HLC wall time as RFC 3339 UTC; `None`
    /// when the log holds no branch of it) and whether history edits were kept as it (scoped `Supersede` transitions).
    #[derive(Clone, Debug, PartialEq)]
    pub struct AlternativeView {
        pub id: String,
        pub name: String,
        pub current: bool,
        pub author: Option<String>,
        pub branched_at: Option<String>,
        pub edited: bool,
    }

    /// 🧾️ One history transition as the alternatives list reads it: a branch naming its alternative, author and wall
    /// time, or a supersession with its scope.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum AlternativeFact<'a> {
        Branch { alternative_id: &'a str, actor: &'a str, physical_ms: u64 },
        Supersede { scope: Option<&'a str> },
    }

    /// 🌿️ The alternatives list of the history body over `(id, name)` pairs in declaration order (the trunk first, with the
    /// empty name the history body localizes) and the log's `facts` in HLC order: current when it is the `active` line,
    /// authored by the first branch naming it, edited when a supersession is scoped to it. Twin: `🧪️tests/🧪️history-alternatives/🟦️.ts` over `🧫️fixtures/🧫️history-alternatives/🔣️.json`.
    // 🚫️async: a pure projection over already-decoded facts.
    pub fn history_alternative_views<'a>(alternatives: impl IntoIterator<Item = (&'a str, &'a str)>, active: Option<&str>, facts: &[AlternativeFact<'_>]) -> Vec<AlternativeView> {
        alternatives
            .into_iter()
            .map(|(id, name)| {
                let branch = facts.iter().find_map(|fact| match fact {
                    AlternativeFact::Branch { alternative_id, actor, physical_ms } if *alternative_id == id => Some((*actor, *physical_ms)),
                    _ => None,
                });
                AlternativeView {
                    id: id.to_string(),
                    name: name.to_string(),
                    current: active == Some(id),
                    author: branch.map(|(actor, _)| actor.to_string()),
                    branched_at: branch.map(|(_, physical_ms)| protocol::scalar::format_rfc3339_ms(i64::try_from(physical_ms).unwrap_or(i64::MAX))),
                    edited: facts.iter().any(|fact| matches!(fact, AlternativeFact::Supersede { scope: Some(scope) } if *scope == id)),
                }
            })
            .collect()
    }
    //#endregion 🔖️CommandLog

    //#region 🔖️HistoryPanel
    /// 📌️ The framework-reserved controller the explicit check-in dialog funnel answers on — the
    /// shell-owned twin of `framework.sync`: a renderer intercepts it before any app sees it
    /// (`🐚️Shell/🎯️targets/🧊️/🦀️.rs`'s `dispatch_action`), because the check-in MESSAGE is shell state
    /// no artifact app holds.
    pub const FRAMEWORK_CHECKIN_CONTROLLER_ID: &str = "framework.checkin";

    /// 📌️ Uncommitted-since-the-last-checkpoint count — the same fold the React shell's
    /// `uncommittedEditCount` (`🏛️ShellHost/🟦️.tsx`) applies, walked OLDEST-first over a
    /// newest-first command log: every applied mutation row counts, and a landed `commitCheckpoint`
    /// resets it to zero. It is what React prints after the Check In label as ` (N)`.
    // 🚫️async: a pure total fold over rows already in hand.
    fn uncommitted_command_count(history: &HistoryView) -> u32 {
        let mut pending = 0u32;
        for entry in history.commands.iter().rev() {
            if entry.kind == ActionKind::History && entry.action_id == "commitCheckpoint" {
                pending = 0;
                continue;
            }
            if entry.kind == ActionKind::Mutation && entry.applied {
                pending += 1;
            }
        }
        pending
    }

    // 🚫️async: a pure total mapping, called inside the Commands window's synchronous row closure.
    /// 🕶️ View is ephemeral cursor/selection/camera state; Shell is an outside-the-document
    /// host effect — distinct icons so a folded ×count row reads at a glance.
    fn history_panel_icon_id(kind: ActionKind) -> IconName {
        match kind {
            ActionKind::Mutation => IconName::Pencil,
            ActionKind::History => IconName::Undo,
            ActionKind::Clipboard => IconName::Clipboard,
            ActionKind::View => IconName::Eye,
            ActionKind::Shell => IconName::Monitor,
            ActionKind::Interaction => "mouse-pointer".into(),
        }
    }

    /// 🕰️ Builds the framework's history panel body from a `HistoryView` as a pure side-panel
    /// `Tree` (same shape as Document/Catalogue): an Actions section (undo/redo/checkpoint/alternative +
    /// filter control) and a Commands section of newest-first rows with optional "inverse" revert.
    /// Shared by both renderers — `VcsArtifactApp::render` returns this verbatim for
    /// `FRAMEWORK_HISTORY_BODY_KEY`. `read_only` is contract §2.3 clause 3 (`VcsArtifactApp::render`
    /// passes `A::ROLE == AppRole::Viewer`): every mutating action row renders disabled and the
    /// per-command "Backwards" revert action is omitted entirely, regardless of `can_undo`/`can_redo`
    /// or `entry.revertible` — the filter control and Commands list themselves stay fully live, since
    /// browsing history is not a mutation.
    ///
    /// 🪟️ The Commands section is a windowed container ([`tree_window_section`]) keyed
    /// `framework.history.commands` under body [`FRAMEWORK_HISTORY_BODY_KEY`]: it stamps the full live
    /// filtered row count as its `TreeWindow::total` and materialises only the slice the host asked
    /// for through `ViewModel::tree_windows` (one viewport on a cold paint). A session log of any
    /// length therefore assembles, the scrollbar spans it all, and there is no `+N` row and no guest
    /// page cursor.
    ///
    /// 📌️ `#s-checkin` — React's EXPLICIT check-in row (`🏛️ShellHost/🟦️.tsx`'s
    /// `framework.history.checkin`), a separate affordance from the no-message quick Checkpoint
    /// above and absent outright for a viewer (never disabled — React's own `canCheckIn` gate,
    /// whose wgpu twin is `can_check_in`, and which `read_only` carries here). The button keeps
    /// React's bare `s-checkin` id: it is the id every battery and probe looks for, and it had no
    /// trigger anywhere on the wgpu target at all (`📓️audit-w14-shell-residual.md` C2).
    ///
    /// ⚠️ React's press OPENS a message dialog whose typed text rides the checkpoint; the message
    /// is shell-local state this assembler cannot see, so the row dispatches `submit` directly and
    /// the shell falls back to its own `"check-in"` message (React's own blank-draft fallback).
    ///
    /// ⏪️ While a history edit is open (`time_travel`), the body leads with the session band
    /// (`framework.history.timeTravel`) and, while a mutation is being edited, its draft editor
    /// (`framework.history.editor` and its unwindowed inputs), then the alternatives, the actions and the commands;
    /// otherwise the actions lead, then the alternatives and the commands. The history-lane actions and the per-row
    /// revert are frozen during the edit, and every row's mutations carry the session overlay (replay outcome,
    /// pending, edited).
    ///
    /// ↩️ Undo is enabled exactly where its chord and palette entry are: for every editor outside a history edit. The
    /// host routes an `undo` to a remote (inference) history it owns, which this guest cannot see, and an undo with
    /// nothing to undo is a benign no-op; `can_undo` therefore never disables it here.
    ///
    /// ✏️ A row with applied mutations is a tree window over ALL of them (gap N1): its projected ones first (the flagged
    /// ones leading), then every other operation of its edit in op order, read from `pages` for the slice a host window
    /// opened past the projection ([`time_travel::history_row_mutation_extent`]). Each child carries its label, a
    /// description naming its state and severity in words (colour is never the only carrier), tone and icon by severity,
    /// and an Edit row action (`historyEditBegin{mutationId}`, also the row's activation) when it is editable and this is
    /// not a viewer — disabled, naming why, wherever the session would refuse `Begin` (gap N15).
    pub async fn ui_history_panel(
        history: &HistoryView,
        time_travel: Option<&TimeTravelPanel>,
        reprojection: Option<&semio_framework::kernel::HistoryReprojection>,
        pages: &HistoryMutationPages,
        controller_id: &str,
        locale: Locale,
        read_only: bool,
        view: &ViewModel,
    ) -> UiAssemblyResult<BuiltNode> {
        let frozen = time_travel.is_some();
        let text_of = |text: time_travel::HistoryPanelText| text.text(locale);
        let action_item = |id: &str, icon_id: IconName, label: &str, action: &str, enabled: bool| -> UiAssemblyResult<BuiltNode> {
            let action = ActionId::try_v1(controller_id, action).ok_or_else(|| ui_assembly_error("history-panel.action-id"))?;
            let button_id = UiText::try_format(format_args!("{id}.run")).ok_or_else(|| ui_assembly_error("history-panel.button-id"))?;
            let icon = ui_text(icon_id.as_str(), "history-panel.icon")?;
            let builder = button(ui_label(label, "history-panel.button-label")?).icon(icon.clone()).disabled(!enabled);
            let builder = builder.try_id(&button_id).map_err(|_| ui_assembly_error("history-panel.button-id"))?;
            let button = builder.try_on(Trigger::Activate, action).map_err(|_| ui_assembly_error("history-panel.button-binding"))?.try_build().map_err(|_| ui_assembly_error("history-panel.button-build"))?;
            let builder = ui::tree_item(ui_label(label, "history-panel.item-label")?).icon(icon).disabled(!enabled);
            let builder = builder.try_id(id).map_err(|_| ui_assembly_error("history-panel.item-id"))?;
            let builder = builder.try_child(button).map_err(|_| ui_assembly_error("history-panel.item-child"))?;
            builder.try_build().map_err(|_| ui_assembly_error("history-panel.item-build"))
        };

        let filter_value = match history.command_filter {
            HistoryCommandFilter::All => "all",
            HistoryCommandFilter::WithoutMutations => "withoutMutations",
            HistoryCommandFilter::OnlyMutations => "onlyMutations",
        };
        let mut filter_builder = select(ui_text(filter_value, "history-panel.filter-value")?);
        for (value, label) in [("all", time_travel::HistoryPanelText::FilterAll), ("withoutMutations", time_travel::HistoryPanelText::FilterWithoutMutations), ("onlyMutations", time_travel::HistoryPanelText::FilterOnlyMutations)] {
            filter_builder = filter_builder.try_item(ui_text(value, "history-panel.filter-item-value")?, ui_label(text_of(label), "history-panel.filter-item-label")?).map_err(|_| ui_assembly_error("history-panel.filter-items"))?;
        }
        let filter_builder = filter_builder.try_id("framework.history.filter.control").map_err(|_| ui_assembly_error("history-panel.filter-id"))?;
        let filter_builder = filter_builder.try_label(text_of(time_travel::HistoryPanelText::Filter)).map_err(|_| ui_assembly_error("history-panel.filter-label"))?;
        let filter_action = ActionId::try_v1(controller_id, SET_HISTORY_COMMAND_FILTER_ACTION_ID).ok_or_else(|| ui_assembly_error("history-panel.filter-action"))?;
        let filter_select = filter_builder.try_on(Trigger::Change, filter_action).map_err(|_| ui_assembly_error("history-panel.filter-binding"))?.try_build().map_err(|_| ui_assembly_error("history-panel.filter-build"))?;
        let filter_builder = ui::tree_item(ui_label(text_of(time_travel::HistoryPanelText::Filter), "history-panel.filter-label")?).icon(ui_text(IconName::Filter.as_str(), "history-panel.filter-icon")?);
        let filter_builder = filter_builder.try_id("framework.history.filter").map_err(|_| ui_assembly_error("history-panel.filter-item-id"))?;
        let filter_item = filter_builder.try_child(filter_select).map_err(|_| ui_assembly_error("history-panel.filter-child"))?.try_build().map_err(|_| ui_assembly_error("history-panel.filter-item-build"))?;

        let command_rows: Vec<&CommandView> = history
            .commands
            .iter()
            .filter(|entry| match history.command_filter {
                HistoryCommandFilter::All => true,
                HistoryCommandFilter::WithoutMutations => entry.edit_id.is_none(),
                HistoryCommandFilter::OnlyMutations => entry.edit_id.is_some(),
            })
            .collect();
        let windows = TreeWindows::for_body(view, FRAMEWORK_HISTORY_BODY_KEY);
        let commands_section = tree_window_section(&windows, time_travel::HISTORY_COMMANDS_SECTION_KEY, ui_label(text_of(time_travel::HistoryPanelText::Commands), "history-panel.commands-label")?, true, &command_rows, |entry| {
            let entry_label = entry.label.resolve(Terminology::Native, locale);
            let label = if entry.count > 1 { UiText::clipped(&format!("{entry_label} x{}", entry.count)) } else { UiText::clipped(entry_label) };
            let id = UiText::try_format(format_args!("{}{}", time_travel::HISTORY_ROW_KEY_PREFIX, entry.seq)).ok_or_else(|| ui_assembly_error("history-panel.command-id"))?;
            let mutations: Vec<semio_framework::kernel::HistoryMutationEntry> = entry.mutations.iter().map(|mutation| history_mutation_entry(mutation, time_travel)).collect();
            let worst = mutations.iter().filter_map(|mutation| mutation.worst).max();
            let mut builder = ui::tree_item(Label(label)).icon(ui_text(history_panel_icon_id(entry.kind).as_str(), "history-panel.command-icon")?);
            builder = builder.try_id(&id).map_err(|_| ui_assembly_error("history-panel.command-id"))?;
            let mut description = if entry.mutations.is_empty() { entry.op_lines.join(" \u{b7} ") } else { String::new() };
            if let Some(worst) = worst {
                let severity = time_travel::history_severity_text(worst, locale);
                description = if description.is_empty() { severity.to_string() } else { format!("{severity} \u{b7} {description}") };
                builder = builder.tone(time_travel::history_severity_tone(Some(worst)).0);
            }
            if let Some(author) = entry.author.as_deref().filter(|_| entry.transition_id.is_some()) {
                description = if description.is_empty() { author.to_string() } else { format!("{author} \u{b7} {description}") };
            }
            if !description.is_empty() {
                builder = builder.description(UiText::clipped(&description));
            }
            if (entry.edit_id.is_some() || entry.transition_id.is_some()) && !entry.applied {
                builder = builder.dimmed(true);
            }
            if entry.revertible && !read_only && !frozen {
                let mut args = UiMapBuilder::try_new().ok_or_else(|| ui_assembly_error("history-panel.row-action-args"))?;
                args.push("entrySeq".to_owned(), UiValue::Number(entry.seq as f64)).map_err(|_| ui_assembly_error("history-panel.row-action-args"))?;
                let revert = row_action(IconName::RotateCcw.as_str(), text_of(time_travel::HistoryPanelText::Backwards), REVERT_TO_COMMAND_ACTION_ID, RowActionPlacement::Menu)?;
                builder = builder.try_row_action(revert).map_err(|_| ui_assembly_error("history-panel.row-actions"))?.target(row_target(controller_id, Some(UiValue::Map(args.finish())), None)?);
            }
            let mut shown: Vec<&semio_framework::kernel::HistoryMutationEntry> = mutations.iter().filter(|mutation| mutation.worst.is_some() || mutation.edited || mutation.superseded).collect();
            shown.extend(mutations.iter().filter(|mutation| mutation.worst.is_none() && !mutation.edited && !mutation.superseded));
            let (projected, total) = time_travel::history_row_mutation_extent(entry);
            if total == 0 {
                return builder.try_build().map_err(|_| ui_assembly_error("history-panel.command-build"));
            }
            let (page, begin_refusal) = (pages.get(&entry.seq), time_travel.and_then(|panel| panel.begin_refusal));
            tree_window_indexed_item(&windows, builder, id.as_str(), time_travel::history_row_opens_by_default(&mutations), total, |index| {
                let paged;
                let mutation = match shown.get(index) {
                    Some(mutation) => *mutation,
                    None => {
                        let view = page.and_then(|page| page.rows.get(index.checked_sub(projected + page.from)?)).ok_or_else(|| ui_assembly_error("history-panel.mutation-page"))?;
                        paged = history_mutation_entry(view, time_travel);
                        &paged
                    }
                };
                history_panel_mutation_row(mutation, controller_id, locale, read_only, begin_refusal)
            })
        })?;

        let checkin_item = if read_only {
            None
        } else {
            let pending = uncommitted_command_count(history);
            let text = text_of(time_travel::HistoryPanelText::CheckIn);
            let text = if pending > 0 { format!("{text} ({pending})") } else { text.to_string() };
            let icon = ui_text(IconName::GitCommit.as_str(), "history-panel.checkin-icon")?;
            let submit = ActionId::try_v1(FRAMEWORK_CHECKIN_CONTROLLER_ID, "submit").ok_or_else(|| ui_assembly_error("history-panel.checkin-action"))?;
            let builder = button(ui_label(text.as_str(), "history-panel.checkin-label")?).icon(icon.clone()).disabled(frozen);
            let builder = builder.try_id("s-checkin").map_err(|_| ui_assembly_error("history-panel.checkin-button-id"))?;
            let trigger = builder.try_on(Trigger::Activate, submit).map_err(|_| ui_assembly_error("history-panel.checkin-binding"))?.try_build().map_err(|_| ui_assembly_error("history-panel.checkin-button-build"))?;
            let builder = ui::tree_item(ui_label(text.as_str(), "history-panel.checkin-item-label")?).icon(icon).disabled(frozen);
            let builder = builder.try_id("framework.history.checkin").map_err(|_| ui_assembly_error("history-panel.checkin-item-id"))?;
            Some(builder.try_child(trigger).map_err(|_| ui_assembly_error("history-panel.checkin-item-child"))?.try_build().map_err(|_| ui_assembly_error("history-panel.checkin-item-build"))?)
        };
        let mutable = !read_only && !frozen;
        let mut action_items = BuiltChildren::default();
        for item in [
            Some(action_item("framework.history.undo", IconName::Undo, text_of(time_travel::HistoryPanelText::Undo), "undo", mutable)?),
            Some(action_item("framework.history.redo", IconName::Redo, text_of(time_travel::HistoryPanelText::Redo), "redo", history.can_redo && mutable)?),
            Some(action_item("framework.history.commitCheckpoint", IconName::GitCommit, text_of(time_travel::HistoryPanelText::CommitCheckpoint), "commitCheckpoint", mutable)?),
            checkin_item,
            Some(action_item("framework.history.createAlternative", IconName::GitBranch, text_of(time_travel::HistoryPanelText::CreateAlternative), "createAlternative", mutable)?),
            Some(filter_item),
        ]
        .into_iter()
        .flatten()
        {
            action_items.try_push(item).map_err(|_| ui_assembly_error("history-panel.actions"))?;
        }
        let actions_builder = tree_section(ui_label(text_of(time_travel::HistoryPanelText::Actions), "history-panel.actions-label")?).default_open(true);
        let actions_builder = actions_builder.try_id("framework.history.actions").map_err(|_| ui_assembly_error("history-panel.actions-id"))?;
        let actions_section = actions_builder.try_children(action_items).map_err(|_| ui_assembly_error("history-panel.actions"))?.try_build().map_err(|_| ui_assembly_error("history-panel.actions-build"))?;
        let alternatives_section = if history.alternatives.is_empty() {
            None
        } else {
            Some(tree_window_section(&windows, "framework.history.alternatives", ui_label(text_of(time_travel::HistoryPanelText::Alternatives), "history-panel.alternatives-label")?, true, &history.alternatives, |alternative| {
                history_panel_alternative_row(alternative, controller_id, locale, mutable)
            })?)
        };
        let mut sections = BuiltChildren::default();
        let remote_section = match reprojection {
            Some(remote) => Some(time_travel::time_travel_reprojection_section(remote, time_travel.is_none() && !read_only, controller_id, locale)?),
            None => None,
        };
        let ordered: Vec<BuiltNode> = match time_travel {
            Some(panel) => {
                let mut session = vec![time_travel::time_travel_band_section(panel, controller_id, locale)?];
                if let Some(editor) = panel.editor.as_ref().filter(|_| !read_only) {
                    session.extend(time_travel::time_travel_editor_sections(panel, editor, &windows, controller_id, locale)?);
                }
                session.into_iter().chain(remote_section).chain(alternatives_section).chain([actions_section, commands_section]).collect()
            }
            None => remote_section.into_iter().chain([actions_section]).chain(alternatives_section).chain([commands_section]).collect(),
        };
        for section in ordered {
            sections.try_push(section).map_err(|_| ui_assembly_error("history-panel.sections"))?;
        }
        tree().try_children(sections).map_err(|_| ui_assembly_error("history-panel.sections"))?.try_build().map_err(|_| ui_assembly_error("history-panel.build"))
    }

    /// 🌿️ One alternative row: its name (the trunk's empty one reads "Main line"), a check icon and "Current" when it is the
    /// current one, who branched it and when,
    /// and "Edited history" when history edits were kept as it; every other alternative switches on activation and by its
    /// Switch row action (`switchAlternative{alternativeId}`) unless the panel is read-only or frozen by a history edit.
    fn history_panel_alternative_row(alternative: &AlternativeView, controller_id: &str, locale: Locale, mutable: bool) -> UiAssemblyResult<BuiltNode> {
        let text = |text: time_travel::HistoryPanelText| text.text(locale);
        let id = UiText::try_format(format_args!("framework.history.alternative.{}", alternative.id)).ok_or_else(|| ui_assembly_error("history-panel.alternative-id"))?;
        let icon = if alternative.current { IconName::Check } else { IconName::GitBranch };
        let name = if alternative.name.is_empty() { text(time_travel::HistoryPanelText::Trunk) } else { alternative.name.as_str() };
        let mut builder = ui::tree_item(Label(UiText::clipped(name))).icon(ui_text(icon.as_str(), "history-panel.alternative-icon")?);
        builder = builder.try_id(&id).map_err(|_| ui_assembly_error("history-panel.alternative-id"))?;
        let mut parts: Vec<String> = Vec::new();
        if alternative.current {
            parts.push(text(time_travel::HistoryPanelText::Current).to_string());
        }
        if let (Some(author), Some(at)) = (alternative.author.as_deref(), alternative.branched_at.as_deref()) {
            let when = at.get(..16).map_or_else(|| at.to_string(), |minute| format!("{} UTC", minute.replacen('T', " ", 1)));
            parts.push(text(time_travel::HistoryPanelText::BranchedBy).replace("{author}", author).replace("{time}", &when));
        }
        if alternative.edited {
            parts.push(text(time_travel::HistoryPanelText::EditedHistory).to_string());
        }
        if !parts.is_empty() {
            builder = builder.description(UiText::clipped(&parts.join(" \u{b7} ")));
        }
        if !alternative.current && mutable {
            let mut args = UiMapBuilder::try_new().ok_or_else(|| ui_assembly_error("history-panel.alternative-args"))?;
            args.push(semio_framework::SWITCH_ALTERNATIVE_ARG_ALTERNATIVE_ID.to_owned(), UiValue::Text(UiText::clipped(&alternative.id))).map_err(|_| ui_assembly_error("history-panel.alternative-args"))?;
            let switch = row_action(IconName::GitBranch.as_str(), text(time_travel::HistoryPanelText::Switch), semio_framework::SWITCH_ALTERNATIVE_ACTION_ID, RowActionPlacement::Row)?;
            builder = builder.try_row_action(switch).map_err(|_| ui_assembly_error("history-panel.alternative-actions"))?.target(row_target(controller_id, Some(UiValue::Map(args.finish())), Some(semio_framework::SWITCH_ALTERNATIVE_ACTION_ID))?);
        }
        builder.try_build().map_err(|_| ui_assembly_error("history-panel.alternative-build"))
    }

    /// ✏️ One mutation child of a history row: label, state-and-severity description in words, tone and icon by
    /// severity, and Edit (`historyEditBegin{mutationId, store?}`, also its activation) when editable and not a viewer —
    /// `store` names the composed member store a child mutation lives in (design §12). While the session would refuse
    /// `Begin` (`begin_refusal`: replaying, choosing, finalizing, or a changed draft still open) the Edit action is disabled
    /// because of that refusal (`RowAction::disabled_because`, announced as its description) and the row's activation fires
    /// nothing (gap N15).
    fn history_panel_mutation_row(mutation: &semio_framework::kernel::HistoryMutationEntry, controller_id: &str, locale: Locale, read_only: bool, begin_refusal: Option<semio_framework_time_travel::TimeTravelRefusal>) -> UiAssemblyResult<BuiltNode> {
        let (tone, icon) = time_travel::history_severity_tone(mutation.worst);
        let icon = if mutation.pending {
            "clock"
        } else if mutation.edited {
            "edit"
        } else {
            icon
        };
        let id = UiText::try_format(format_args!("framework.history.mutation.{}", mutation.mutation_id)).ok_or_else(|| ui_assembly_error("history-panel.mutation-id"))?;
        let mut builder = ui::tree_item(Label(UiText::clipped(mutation.label.resolve(Terminology::Native, locale)))).icon(ui_text(icon, "history-panel.mutation-icon")?).tone(if mutation.worst.is_some() { tone } else { Tone::Neutral });
        builder = builder.try_id(&id).map_err(|_| ui_assembly_error("history-panel.mutation-id"))?;
        let description = time_travel::history_mutation_description(mutation, locale);
        if !description.is_empty() {
            builder = builder.description(UiText::clipped(&description));
        }
        if mutation.pending || mutation.withdrawn {
            builder = builder.dimmed(true);
        }
        if mutation.editable && !read_only {
            let mut args = UiMapBuilder::try_new().ok_or_else(|| ui_assembly_error("history-panel.mutation-args"))?;
            args.push(semio_framework::HISTORY_EDIT_ARG_MUTATION_ID.to_owned(), UiValue::Text(UiText::clipped(&mutation.mutation_id))).map_err(|_| ui_assembly_error("history-panel.mutation-args"))?;
            if let Some(store) = mutation.store.as_deref() {
                args.push(semio_framework::HISTORY_EDIT_ARG_STORE.to_owned(), UiValue::Text(UiText::clipped(store))).map_err(|_| ui_assembly_error("history-panel.mutation-args"))?;
            }
            let edit_text = time_travel::HistoryPanelText::Edit.text(locale);
            let (edit, activation) = match begin_refusal {
                None => (row_action(IconName::Edit.as_str(), edit_text, semio_framework::HISTORY_EDIT_BEGIN_ACTION_ID, RowActionPlacement::Row)?, Some(semio_framework::HISTORY_EDIT_BEGIN_ACTION_ID)),
                Some(refusal) => {
                    let reason = refusal.label().localized(LocalizedLabel::native).resolve(Terminology::Native, locale).to_string();
                    (row_action(IconName::Edit.as_str(), edit_text, semio_framework::HISTORY_EDIT_BEGIN_ACTION_ID, RowActionPlacement::Row)?.disabled_because(ui_label(reason.as_str(), "history-panel.mutation-edit-reason")?), None)
                }
            };
            builder = builder.try_row_action(edit).map_err(|_| ui_assembly_error("history-panel.mutation-actions"))?.target(row_target(controller_id, Some(UiValue::Map(args.finish())), activation)?);
        }
        builder.try_build().map_err(|_| ui_assembly_error("history-panel.mutation-build"))
    }
    //#endregion 🔖️HistoryPanel

    /// 📤️ What a pure `ArtifactApp::handle` emits: zero-or-more typed document operations (applied
    /// through the document store with a true inverse) and zero-or-more typed config operations (applied
    /// through the config store, also with a true inverse via `ConfigMutation::inverse` — the config-op
    /// twin of a document op, replacing the old `ActionEmit::inverse`/`InverseAction` ad hoc self-computed
    /// inverse: a former "View"-kind action now just emits a `ConfigMutation` and gets a real inverse
    /// for free), plus host effects (navigate/export/spawn…) and app events. An emission never labels its edit: the history
    /// row reads its leaves' localized labels (design §20.6). `B1` rename: was `ActionEmit`, `operations` renamed
    /// `artifact_mutations` to sit next to `config_mutations` unambiguously.
    pub struct Emit<Mutation, ConfigMutation = NoConfigMutation, DraftMutation = NoDraftMutation> {
        pub artifact_mutations: Vec<Mutation>,
        pub config_mutations: Vec<ConfigMutation>,
        pub window_config_mutations: Vec<WindowConfigMutation>,
        pub draft_mutations: Vec<DraftMutation>,
        /// 🛠️ The `ToolTransaction` that authored `artifact_mutations`: stamped on every published op as
        /// `MutationMeta.transaction`, so history lists the gesture as one row and edits its yielded mutations.
        /// `None` outside a tool transaction; streamed or aborted only on the app's own document ([`Self::transaction_phase`]). Build it with [`Emit::commit_transaction`],
        /// [`Emit::stream_transaction`] or [`Emit::abort_transaction`].
        pub transaction: Option<protocol::TransactionRef>,
        /// 🎞️ How `artifact_mutations` join `transaction` (design §15): committed as its one edit, streamed into its open
        /// edit, or its open edit aborted.
        pub transaction_phase: TransactionPhase,
        pub effects: Vec<Effect>,
        /// 🔁️ Zero-or-more extension capability invocations whose OUTCOME must come back to this app
        /// — see [`ExtensionInvocation`]. Deliberately NOT expressible through `effects`: the
        /// kernel's `Effect::InvokeExtension` carries a `req` that only the guest request registry
        /// can mint, so this lane exists precisely so an app never writes one. `dispatch_emit` (and
        /// the retained tool-operation publication path) drains it through
        /// `reactor::queue_extension_invocation`, which allocates the id, records the continuation
        /// and queues the effect.
        pub extension_invocations: Vec<ExtensionInvocation>,
        pub events: Vec<AppEvent>,
        /// 🐢️ Which rendered UI sections this action actually invalidates — `Full` (the default) preserves
        /// today's whole-shell-refresh behavior for every app that doesn't opt in to narrower scopes.
        pub ui_scope: UiDirtyScope,
        /// 🧩️ UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM (C1): zero-or-more owned-child edits riding
        /// alongside this SAME gesture — the seam that lets one user action touch a parent AND N of
        /// its composed children as ONE undo step. Never hand-built; always via `ChildEmit::of`, which
        /// captures each op's `SemanticMutation` label/semantics BEFORE `OpBinary`-encoding it, so the
        /// child artifact's own semantic vocabulary survives end-to-end into history instead of being
        /// re-invented as a parent-side "child routing" mutation. `VcsArtifactApp::dispatch_emit`
        /// routes `artifact_mutations` (the parent's own ops) plus every entry here through
        /// `store::CompositionCoordinator::dispatch_group` as one atomic multi-document gesture — see
        /// that method's own doc comment for the two-phase validate/apply protocol.
        pub child_emits: Vec<ChildEmit>,
        /// 🕹️ FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM (26/08/14): zero-or-more app-initiated
        /// selection writes riding alongside this SAME gesture — see [`InteractionWrite`]. Applied
        /// after this emit's own mutation lanes have landed, through the one single-writer path the
        /// reserved interaction verbs already use. Empty by default, so no other app changes.
        pub interaction_writes: Vec<InteractionWrite>,
        /// 🧵️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (design-abi.md §4): zero-or-more tasks
        /// spawned onto this actor's `LocalExecutor` alongside this SAME gesture — `dispatch_emit`
        /// spawns each one (quota-gated, key-deduped) right after the mutation lanes above have
        /// landed, so `TaskCtx.meta` always reflects state that was ACTUALLY committed, never just
        /// requested. This is the ONLY way a command handler can await anything: `handle` itself
        /// stays a pure synchronous reducer (see `AsyncTask`'s own doc for the full contract).
        pub tasks: Vec<AsyncTask<Mutation, ConfigMutation, DraftMutation>>,
    }

    /// 🎞️ How an emission's artifact mutations join its tool transaction (design §15, transaction-scoped amend). `Commit`
    /// records them as the transaction's one edit — closing the transaction's open edit when earlier ticks streamed into it.
    /// `Stream` appends them to the transaction's open edit (the first tick opens it) and keeps it open: the store folds it
    /// as its applied tail, but nothing is announced or persisted before the commit. `Abort` reverts the open edit with zero
    /// trace.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub enum TransactionPhase {
        #[default]
        Commit,
        Stream,
        Abort,
    }

    /// ✋️ A released node drag's emission (`semio_framework_tool_machine::node_drag_emit`): ONE committed tool transaction,
    /// a plain edit for a view without command authority, or nothing.
    impl<Mutation, ConfigMutation, DraftMutation> From<semio_framework_tool_machine::NodeDragEmit<Mutation>> for Emit<Mutation, ConfigMutation, DraftMutation> {
        fn from(drag: semio_framework_tool_machine::NodeDragEmit<Mutation>) -> Self {
            match drag {
                semio_framework_tool_machine::NodeDragEmit::Commit(transaction, artifact_mutations) => Self::commit_transaction(transaction, artifact_mutations),
                semio_framework_tool_machine::NodeDragEmit::Plain(artifact_mutations) => Self::mutations(artifact_mutations),
                semio_framework_tool_machine::NodeDragEmit::Nothing => Self::default(),
            }
        }
    }

    impl<Mutation, ConfigMutation, DraftMutation> Default for Emit<Mutation, ConfigMutation, DraftMutation> {
        fn default() -> Self {
            Self {
                artifact_mutations: Vec::new(),
                config_mutations: Vec::new(),
                window_config_mutations: Vec::new(),
                draft_mutations: Vec::new(),
                transaction: None,
                transaction_phase: TransactionPhase::Commit,
                effects: Vec::new(),
                extension_invocations: Vec::new(),
                events: Vec::new(),
                ui_scope: UiDirtyScope::default(),
                child_emits: Vec::new(),
                interaction_writes: Vec::new(),
                tasks: Vec::new(),
            }
        }
    }

    //#region 🔖️ExtensionInvocation
    /// 🔁️ One extension capability call plus the app command its RESULT is dispatched into — the
    /// whole of an app's extension-invocation surface, and the only shape from which a
    /// `Effect::InvokeExtension` is ever built.
    ///
    /// 🎯️ Why a declared `response_action` and not an awaited future: `ArtifactApp::handle` is a
    /// pure synchronous reducer, so it has no place to hold a `RequestFuture` across the turns an
    /// extension round-trip spans. The SDK therefore mints the `req` from the guest
    /// `RequestRegistry` (`request_continuation`) and, when `Event::Completed` for that exact id
    /// arrives, dispatches `response_action` back into the SAME app instance with `request_json`'s
    /// own fields merged with the outcome (`ok` plus `outputJson`, or `faultCode`/`faultMessage`).
    /// Correlation is therefore whatever the app already put in its request — a node hash, a
    /// handle — never a framework-invented key.
    ///
    /// ⚠️ `response_action` must name an APP-OWNED command of this same app (it is dispatched
    /// through `PluginApp::handle_command` against the instance's own owner address); an unknown id
    /// surfaces as an ordinary dispatch fault frame, never a silent drop.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ExtensionInvocation {
        pub extension_id: String,
        pub capability: String,
        pub request_json: String,
        pub response_action: String,
    }

    impl ExtensionInvocation {
        pub fn new(extension_id: impl Into<String>, capability: impl Into<String>, request_json: impl Into<String>, response_action: impl Into<String>) -> Self {
            Self { extension_id: extension_id.into(), capability: capability.into(), request_json: request_json.into(), response_action: response_action.into() }
        }
    }
    //#endregion 🔖️ExtensionInvocation

    //#region 🔖️AsyncTask
    /// 🧵️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (design-abi.md §4): the ONLY way a plugin's code
    /// can await anything. `ArtifactApp::handle` (the pure reducer) stays fully synchronous —
    /// waiting happens entirely INSIDE a task's `run` future, which is handed a `TaskCtx` (the
    /// awaitable `host::*` surface plus the ORIGINATING `ActionMeta`) once `dispatch_emit` actually
    /// spawns it, and the task's eventual result re-enters the reducer as a FOLLOW-UP dispatch
    /// (Elm's Msg-from-Cmd) — never by mutating anything directly from inside the future. Every
    /// task is owned by the instance that spawned it and is cancelled the moment that instance
    /// closes (`Event::InstanceClose`) — there is no detached/fire-and-forget spawn.
    ///
    /// `run`'s closure is `Send` because a pure reducer may create it on a worker before handing the
    /// resulting emit back to its actor. The future it creates remains actor-local and need not be
    /// `Send`: `TaskCtx` is supplied only after the closure reaches the actor's `LocalExecutor`.
    pub struct AsyncTask<Mutation, ConfigMutation = NoConfigMutation, DraftMutation = NoDraftMutation> {
        /// 🪪️ Diagnostic name — never parsed, only ever displayed (a quota-exceeded `Fault`'s
        /// message names the task that was refused).
        pub label: String,
        /// 🔑️ Latest-wins dedupe: spawning a task under the same `(instance, key)` as one already
        /// live cancels the live one first — the common "a new gesture supersedes an in-flight
        /// autosave/search/etc for the same purpose" shape.
        pub key: Option<String>,
        /// 🔁️ OpBinary-encoded command bytes — if the actor restores from a checkpoint taken while
        /// this task was still in flight, THIS is re-dispatched (as a fresh `TaskResolution::
        /// Command`) on the first turn after restore instead of the task itself, which is never
        /// serialized (design-abi.md §4: an in-flight async task is marked re-run-on-restore, not
        /// resumed as though the host round-trip were still live). `None` (the default) means the
        /// task is simply dropped, unrestarted, on restore — correct for idempotent/best-effort
        /// work that a restore should not repeat.
        pub restart: Option<Vec<u8>>,
        run: Box<dyn FnOnce(TaskCtx) -> Pin<Box<dyn Future<Output = Result<TaskResolution<Mutation, ConfigMutation, DraftMutation>, Fault>>>> + Send>,
    }

    impl<Mutation, ConfigMutation, DraftMutation> AsyncTask<Mutation, ConfigMutation, DraftMutation> {
        /// 🌱️ Builds a task from an async closure. `run` is called once, at the moment
        /// `dispatch_emit` actually spawns this task (never eagerly at `Emit` construction time),
        /// with the `TaskCtx` it should await against.
        pub fn new<F>(label: impl Into<String>, run: impl FnOnce(TaskCtx) -> F + Send + 'static) -> Self
        where
            F: Future<Output = Result<TaskResolution<Mutation, ConfigMutation, DraftMutation>, Fault>> + 'static,
        {
            Self { label: label.into(), key: None, restart: None, run: Box::new(move |ctx| Box::pin(run(ctx))) }
        }

        /// 🔑️ See the `key` field's own doc.
        pub fn keyed(mut self, key: impl Into<String>) -> Self {
            self.key = Some(key.into());
            self
        }

        /// 🔁️ See the `restart` field's own doc.
        pub fn restartable(mut self, command: Vec<u8>) -> Self {
            self.restart = Some(command);
            self
        }

        /// 🧵️ `⚛️reactor::spawn_task`'s sole consumer — decomposes the task into its plain-data
        /// bookkeeping fields plus the boxed closure, so the reactor (which has no reason to know
        /// about `AsyncTask` as a named type beyond spawning it) never has to reconstruct one.
        pub(crate) async fn into_parts(self) -> (String, Option<String>, Option<Vec<u8>>, Box<dyn FnOnce(TaskCtx) -> Pin<Box<dyn Future<Output = Result<TaskResolution<Mutation, ConfigMutation, DraftMutation>, Fault>>>> + Send>) {
            (self.label, self.key, self.restart, self.run)
        }
    }

    /// 🪪️ Handed to an `AsyncTask::run` closure at spawn time — the awaitable `host::*` surface
    /// (this actor's shared `RequestRegistry`, scoped to the spawning instance — see
    /// `⚛️reactor::host`) plus the CLONED `ActionMeta` the task was spawned under, so its eventual
    /// follow-up dispatch stays attributed to the same actor/instance even if a different one is
    /// active by the time the task resolves.
    pub struct TaskCtx {
        pub host: crate::host::Host,
        pub meta: ActionMeta,
    }

    /// 📬️ What an `AsyncTask` produces once its future resolves. Re-enters the (still pure/sync)
    /// reducer as a follow-up rather than mutating anything directly — Elm's Msg-from-Cmd.
    ///
    /// `Command` is the CANONICAL form: the document may have drifted while the task awaited, so
    /// the bytes re-enter `ArtifactApp::handle` against CURRENT state via the exact same
    /// `OpBinary`-typed path (`PluginApp::handle_command_frame`) a fresh command uses, stamped
    /// with the task's originating `ActionMeta`.
    ///
    /// `Emit` is a narrower, trivially-safe shortcut for a LITERAL mutation-lane follow-up that
    /// skips re-entering `handle` entirely — only `artifact_mutations`/`config_mutations`/
    /// `draft_mutations` are honored; `effects`/`events`/`child_emits`/`tasks` on this `Emit` are
    /// NOT applied (use `Command` if the follow-up needs any of those).
    ///
    /// `Done` performs no follow-up dispatch at all — for a task whose only job was a
    /// `TaskCtx::host` side effect (e.g. `host.notify(...)`) it already queued during its own run.
    pub enum TaskResolution<Mutation, ConfigMutation = NoConfigMutation, DraftMutation = NoDraftMutation> {
        Command(Vec<u8>),
        Emit(Emit<Mutation, ConfigMutation, DraftMutation>),
        Done,
    }
    //#endregion 🔖️AsyncTask

    //#region 🔖️EphemeralEmit
    /// 👥️🫧️ The two EPHEMERAL lanes' emission, deliberately separate from {@link Emit}.
    ///
    /// 🎯️ Why not more fields on `Emit`: the document lanes (artifact/config/draft) all have an op
    /// log, an edit id, an undo group and a failure mode; presence and transient have NONE of those.
    /// They cannot fail, cannot be undone, never enter a checkpoint and never appear in the command
    /// log. Folding them into `Emit` would put five type parameters on ~1000 signatures to express a
    /// thing that shares none of `Emit`'s machinery — and would force every app that emits no
    /// presence to name its presence type anyway.
    ///
    /// Apps opt in by overriding {@link ArtifactApp::ephemeral}; the default emits nothing, so an
    /// app with no shareable or UI-local state writes no code at all.
    #[derive(Debug)]
    pub struct EphemeralEmit<A: ArtifactApp> {
        /// 👥️ Ephemeral SHARED — broadcast to peers, never persisted.
        pub presence: Vec<A::PresenceMutation>,
        /// 🫧️ Ephemeral LOCAL-ONLY — never leaves this client.
        pub transient: Vec<A::TransientMutation>,
        /// 🪟️ Ephemeral LOCAL-ONLY state addressed to an exact concrete window instance.
        pub window_transient: Vec<WindowTransientMutation>,
    }

    impl<A: ArtifactApp> Default for EphemeralEmit<A> {
        fn default() -> Self {
            Self { presence: Vec::new(), transient: Vec::new(), window_transient: Vec::new() }
        }
    }

    impl<A: ArtifactApp> EphemeralEmit<A> {
        /// 👥️ Presence-only emission — the common case (a moved cursor, a changed selection).
        pub async fn presence(presence: Vec<A::PresenceMutation>) -> Self {
            Self { presence, transient: Vec::new(), window_transient: Vec::new() }
        }

        /// 🫧️ Transient-only emission — the common case (a hover, an in-flight gesture).
        pub async fn transient(transient: Vec<A::TransientMutation>) -> Self {
            Self { presence: Vec::new(), transient, window_transient: Vec::new() }
        }

        pub async fn window_transient(window_transient: Vec<WindowTransientMutation>) -> Self {
            Self { presence: Vec::new(), transient: Vec::new(), window_transient }
        }

        /// 🈳️ Whether this emission touches neither ephemeral lane.
        pub async fn is_empty(&self) -> bool {
            self.presence.is_empty() && self.transient.is_empty() && self.window_transient.is_empty()
        }
    }
    //#endregion 🔖️EphemeralEmit

    /// 🕹️ One app-initiated selection write riding alongside an ordinary action's own mutations —
    /// the ONLY way a reducer expresses "select what I just created/widened to" ("Select Same Kind",
    /// duplicate/accept/place re-select). Never a new client-facing verb: the six reserved
    /// `interactionSelect`-family actions stay the only EXTERNAL trigger, and every entry here is
    /// applied through the very same single-writer state machine they use
    /// (`protocol::next_selection` + `revalidate_and_persist_interaction_state`), after the
    /// triggering action's document mutations have landed so a just-created id is already in
    /// topology. See `26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM`.
    #[derive(Clone, Debug, PartialEq)]
    pub struct InteractionWrite {
        pub domain: String,
        pub targets: Vec<protocol::InteractionTarget>,
        pub merge: protocol::MergeMode,
    }

    impl InteractionWrite {
        /// 🎯️ Replaces `domain`'s selection with `ids`, all at one granularity — the shape every
        /// "select exactly these" reducer wants.
        pub fn replace(domain: impl Into<String>, granularity: &str, ids: impl IntoIterator<Item = String>) -> Self {
            Self { domain: domain.into(), targets: ids.into_iter().map(|id| protocol::InteractionTarget { granularity: granularity.to_string(), id }).collect(), merge: protocol::MergeMode::Replace }
        }
    }

    /// 🧩️ One composed child's share of an `Emit` — the plugin-layer twin of `store::ChildDispatch`,
    /// minted exclusively by `ChildEmit::of` so a plugin author never hand-encodes an op or
    /// hand-writes a `SchemaId`. `ops` are already `protocol::OpBinary`-encoded (the same per-op wire
    /// shape `store::ChildDispatch::ops` bundles); `labels` are each op's `SemanticMutation::label()`,
    /// captured BEFORE encoding — the vocabulary a history UI shows for this child's edit without
    /// ever decoding the raw bytes back into a concrete `Mutation` type it has no way to name
    /// generically.
    #[derive(Clone, Debug, PartialEq, Serialize, ToValue, FromValue)]
    pub struct ChildEmit {
        pub slot: String,
        pub child_id: String,
        pub ops: Vec<Vec<u8>>,
        pub op_schema: SchemaId,
        pub labels: Vec<LocalizedLabel>,
    }

    impl ChildEmit {
        /// 🧩️ The wire form of one agent gesture's owned-child share (`AppFrame::Emit.child_ops` →
        /// gateway → `AppCommand::TransactionPrepare.prepared_child_ops`): the exact `ChildEmit` list as one
        /// wire pack, empty bytes when the gesture touches no owned child, so a childless transaction's wire
        /// is unchanged.
        pub fn encode_groups(children: &[ChildEmit]) -> Vec<u8> {
            if children.is_empty() {
                return Vec::new();
            }
            store::pack_rt::encode_wire_value(&store::ToValue::to_value(&children.to_vec()))
        }

        /// 🧩️ Decodes [`ChildEmit::encode_groups`]; a pack that is not a `ChildEmit` list is refused by name.
        pub fn decode_groups(bytes: &[u8]) -> Result<Vec<ChildEmit>, Fault> {
            if bytes.is_empty() {
                return Ok(Vec::new());
            }
            let value = store::pack_rt::decode_wire_value(bytes).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("transaction.child-groups-malformed"), format!("owned-child op groups did not decode: {error}")))?;
            <Vec<ChildEmit> as store::FromValue>::from_value(value).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("transaction.child-groups-malformed"), format!("owned-child op groups are not a ChildEmit list: {error}")))
        }

        pub(crate) fn close_one(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(op) = self.ops.last_mut() {
                if !op.is_empty() {
                    if maximum_bytes == 0 {
                        return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    op.pop();
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 1 };
                }
                self.ops.pop();
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(label) = self.labels.last_mut() {
                let Some(value) = label.texts_mut().find(|value| !value.is_empty()) else {
                    self.labels.pop();
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                };
                let bytes = value.chars().next_back().expect("retained child label cell is nonempty").len_utf8();
                if bytes > maximum_bytes {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                value.pop();
                return PluginCloseStep::Pending { released_items: 0, released_bytes: bytes };
            }
            let value = if !self.op_schema.0.is_empty() {
                &mut self.op_schema.0
            } else if !self.child_id.is_empty() {
                &mut self.child_id
            } else if !self.slot.is_empty() {
                &mut self.slot
            } else {
                return PluginCloseStep::Complete;
            };
            let bytes = value.chars().next_back().expect("retained child string is nonempty").len_utf8();
            if bytes > maximum_bytes {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            value.pop();
            PluginCloseStep::Pending { released_items: 0, released_bytes: bytes }
        }

        /// 🏭️ The one sanctioned constructor: `S` is the child artifact's OWN snapshot type (turbofish
        /// it explicitly, e.g. `ChildEmit::of::<ChildSnapshot, _>("mesh", &child_id, &ops)` — `S`
        /// appears only in the `SemanticMutation<S>` bound below, so Rust cannot infer it from `ops`
        /// alone). Captures `op.label()`/`op.semantics()` per op (the child's real semantic
        /// vocabulary) BEFORE `OpBinary::encode_op`, so nothing about the child's own history
        /// authoring is lost crossing into the parent's `Emit`. `op_schema` is a best-effort
        /// diagnostic tag derived from the first op's `SemanticDescriptor` (`"<entity>.<kind>"`,
        /// falling back to `"child.empty"` for a no-op `ChildEmit`) — `store::dispatch_group` carries
        /// `ChildDispatch.op_schema` through as forward-compat metadata without interpreting it (see
        /// `UNIFIED-COMPOSABLE-ARTIFACT-SYSTEM/📓️wave1-reports/b2-store-composition-report.md`), so
        /// there is no schema REGISTRY this must resolve against yet.
        pub fn of<S, M>(slot: impl Into<String>, child_id: impl Into<String>, ops: &[M]) -> ChildEmit
        where
            M: protocol::SemanticMutation<S> + ::protocol::OpBinary,
        {
            let mut labels: Vec<LocalizedLabel> = Vec::with_capacity(ops.len());
            for op in ops.iter() {
                labels.push(protocol::SemanticMutation::label(op));
            }
            let op_schema = match ops.first() {
                Some(op) => {
                    let semantics = protocol::SemanticMutation::semantics(op);
                    SchemaId(format!("{}.{}", semantics.entity, semantics.kind))
                }
                None => SchemaId("child.empty".to_string()),
            };
            let mut encoded: Vec<Vec<u8>> = Vec::with_capacity(ops.len());
            for op in ops.iter() {
                encoded.push(::protocol::OpBinary::encode_op(op).unwrap_or_default());
            }
            ChildEmit { slot: slot.into(), child_id: child_id.into(), ops: encoded, op_schema, labels }
        }
    }

    impl<Mutation, ConfigMutation, DraftMutation> Emit<Mutation, ConfigMutation, DraftMutation> {
        /// 🧹️ Retires at most one bounded child-emission step while the concrete app keeps ownership of its typed lanes.
        pub fn close_child_one(&mut self, maximum_items: usize, maximum_bytes: usize) -> Option<PluginCloseStep> {
            let child = self.child_emits.last_mut()?;
            let step = child.close_one(maximum_items, maximum_bytes);
            if step == PluginCloseStep::Complete {
                self.child_emits.pop();
                Some(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
            } else {
                Some(step)
            }
        }

        /// ✏️ A document-operation emission carrying `artifact_mutations` and nothing else.
        pub fn mutations(artifact_mutations: Vec<Mutation>) -> Self {
            Self { artifact_mutations, ..Default::default() }
        }

        /// 🛠️ A committed `ToolTransaction` (`ToolMachineRunner`'s `ToolStep::Committed(transaction, mutations)`)
        /// published as ONE document edit whose every op carries `transaction`; the history row is labelled from the
        /// mutations' own `MutationKind` labels. When earlier ticks streamed into the transaction
        /// ([`Self::stream_transaction`]) the mutations join its open edit and the commit closes it; with nothing open and
        /// nothing to record it is an empty emission.
        pub fn commit_transaction(transaction: protocol::TransactionRef, artifact_mutations: Vec<Mutation>) -> Self {
            Self { artifact_mutations, transaction: Some(transaction), ..Default::default() }
        }

        /// 🌊️ One tick of a streamed `ToolTransaction` (design §15): `artifact_mutations` join the transaction's open edit
        /// (the first tick opens it), every op stamped with `transaction`. The document shows them at once, but nothing is
        /// announced or persisted until [`Self::commit_transaction`] with the same ref closes the edit; [`Self::abort_transaction`]
        /// reverts it with zero trace. For tools whose yield cannot wait for the commit (streamed imports).
        pub fn stream_transaction(transaction: protocol::TransactionRef, artifact_mutations: Vec<Mutation>) -> Self {
            Self { artifact_mutations, transaction: Some(transaction), transaction_phase: TransactionPhase::Stream, ..Default::default() }
        }

        /// 🧨️ Reverts the open edit of the streamed `ToolTransaction` `transaction` with zero trace: no edit, no history row,
        /// nothing announced. With nothing open it is an empty emission.
        pub fn abort_transaction(transaction: protocol::TransactionRef) -> Self {
            Self { transaction: Some(transaction), transaction_phase: TransactionPhase::Abort, ..Default::default() }
        }

        /// 🪆️ `commit_transaction`'s composed-children twin (design §12): a committed `ToolTransaction` whose leaves
        /// land in owned child members, published as ONE composite group where every touched member's edit carries
        /// `transaction`. Children with no ops are dropped; nothing touched is an empty emission.
        pub fn commit_child_transaction(transaction: protocol::TransactionRef, child_emits: Vec<ChildEmit>) -> Self {
            let child_emits: Vec<ChildEmit> = child_emits.into_iter().filter(|child| !child.ops.is_empty()).collect();
            let transaction = (!child_emits.is_empty()).then_some(transaction);
            Self { child_emits, transaction, ..Default::default() }
        }

        /// 🪆️ A released node drag (`semio_framework_tool_machine::node_drag_emit`) whose leaves land in the owned child
        /// `slot` member `child_id` (design §12): ONE composite group whose member edit carries the transaction, the child
        /// leaves plainly for a view without command authority, or nothing.
        pub fn node_drag_child<S, M>(drag: semio_framework_tool_machine::NodeDragEmit<M>, slot: &str, child_id: &str) -> Self
        where
            M: protocol::SemanticMutation<S> + ::protocol::OpBinary,
        {
            match drag {
                semio_framework_tool_machine::NodeDragEmit::Commit(transaction, leaves) => Self::commit_child_transaction(transaction, vec![ChildEmit::of::<S, M>(slot, child_id, &leaves)]),
                semio_framework_tool_machine::NodeDragEmit::Plain(leaves) => Self { child_emits: vec![ChildEmit::of::<S, M>(slot, child_id, &leaves)], ..Default::default() },
                semio_framework_tool_machine::NodeDragEmit::Nothing => Self::default(),
            }
        }

        /// 🧮️ A config-operation emission carrying `config_mutations` and nothing else — the
        /// replacement for a former "View"-kind `ActionEmit::view_with_inverse`: selection/camera/hover/…
        /// changes now flow through the config store, which computes their real `inverse` itself.
        pub fn config(config_mutations: Vec<ConfigMutation>) -> Self {
            Self { config_mutations, ..Default::default() }
        }

        /// 📝️ A draft-operation emission carrying `draft_mutations` and nothing else.
        pub fn draft(draft_mutations: Vec<DraftMutation>) -> Self {
            Self { draft_mutations, ..Default::default() }
        }

        /// 🐚️ A single host effect and no operations (a shell action).
        pub fn effect(effect: Effect) -> Self {
            Self { effects: vec![effect], ..Default::default() }
        }

        /// 📣️ A single app event and no operations.
        pub fn event(event: AppEvent) -> Self {
            Self { events: vec![event], ..Default::default() }
        }

        /// 🧵️ A single spawned `AsyncTask` and no operations — the common case for "this
        /// command's only job is to kick off host work" (e.g. a search-as-you-type debounce).
        pub fn task(task: AsyncTask<Mutation, ConfigMutation, DraftMutation>) -> Self {
            Self { tasks: vec![task], ..Default::default() }
        }
    }

    /// 🪪️ Per-invocation runtime metadata handed to the object-safe {@link PluginApp} — the local
    /// actor id, the instance id used to stamp operation handles, and optional host view context.
    /// Headless operations have no view; UI actions carry the addressed concrete window's projection.
    #[derive(Clone, Debug, Default)]
    pub struct ActionMeta {
        pub actor: String,
        pub instance_id: u32,
        pub view_state: Option<ViewModel>,
    }

    /// 🔤️ Parses the raw action id crossing the WASM ABI (`ArtifactApp::handle_action`'s `action: &str`)
    /// into a closed, per-app enum — the seam where "stringly-typed at the edge" becomes exhaustively
    /// matched one line in. Not yet wired into `ArtifactApp` itself (that would break every existing
    /// implementer at once); adopt it per app by matching on the parsed variant instead of the raw string
    /// inside `handle_action`, e.g. `let action = MyAppAction::from_action_id(action)?; match action { ... }`.
    pub trait AppAction: Sized {
        async fn from_action_id(id: &str) -> Result<Self, String>;
    }

    /// 🏭️ Generates a closed per-app action enum plus its `AppAction` impl from a list of
    /// `Variant = "actionId"` pairs — the ids should match what's passed to `.mutation()/.view_action()/
    /// .shell_action()` on the app's `AppBuilder` so the declared action registry and the dispatch match
    /// can't drift apart silently.
    #[macro_export]
    macro_rules! app_action_enum {
    ($vis:vis enum $Name:ident { $($Variant:ident = $id:literal),* $(,)? }) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        $vis enum $Name {
            $($Variant),*
        }

        impl $crate::app::AppAction for $Name {
            async fn from_action_id(id: &str) -> Result<Self, String> {
                match id {
                    $($id => Ok(Self::$Variant),)*
                    other => Err(Fault::from(format!("unknown action id {other}"))),
                }
            }
        }
    };
}

    //#region 🔖️AppCommands
    /// 🎮️ Generates a closed per-app `ArtifactApp::Command` enum from `"id" => module::Payload`
    /// rows — the taxonomy-decomposed replacement for a hand-written
    /// `#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, dsl::DslOps)] pub enum XCommand { #[dsl(key = "...")] Variant { .. }, .. }`
    /// (see e.g. `flow_protocol::FlowCommand`, `dag_protocol::DagCommand`, `shooting_protocol::ShootingCommand`
    /// — every hand-written Command enum in the repo already follows this exact derive/attribute shape, none
    /// use `#[serde(tag = ...)]`; the real wire codec is `dsl::DslOps`'s generated `OpText`/`OpBinary`, keyed
    /// by each variant's `#[dsl(key = ..)]` string).
    ///
    /// Each row becomes a single-field tuple variant `$Payload($module::$Payload)`. This is deliberate, not
    /// incidental: `dsl::DslOps`'s codegen special-cases single-field tuple variants (see
    /// `dsl_variants_codegen` in the `dsl-derive` crate) to delegate ENTIRELY to the inner type's own
    /// `DslField` impl — its `RecordSpec` IS the payload type's, not a wrapper with one positional field — so
    /// a payload struct declared with `#[derive(dsl::DslRecord)]` (its own fields, no extra nesting) prints/
    /// parses byte-identically whether reached through this enum or used standalone. Concretely: migrating a
    /// hand-written `AddWidget { kind: String, x: Option<f64> }` struct-variant into a
    /// `🎮️commands/add_widget/🦀️.rs` payload `struct AddWidget { kind: String, x: Option<f64> }`
    /// (deriving `DslRecord`) plus `AddWidget(add_widget::AddWidget)` here reproduces the exact same
    /// `OpText`/`OpBinary` wire bytes for the same `#[dsl(key = "...")]` string — the migration is pure code
    /// motion, not a wire-format change.
    ///
    /// Expands to:
    /// - the enum itself (`$vis enum $Name`), deriving `Clone, Debug, PartialEq, $crate::ToValue,
    ///   $crate::FromValue, dsl::DslOps` — satisfies `ArtifactApp::Command: protocol::OpBinary + Send`
    ///   directly. `dsl` is referenced unqualified (not via `$crate`, since it is NOT the defining crate) —
    ///   every crate that hosts `🎮️commands/*` payload modules already depends on `dsl` directly (payloads
    ///   themselves derive `dsl::DslRecord`), matching the convention every existing hand-written
    ///   `*_protocol` crate already follows. `ToValue`/`FromValue`, by contrast, ARE spelled via `$crate` —
    ///   both are proc-macros re-exported at this crate's own root (`🦀️.rs`), so the path resolves to
    ///   `semio_framework_value_derive`'s derives regardless of what the invoking plugin crate has
    ///   imported; every `$Payload` type these wrap must itself derive `ToValue`/`FromValue` (own work, not
    ///   inherited) for the generated enum impl to compile — no plugin manifest was allowed to drop `serde`
    ///   from `Cargo.toml` while this line still said `::serde::Serialize, ::serde::Deserialize`, since the
    ///   enum's own derive transitively required every payload type to implement it too.
    /// - `command_id(&self) -> &'static str`, returning each row's `$id` — mirrors the per-command labeling
    ///   `ArtifactApp::command_id` needs (today hand-rolled as a parallel `match` per app, e.g.
    ///   `TestApp::command_id` above).
    /// - `dispatch(&self, doc: &ArtifactView<'_, $Snapshot>, cfg: &ConfigView<'_, $Config>) -> ArtifactMutationOutcome<$Mutation, $ConfigMutation>`,
    ///   matching each variant to `$module::handle(payload, doc, cfg)` — `$Snapshot`/`$Mutation`/`$Config`/
    ///   `$ConfigMutation` are the four types declared after `for` in the invocation (see below).
    ///
    /// # 🔖️DispatchDesignChoice
    /// The macro invocation names the app's four `ArtifactApp` associated types up front —
    /// `enum $Name for $Snapshot, $Mutation, $Config, $ConfigMutation { .. }` — so `dispatch` can be a
    /// perfectly ordinary, CONCRETE (non-generic) inherent method. This was chosen over the alternative
    /// tried first: a `dispatch<P, O, C, CO>` generic over all four, inferring them from the call site. That
    /// alternative does not type-check, and the `app_commands_tests` module below hit exactly this in
    /// practice — every real `🎮️commands/<command>/🦀️.rs::handle` fn will be written against ONE
    /// app's concrete `Snapshot`/`Mutation`/`Config`/`ConfigMutation` (the same way
    /// `flow_protocol`/`dag_protocol`/... payload handlers are today), never generically; a generic
    /// `dispatch<P,O,C,CO>` body calling a concrete-typed `$module::handle` fails to unify (`P` is not
    /// literally `FlowHostSnapshot`, even though there is only ever one real instantiation). Naming the four
    /// types once, at the `app_commands!` invocation, costs one extra clause per app but produces a
    /// `dispatch` whose signature matches `ArtifactApp::handle` exactly — so an app's whole `handle` impl
    /// collapses to one line, `command.dispatch(doc, cfg)`. A per-command closure/trait-object API (the
    /// plan's other suggested option) would force hand-rolling one closure per row at adoption time instead
    /// — strictly more ceremony than stating the four types once.
    ///
    /// # 🔖️KeyedAndContextualForms
    /// Two further arms exist, both discovered as hard requirements by the W1 🌊️flow pilot (the first real
    /// consumer) and additive to the plain arm above, which is unchanged:
    ///
    /// 1. **Keyed rows** — `"commandId" as "wire-key" => module::Payload`. Every hand-written Command enum in
