    /// 🫧️ Yields one mounted plugin-job transition back to the host executor.
    pub(crate) async fn plugin_job_yield_once() {
        let mut yielded = false;
        std::future::poll_fn(move |cx| {
            if yielded {
                std::task::Poll::Ready(())
            } else {
                yielded = true;
                cx.waker().wake_by_ref();
                std::task::Poll::Pending
            }
        })
        .await;
    }

    /// 🚦️ Whether one mounted-worker pump rejection is scheduler weather rather than a lost transition.
    /// The process pool admits a step through a per-worker `try_lock` and a finite per-lane queue, so a
    /// worker that happens to be popping its own queue, a momentarily full lane, and a step whose outcome
    /// has not landed yet all return an `Err` that says NOTHING about this job — the exact same set the
    /// mounted typed-operation path already answers with `AwaitingInput`. Faulting a framework-reserved
    /// route on them made every `interactionHover`/`interactionSelect` a coin flip against pool load.
    fn reserved_pump_fault_is_transient(fault: &semio_framework_job::MountedWorkerJobPumpFault) -> bool {
        matches!(
            fault,
            semio_framework_job::MountedWorkerJobPumpFault::Submit(semio_framework_job::WorkerJobSubmitFault::Contention(_))
                | semio_framework_job::MountedWorkerJobPumpFault::Submit(semio_framework_job::WorkerJobSubmitFault::Pool(semio_framework_async::WorkerSubmitErrorKind::Contended | semio_framework_async::WorkerSubmitErrorKind::Saturated))
                | semio_framework_job::MountedWorkerJobPumpFault::Take(semio_framework_job::WorkerJobTakeFault::Pending)
        )
    }

    /// 🏷️ The exact rejection a structural pump fault carries, so the route's fault message names the
    /// transition it lost instead of a bare code.
    fn reserved_pump_fault_detail(fault: &semio_framework_job::MountedWorkerJobPumpFault) -> String {
        match fault {
            semio_framework_job::MountedWorkerJobPumpFault::Submit(submit) => format!("submit {submit:?}"),
            semio_framework_job::MountedWorkerJobPumpFault::Take(take) => format!("take {take:?}"),
            semio_framework_job::MountedWorkerJobPumpFault::MissingTicket => "submitted step lost its exact ticket".to_string(),
            semio_framework_job::MountedWorkerJobPumpFault::CheckedOut => "outcome is already checked out".to_string(),
        }
    }

    /// 🧾️ Compares a retained fixed-page payload without materializing a whole-buffer adapter.
    fn retained_payload_eq_slice(payload: &semio_framework_job::RetainedJobPayload, expected: &[u8]) -> bool {
        if payload.len() != expected.len() {
            return false;
        }
        let mut cursor = 0usize;
        let mut reader = payload.reader();
        while let Some(page) = reader.read_page(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {
            let end = cursor.saturating_add(page.len());
            if expected.get(cursor..end) != Some(page) {
                return false;
            }
            cursor = end;
        }
        reader.terminal_is_empty() && cursor == expected.len()
    }

    struct AdmittedToolCommand {
        verb: String,
        proof: QualifiedToolProof,
        wire_admission: semio_framework::ToolWireAdmission,
        decoded_items: usize,
        raw_wire: semio_framework::action_bus::RetainedToolWireInput,
    }

    struct PendingLatestWinsCommand<A: ArtifactApp> {
        command: std::mem::ManuallyDrop<Option<Box<A::Command>>>,
        disposer: Box<dyn ArtifactOwnedDisposer<A::Command>>,
        admission: Option<AdmittedToolCommand>,
        meta: ActionMeta,
        operation: semio_framework_job::Operation,
        revision: [u8; 32],
        lease: Option<ToolCancellationLease>,
        key_copy: Option<ToolLatestWinsKeyCopy>,
        key: Option<std::sync::Arc<String>>,
        retired_key: Option<String>,
        lookup_started: bool,
        accepted: bool,
        restarting: bool,
        closing: bool,
    }

    impl<A: ArtifactApp> PendingLatestWinsCommand<A> {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 || maximum_bytes == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(command) = self.command.as_mut() {
                let step = self.disposer.close_step(command, maximum_items.min(1), maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    if !self.disposer.terminal_is_empty(command) {
                        return Err(plugin_sdk_fault("latest-wins command disposer reported a false terminal"));
                    }
                    drop(self.command.take());
                }
                return Ok(step);
            }
            let step = self.close_key_step(maximum_items, maximum_bytes);
            if step != PluginCloseStep::Complete {
                return Ok(step);
            }
            if let Some(admission) = self.admission.as_mut() {
                if !admission.raw_wire.terminal_is_empty() {
                    return Ok(match admission.raw_wire.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                        semio_framework_job::InteractiveJobCloseStep::Blocked => PluginCloseStep::Blocked { reason: "latest-wins retained raw input close is blocked" },
                        semio_framework_job::InteractiveJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                    });
                }
                if let QualifiedToolProof::AppOwned(registration) = &mut admission.proof {
                    for text in [&mut registration.key.controller_id, &mut registration.key.tool_id, &mut registration.schema_id] {
                        if let Some(step) = MountedTypedCommandFullOperation::<A>::retire_string_scalar(text, maximum_bytes) {
                            return Ok(step);
                        }
                    }
                }
                for text in [&mut admission.verb, &mut admission.wire_admission.key.controller_id, &mut admission.wire_admission.key.tool_id, &mut admission.wire_admission.schema_id] {
                    if let Some(step) = MountedTypedCommandFullOperation::<A>::retire_string_scalar(text, maximum_bytes) {
                        return Ok(step);
                    }
                }
                self.admission = None;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn close_key_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(copy) = self.key_copy.as_mut() {
                let step = copy.close_step(maximum_items, maximum_bytes);
                if step == PluginCloseStep::Complete {
                    self.key_copy = None;
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                return step;
            }
            if let Some(key) = self.key.take() {
                self.retired_key = std::sync::Arc::into_inner(key);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(key) = self.retired_key.as_mut() {
                if let Some(step) = MountedTypedCommandFullOperation::<A>::retire_string_scalar(key, maximum_bytes) {
                    return step;
                }
                self.retired_key = None;
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            PluginCloseStep::Complete
        }

        fn command_owners_are_empty(&self) -> bool {
            self.command.is_none() && self.admission.is_none() && self.key_copy.is_none() && self.key.is_none() && self.retired_key.is_none()
        }
    }

    impl<A: ArtifactApp> Drop for PendingLatestWinsCommand<A> {
        fn drop(&mut self) {
            if !std::thread::panicking() {
                assert!(std::thread::panicking() || self.command_owners_are_empty(), "latest-wins admission must transfer or cursor-retire its exact command/key/raw owners");
            }
        }
    }

    struct TypedCommandWireWriter {
        input: semio_framework::action_bus::RetainedToolWireInput,
        page: [u8; semio_framework::action_bus::TOOL_WIRE_PAGE_BYTES],
        len: usize,
    }

    impl TypedCommandWireWriter {
        fn flush_page(&mut self) -> std::io::Result<()> {
            if self.len == 0 {
                return Ok(());
            }
            let page = semio_framework::action_bus::ToolWirePage::try_copy_from(&self.page[..self.len]).map_err(|error| std::io::Error::new(std::io::ErrorKind::WriteZero, error.detail))?;
            self.input.admit_page(page).map_err(|(error, _)| std::io::Error::new(std::io::ErrorKind::WriteZero, error.detail))?;
            self.len = 0;
            Ok(())
        }

        fn finish(mut self) -> Result<semio_framework::action_bus::RetainedToolWireInput, Fault> {
            self.flush_page().map_err(|error| plugin_sdk_fault(error.to_string()))?;
            self.input.seal().map_err(|error| plugin_sdk_fault(error.detail))?;
            Ok(self.input)
        }

        fn finish_admitted_prefix(mut self) -> Result<semio_framework::action_bus::RetainedToolWireInput, Fault> {
            self.flush_page().map_err(|error| plugin_sdk_fault(error.to_string()))?;
            self.input.seal_admitted_prefix().map_err(|error| plugin_sdk_fault(error.detail))?;
            Ok(self.input)
        }
    }

    impl std::io::Write for TypedCommandWireWriter {
        fn write(&mut self, mut bytes: &[u8]) -> std::io::Result<usize> {
            let source_len = bytes.len();
            while !bytes.is_empty() {
                if self.len == self.page.len() {
                    self.flush_page()?;
                }
                let count = bytes.len().min(self.page.len() - self.len);
                self.page[self.len..self.len + count].copy_from_slice(&bytes[..count]);
                self.len += count;
                bytes = &bytes[count..];
            }
            Ok(source_len)
        }

        fn flush(&mut self) -> std::io::Result<()> {
            self.flush_page()
        }
    }

