    impl<A: ArtifactApp, M: SpaceMember + MemberFactory + 'static> VcsArtifactApp<A, M> {
        /// 🔍️ Read-only inspection of this instance's tool run ledger for app-level tests.
        #[cfg(feature = "artifact-app-testing")]
        pub fn tool_run_ledger(&self) -> &ToolRunLedger<A> {
            &self.tool_runs
        }

        /// 🪪️ A command's whole-document replacement names this store's identity, not whatever the app
        /// minted: see [`store::stamp_document_spr_identity`].
        fn stamp_load_document_identity(&self, effect: Effect) -> Result<Effect, Fault> {
            let Effect::LoadDocument { pack, spr } = effect else { return Ok(effect) };
            let envelope = self.store.envelope();
            let identity = ArtifactRef { artifact_id: envelope.id.clone(), dialect: A::DIALECT.into() };
            let spr = ::semio_framework_async::poll::resolve_ready(store::stamp_document_spr_identity(&spr, &identity.artifact_id, A::DOCUMENT_SCHEMA, &identity.dialect, envelope.owner.as_ref()))
                .map_err(|error| plugin_sdk_fault(format!("load-document identity stamp failed: {error}")))?;
            Ok(Effect::LoadDocument { pack, spr })
        }

        /// 🚪️ EVERY effect leaving this instance passes the stamp, not just the mounted typed-operation
        /// ladder's. An app mints its replacement log with `store::empty_document_spr`, which carries no
        /// composition section at all, and the archive loader's parent hydration refuses such a log
        /// outright (`MemberOpenDiagnostic::Identity`, `💧️hydration/🦀️.rs` `Phase::Begin`) before any of
        /// the three replacement legs even runs. The stamp is therefore not an optimisation on one lane,
        /// it is the whole contract between `Effect::LoadDocument` and `load_document_archive` — and the
        /// plain dispatch lane and the refresh poll both used to skip it, which is why every
        /// `setActiveExample` whose verb is not a mounted retained tool died in the browser.
        fn stamp_load_document_effects(&self, effects: Vec<Effect>) -> Result<Vec<Effect>, Fault> {
            if !effects.iter().any(|effect| matches!(effect, Effect::LoadDocument { .. })) {
                return Ok(effects);
            }
            effects.into_iter().map(|effect| self.stamp_load_document_identity(effect)).collect()
        }

        /// 🪪️ The refresh poll's twin — that lane has no error channel, so an undecodable log rides on
        /// unchanged and the archive loader reports its own identity refusal, rather than the effect
        /// disappearing without a word.
        fn stamp_polled_load_document_effects(&self, effects: Vec<Effect>) -> Vec<Effect> {
            if !effects.iter().any(|effect| matches!(effect, Effect::LoadDocument { .. })) {
                return effects;
            }
            let envelope = self.store.envelope();
            let dialect: ArtifactDialect = A::DIALECT.into();
            effects
                .into_iter()
                .map(|effect| match effect {
                    Effect::LoadDocument { pack, spr } => {
                        let stamped = ::semio_framework_async::poll::resolve_ready(store::stamp_document_spr_identity(&spr, &envelope.id, A::DOCUMENT_SCHEMA, &dialect, envelope.owner.as_ref())).ok();
                        Effect::LoadDocument { pack, spr: stamped.unwrap_or(spr) }
                    }
                    other => other,
                })
                .collect()
        }
    }

    /// 🆔️ Deterministic session-local `ArtifactHandle` for a CHILD's real (string) artifact id.
    /// `result_from_last_edit`'s own `ArtifactHandle(meta.instance_id as u128)` only identifies the
    /// ONE wasm-hosted document this plugin instance runs (the parent) — a child pulled in through
    /// `dispatch_emit_group` is a different document with its own string `artifact_id` and no
    /// instance id of its own, so `KernelMutation.document` needs a handle derived from THAT id
    /// instead, so history correctly attributes a child's edit to the child, not the parent. FNV-1a
    /// (128-bit, two interleaved 64-bit lanes) rather than `std::collections::hash_map::DefaultHasher`
    /// — the latter's hash is only guaranteed stable for one process/compiler invocation, not the
    /// byte-identical value the SAME child id must always map to.
    pub(crate) async fn artifact_handle_of(artifact_id: &str) -> ArtifactHandle {
        const OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
        const PRIME: u64 = 0x0000_0100_0000_01b3;
        let mut lane0 = OFFSET;
        let mut lane1 = OFFSET ^ 0x9e37_79b9_7f4a_7c15;
        for byte in artifact_id.as_bytes() {
            lane0 = (lane0 ^ *byte as u64).wrapping_mul(PRIME);
            lane1 = (lane1 ^ (*byte as u64).rotate_left(7)).wrapping_mul(PRIME);
        }
        ArtifactHandle(((lane0 as u128) << 64) | lane1 as u128)
    }

    /// ⏱️ Wall budget one `PollDocumentArchiveLoad` may spend driving the maintenance rotation before it
    /// reports — the background lane's slice, so a load polled back-to-back completes in seconds while a
    /// single poll never holds the actor longer than the pump's own worst step.
    const DOCUMENT_ARCHIVE_POLL_WALL_US: u64 = semio_framework_job::BACKGROUND_LANE_WALL_US;
    /// 📏️ Byte grant per maintenance step driven by a poll — the same slice the runtime's live cleanup job hands the pump.
    const DOCUMENT_ARCHIVE_POLL_STEP_BYTES: usize = 32 * 1_024;

    /// 🪪️ The persisted schema a derivable child of `dialect` is minted under — read from the member
    /// roster's own open declarations, so an app deriving a child of a dialect its `M` never declares
    /// is a fault rather than a member nothing could ever open.
    fn genesis_member_schema<M: MemberFactory>(dialect: &ArtifactDialect) -> Result<&'static str, Fault> {
        M::OPEN_DECLARATIONS
            .iter()
            .find(|declaration| declaration.kind == dialect.artifact_kind && declaration.standard == dialect.standard && declaration.subset == dialect.subset)
            .map(|declaration| declaration.schema)
            .ok_or_else(|| plugin_sdk_fault(format!("derived child dialect '{}' is not declared by this app's member roster", dialect.to_coordinate())))
    }

    /// 📚️ Turns a registered example body into the app snapshot. A `{` body is the JSON a deferred
    /// producer emits; anything else is the subset's own DSL.
    pub(crate) fn catalogue_snapshot_from_document<S>(body: &str) -> Result<S, Fault>
    where
        S: store::ArtifactDsl + protocol::FromValue,
    {
        if body.trim_start().starts_with('{') {
            semio_framework_pack_json::from_json_str(body, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| Fault::new(FaultOrigin::App, FaultCode::new("app.example.unreadable"), error.to_string()))
        } else {
            <S as store::ArtifactDsl>::parse_dsl(body).map_err(|error| Fault::new(FaultOrigin::App, FaultCode::new("app.example.unreadable"), error.to_string()))
        }
    }

    const HISTORY_ACTION_IDS: [&str; 6] = ["undo", "redo", "commitCheckpoint", "createAlternative", "switchAlternative", "checkoutCheckpoint"];

    const CLIPBOARD_ACTION_IDS: [&str; 3] = ["copy", "cut", "paste"];

    /// 🕹️ The six framework-owned interaction actions `dispatch_action` intercepts before any of the
    /// other framework-reserved branches — see `dispatch_interaction_action`'s own doc comment.
    pub(crate) const INTERACTION_ACTION_IDS: [&str; 6] = [INTERACTION_SELECT_ACTION_ID, INTERACTION_HOVER_ACTION_ID, CLEAR_SELECTION_ACTION_ID, SELECT_ALL_ACTION_ID, SET_SELECTION_MODE_ACTION_ID, SET_INTERACTION_GRANULARITY_ACTION_ID];

    pub(crate) fn is_framework_reserved_action_id(action: &str) -> bool {
        HISTORY_ACTION_IDS.contains(&action)
            || CLIPBOARD_ACTION_IDS.contains(&action)
            || INTERACTION_ACTION_IDS.contains(&action)
            || is_tool_run_action_id(action)
            || is_time_travel_action_id(action)
            || action == CANCEL_TYPED_OPERATION_ACTION_ID
            || action == semio_framework::HOST_EVENT_ACTION_ID
            || matches!(action, REVERT_TO_COMMAND_ACTION_ID | SET_HISTORY_COMMAND_FILTER_ACTION_ID | NOTE_SHELL_COMMAND_ACTION_ID | RECORD_TUTORIAL_ACTION_ID)
            || matches!(action, semio_framework::EXPORT_ARTIFACT_DOCUMENT_ACTION_ID | semio_framework::IMPORT_ARTIFACT_DOCUMENT_ACTION_ID)
    }

    pub(crate) fn framework_reserved_action_kind(action: &str) -> Option<ActionKind> {
        if !is_framework_reserved_action_id(action) {
            return None;
        }
        if CLIPBOARD_ACTION_IDS.contains(&action) {
            return Some(ActionKind::Clipboard);
        }
        if INTERACTION_ACTION_IDS.contains(&action) || action == semio_framework::HOST_EVENT_ACTION_ID {
            return Some(ActionKind::Interaction);
        }
        if action == SET_HISTORY_COMMAND_FILTER_ACTION_ID || action == CANCEL_TYPED_OPERATION_ACTION_ID {
            return Some(ActionKind::View);
        }
        if action == NOTE_SHELL_COMMAND_ACTION_ID || matches!(action, semio_framework::EXPORT_ARTIFACT_DOCUMENT_ACTION_ID | semio_framework::IMPORT_ARTIFACT_DOCUMENT_ACTION_ID) {
            return Some(ActionKind::Shell);
        }
        Some(ActionKind::History)
    }

    /// ⏱️ M2 (ticket 26/08/17 `design-unified.md`): default TTL for every `PresenceUpdate`
    /// `stamp_and_cache_interaction_ui` derives — a peer mark not refreshed within this window ages
    /// out on the reactor's `PresenceHub` with no goodbye message (matches the design's decided
    /// default; own presence never expires by this or any other TTL — see `ui_runtime::PresenceHub`'s
    /// own doc).
    const PRESENCE_TTL_MS: u32 = 4_000;

    //#region 🔖️ViewerGuard
    /// 🔒️ Contract §2.3: the string-action verbs a `Viewer`-role instance must reject at
    /// `dispatch_action`'s entry — `import` is not a string action (see `PluginApp::import_media`'s
    /// own check in `dispatch_import_media`), so it is not in this list. `checkoutCheckpoint` and
    /// `switchAlternative` are rejected too: each commits a `Checkout` history transition to the shared event log, which
    /// moves the head (and the scoped history edits it projects) for every replica, so it is a write, not a read cursor.
    /// `try_build_definition` never declares these on a viewer app, so no host offers or binds them to a
    /// Spectator; this guard is the backstop for a dispatch no manifest offered.
    const VIEWER_REJECTED_ACTION_IDS: [&str; 9] = ["undo", "redo", "commitCheckpoint", "createAlternative", semio_framework::SWITCH_ALTERNATIVE_ACTION_ID, "checkoutCheckpoint", REVERT_TO_COMMAND_ACTION_ID, "cut", "paste"];

    /// 🔒️ Whether a `Viewer`-role instance rejects `action`: the [`VIEWER_REJECTED_ACTION_IDS`] and every history-edit
    /// verb (editing history supersedes inputs, which a viewer never may).
    fn viewer_rejects_action(action: &str) -> bool {
        VIEWER_REJECTED_ACTION_IDS.contains(&action) || is_time_travel_action_id(action)
    }

    /// 🧊️ The framework-reserved verbs a history-edit session freezes: the history-lane verbs (they move the applied
    /// stack or the head and would invalidate the session base silently) and the clipboard verbs that edit the document.
    fn time_travel_freezes_reserved_action(action: &str) -> bool {
        HISTORY_ACTION_IDS.contains(&action) || matches!(action, REVERT_TO_COMMAND_ACTION_ID | "cut" | "paste")
    }

    /// 🧊️ The `timeTravel.frozen` refusal of `verb` while a history edit is open on this instance.
    fn time_travel_frozen_fault(verb: &str) -> Fault {
        Fault::new(FaultOrigin::Framework, FaultCode::new(semio_framework_time_travel::TIME_TRAVEL_FROZEN_CODE), format!("verb {verb:?} would change the document while a history edit is open on this instance"))
    }

    /// 🔒️ Frozen fault (contract §2.3): exact code `viewer.read-only`, `FaultOrigin::Framework` — a
    /// mutating verb reached a `Viewer`-role `VcsArtifactApp` instance, either through
    /// `dispatch_action`/`dispatch_import_media`'s string-verb guard or `dispatch_emit`'s non-empty
    /// `artifact_mutations` backstop (the latter is unreachable through `ViewerApp`'s structurally
    /// closed `ViewEmit`, contract §2.2 — this exists so a hand-written runtime `ArtifactApp` impl
    /// that ignores `ViewEmit` is safe too, not "redundant").
    // 🚫️async: E1 pure error constructor consumed pervasively by sync closures — see R9.
    fn viewer_read_only_fault(verb: &str) -> Fault {
        Fault::new(FaultOrigin::Framework, FaultCode::new("viewer.read-only"), format!("'{verb}' is not permitted on a viewer instance (contract §2.3)"))
    }
    //#endregion 🔖️ViewerGuard

    /// 🏷️ A noted shell command's history label in every locale: a full `LocalizedLabel`, an `{en, de}` pair, or plain
    /// text (locale-invariant data, e.g. a file name); the optional `detail` is appended in every locale. Without a
    /// label the command id stands, as data.
    fn note_shell_command_label(label: Option<&DslValue>, command_id: &str, detail: Option<&DslValue>) -> LocalizedLabel {
        let base = match label {
            Some(DslValue::String(text)) => LocalizedLabel::data(text.clone()),
            Some(value @ DslValue::Object(_)) => match (value.get("en").and_then(DslValue::as_str), value.get("de").and_then(DslValue::as_str)) {
                (Some(en), Some(de)) => LocalizedLabel::native(en, de),
                _ => <LocalizedLabel as protocol::FromValue>::from_value(value.clone()).unwrap_or_else(|_| LocalizedLabel::data(command_id)),
            },
            _ => LocalizedLabel::data(command_id),
        };
        match detail.and_then(DslValue::as_str) {
            Some(detail) => LocalizedLabel::from_fn(|terminology, locale| format!("{} - {detail}", base.resolve(terminology, locale))),
            None => base,
        }
    }

    /// 🛠️ A committed tool transaction is one plain edit per touched member (the parent and every owned child it carries,
    /// all stamped with the same ref — design §12); a streamed one is one open edit of the app's own document that its ticks
    /// grow (design §15). Refused instead of silently losing a stamp or a trace: a stream or abort naming no transaction, a
    /// stream or abort across owned children, a stream carrying operations with foreign steps, and an abort carrying
    /// operations.
    fn tool_transaction_shape_fault(verb: &str, transaction: Option<&protocol::TransactionRef>, phase: TransactionPhase, children: bool, carried: bool, foreign: bool) -> Option<Fault> {
        let refuse = |detail: String| Some(Fault::new(FaultOrigin::Framework, FaultCode::new("toolTransaction.shape"), detail));
        let streamed = matches!(phase, TransactionPhase::Stream | TransactionPhase::Abort);
        match transaction {
            None if streamed => refuse(format!("verb {verb:?} streamed or aborted no tool transaction")),
            Some(transaction) if streamed && children => refuse(format!("verb {verb:?} streamed or aborted tool transaction {:?} across owned children; a streamed transaction grows the app's own document", transaction.id)),
            Some(transaction) if phase == TransactionPhase::Stream && foreign => refuse(format!("verb {verb:?} streamed operations with foreign steps into tool transaction {:?}; a streamed transaction grows the app's own document", transaction.id)),
            Some(transaction) if phase == TransactionPhase::Abort && carried => refuse(format!("verb {verb:?} aborted tool transaction {:?} with mutations; an abort carries none", transaction.id)),
            _ => None,
        }
    }

    /// 🎞️ The document-store commands an emission's artifact lane dispatches (design §15): a streamed tick appends to its
    /// transaction's open edit (opening it), a commit closes the open edit of its transaction (appending its last operations
    /// first) or, with none open, records its operations as one edit carrying the ref, an abort reverts the open edit, and an
    /// emission outside a transaction applies as one plain edit. An empty list publishes nothing.
    fn artifact_lane_commands<M>(mutations: Vec<M>, transaction: Option<protocol::TransactionRef>, phase: TransactionPhase, open: Option<&store::OpenToolTransaction>) -> Vec<ArtifactCommand<M>> {
        let open = open.zip(transaction.as_ref()).is_some_and(|(open, transaction)| open.transaction.id == transaction.id);
        let append = |mutations: Vec<M>, transaction: protocol::TransactionRef| (!mutations.is_empty()).then(|| ArtifactCommand::AppendTransaction { mutations, transaction });
        match (transaction, phase) {
            (Some(transaction), TransactionPhase::Stream) => append(mutations, transaction).into_iter().collect(),
            (Some(transaction), TransactionPhase::Commit) if open => {
                let transaction_id = transaction.id.clone();
                append(mutations, transaction).into_iter().chain([ArtifactCommand::CommitTransaction { transaction_id }]).collect()
            }
            (Some(transaction), TransactionPhase::Abort) => open.then(|| ArtifactCommand::AbortTransaction { transaction_id: transaction.id }).into_iter().collect(),
            (_, _) if mutations.is_empty() => Vec::new(),
            (transaction, _) => vec![ArtifactCommand::Apply { mutations, description: None, transaction }],
        }
    }

    /// 🧯️ A batched store publication's refusal: the history and tool-transaction refusals keep their own fault codes
    /// (`history.full`, `toolTransaction.open`, `toolTransaction.unknown` — the shells show them as notices); every other one is
    /// the SDK's publication fault.
    fn store_publication_fault(error: vcs::VcsError) -> Fault {
        match error {
            vcs::VcsError::TransactionOpen { .. } | vcs::VcsError::UnknownTransaction(_) | vcs::VcsError::HistoryFull { .. } => error.into_fault(),
            error => plugin_sdk_fault(error.to_string()),
        }
    }

    fn typed_operation_document_is_fresh(operation: &semio_framework_job::Operation, canonical_revision: [u8; 32], live_revision: [u8; 32], live_generation: u64) -> bool {
        let live_short = semio_framework_job::RevisionId(u64::from_be_bytes(live_revision[..8].try_into().expect("revision lane width")));
        canonical_revision == live_revision && matches!(semio_framework_job::validate_commit(operation, live_short, semio_framework_job::Generation(live_generation)), semio_framework_job::CommitValidation::Accepted)
    }

    include!("🪟️window/🫧️transient/🔁️document-replacement/🦀️.rs");

    /// 🕳️ Which revalidation pass this is, because the same pruning is a feature in one and a defect
    /// in the other: `DocumentChange` runs after every artifact dispatch precisely to drop ids the
    /// document no longer has, `Pick` carries ids a user click or an app's own `InteractionWrite`
    /// just named and owes them to the render.
    #[derive(Clone, Copy, PartialEq, Eq)]
    pub(crate) enum InteractionRevalidateOrigin {
        Pick,
        DocumentChange,
    }

    /// 🕹️ What one applied interaction verb hands back to whichever dispatch carried it
    /// ([`VcsArtifactApp::apply_interaction_verb`]): the app-declared refresh scope for the verb and
    /// the domains it touched, and the leftover `InteractionView` publication the host peels from
    /// `Invocation.output.interactionView` (`interactionViewFromLeftoverOutput`, `🏛️ShellHost`).
    struct AppliedInteractionVerb {
        scope: UiDirtyScope,
        leftover: DslValue,
    }

    /// 🔀️ The outcome of folding a guest emit's interaction verbs inline
    /// ([`VcsArtifactApp::fold_inline_interaction_verbs`]): the carrying emit's `ui_scope` widened by
    /// every applied verb's scope, the LAST applied verb's leftover view (the host publishes one
    /// leftover per invocation, and a later verb's snapshot already includes the earlier ones), and
    /// one diagnostic per verb that faulted instead of applying.
    struct InlineInteractionFold {
        scope: UiDirtyScope,
        leftover: Option<DslValue>,
        diagnostics: Vec<semio_framework_diagnostic::Diagnostic>,
    }

    /// 🩹 Diagnostic code of a guest-emitted interaction verb the reactor could not apply inline —
    /// attached to the carrying command's `InvocationResult.diagnostics`, never raised as its fault.
    pub(crate) const INLINE_INTERACTION_VERB_DIAGNOSTIC_CODE: &str = "interaction.inline-verb-not-applied";

    /// 🔀️ Whether this effect is a guest asking the host to (re)dispatch one of the six framework
    /// interaction verbs (`INTERACTION_ACTION_IDS`), in EITHER of the two shapes apps emit for that
    /// one intent: `Effect::ReplayShellCommand { action_id ∈ … }` (what `interaction_select_effect`
    /// / `interaction_hover_effect` build in most apps) and `Effect::DispatchAction { action ∈ … }`
    /// (what `📏️layout`'s `layout_select_effect`/`layout_hover_effect`/`layout_clear_selection_effect`
    /// and `💡️reasoning`'s `wires_select_effect` build). Every other `ReplayShellCommand` (an
    /// undo/redo inverse replay, an `os.*` shell relay) and every other `DispatchAction` (a
    /// self-dispatch chain, a `probeChildContinuation`, a traced `canvasPointerDown` redispatch) is
    /// NOT one and keeps reaching the host untouched.
    ///
    /// ⏱️ A `DispatchAction` interaction verb with a positive `delay_ms` still folds inline: the delay
    /// was only ever a host-scheduling artefact (a later `onAction` tick) for a state write that is
    /// synchronous in the reactor — deferring a pick behind pointer input issued meanwhile is exactly
    /// the ordering hazard §2 C removes, so no delay is honoured for these six verbs.
    ///
    /// 🔮️ The `req: RequestId` such an effect carries is never a parked `RequestFuture`: a registry-
    /// minted `DispatchAction` (`Host::dispatch_action` → `RequestRegistry::request`) queues on the
    /// registry's own outbound lane and never enters `Emit.effects`, so every one peeled here is an
    /// app struct literal with a placeholder id nothing awaits — dropping it completes nothing late.
    fn is_inline_interaction_verb(effect: &Effect) -> bool {
        match effect {
            Effect::ReplayShellCommand { action_id, .. } => INTERACTION_ACTION_IDS.contains(&action_id.as_str()),
            Effect::DispatchAction { action, .. } => INTERACTION_ACTION_IDS.contains(&action.as_str()),
            _ => false,
        }
    }

    /// 🔀️ Peels every guest-emitted interaction verb out of an emit's effect list — both shapes
    /// [`is_inline_interaction_verb`] admits, in one pass so emission order is kept ACROSS the two
    /// shapes — leaving every other effect in place. The host never sees a peeled verb; the reactor
    /// applies it inline instead ([`VcsArtifactApp::fold_inline_interaction_verbs`]).
    fn take_inline_interaction_verbs(effects: &mut Vec<Effect>) -> Vec<(String, Option<DslValue>)> {
        if !effects.iter().any(is_inline_interaction_verb) {
            return Vec::new();
        }
        let mut folded = Vec::new();
        effects.retain_mut(|effect| {
            if !is_inline_interaction_verb(effect) {
                return true;
            }
            match effect {
                Effect::ReplayShellCommand { action_id, args } => folded.push((std::mem::take(action_id), args.take())),
                Effect::DispatchAction { action, args, .. } => folded.push((std::mem::take(action), args.take())),
                _ => unreachable!("is_inline_interaction_verb admits exactly the two arms above"),
            }
            false
        });
        folded
    }

    /// 🕳️ Whether a `;`-joined [`interaction_selection_witness`] names at least one id — an empty
    /// selection and a present-but-empty domain (`vortex=object:`) are both "nothing was carried".
    fn interaction_witness_names_ids(witness: &str) -> bool {
        witness.split(';').any(|entry| entry.split_once(':').is_some_and(|(_, ids)| !ids.is_empty()))
    }

    /// 🕳️ The ONE predicate that names how a pick disappeared between the ids a dispatch carried and
    /// the ids the app will actually render from, instead of leaving the two silently unequal:
    /// `validate-state-pruned` when [`protocol::validate_state`] dropped them against the topology it
    /// was handed, `persist-skipped` when the validated half compared equal to the stored one so no
    /// edit was ever minted, `store-readback-lost` when the store took the edit and then did not
    /// answer with it. `None` is the healthy case — the render source carries exactly what was
    /// dispatched, whether through the store or through the leftover overlay
    /// [`VcsArtifactApp::interaction_selection_snapshot`] lays over it.
    ///
    /// 🔬️ Ticket 26/09/02/PUZZLE-3D-END-TO-END wave B23: every browser symptom of the
    /// selection-scoped family (`inspection-object-fields id=null`, `locked-flag-row`,
    /// `gumball-scene-delta`, `relocate-pose-delta`) is this predicate answering `Some` where nothing
    /// ever said so.
    pub(crate) fn interaction_selection_loss_v1(dispatched: &str, validated: &str, readback: &str, minted: bool) -> Option<&'static str> {
        if !interaction_witness_names_ids(dispatched) || readback == dispatched {
            return None;
        }
        if validated != dispatched {
            return Some("validate-state-pruned");
        }
        if !minted {
            return Some("persist-skipped");
        }
        Some("store-readback-lost")
    }

    /// 🧹️ Retires the leftover selection overlay for the domains an APP-authored selection write just
    /// moved, and answers the pair `(overlay, leftover_ids)` that must replace the live ones.
    ///
    /// The overlay exists to paper over one specific hole: a pick whose ids the interaction store has
    /// not answered with yet, or that `validate_state` pruned, still has to reach the render
    /// ([`VcsArtifactApp::interaction_selection_snapshot`] lays it over an EMPTY store selection). It
    /// is written only by the framework-reserved pick route, so before this rule existed it also
    /// papered over a deliberate emptying: an app that empties its own selection through
    /// `Emit.interaction_writes` (`MergeMode::Subtractive` — every `ctx.clear_selection()` in every
    /// plugin) had the store answer `[]` correctly and then read the PRE-write ids straight back off
    /// the overlay, forever. Measured 2026-09-12 in-process (ticket 26/09/02/PUZZLE-3D-END-TO-END wave
    /// B31): `write merge=Subtractive current=[object] next=[]`, `persisted=Some([])`, then
    /// `snapshot store=Some([]) overlay=Some([object])` — puzzle3d's `deleteSelection` kept its own
    /// victim selected and its `clear` verb could not clear.
    ///
    /// A write names the newest truth for its domain, so that domain's overlay entry BECOMES the
    /// freshly computed selection (empty included) and the flat leftover ids keep only what is still
    /// selected somewhere. Domains the write never named are untouched, so an unrelated pick in flight
    /// keeps its cover.
    pub(crate) fn leftover_after_app_selection_write_v1(overlay: Option<&protocol::InteractionState>, leftover_ids: &[String], next: &protocol::InteractionState, domains: &[String]) -> (Option<protocol::InteractionState>, Vec<String>) {
        let retired = overlay.map(|overlay| {
            let mut retired = overlay.clone();
            for domain in domains {
                match next.selection.get(domain) {
                    Some(selection) => retired.selection.insert(domain.clone(), selection.clone()),
                    None => retired.selection.remove(domain),
                };
            }
            retired
        });
        let live: Vec<&String> = next.selection.values().flat_map(|selection| selection.ids.iter()).collect();
        (retired, leftover_ids.iter().filter(|id| live.contains(id)).cloned().collect())
    }

    /// 🧹️ What a DOCUMENT CHANGE leaves of the just-validated interaction state, of the leftover
    /// cover laid over it, and of the flat leftover ids — the ONE rule that makes a whole-document
    /// replacement (loading another bundled example, importing a file, reverting) drop the ids the
    /// new document does not have.
    ///
    /// Two holes, both measured on the generation3d React playground 2026-09-14 (ticket
    /// 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️selection-prune-interact-2026-09-14.md`), let a pick
    /// made in one example outlive it into every later one:
    ///
    /// 1. [`protocol::validate_state`] can only prune a domain the topology has an entry for, and
    ///    [`VcsArtifactApp::build_full_interaction_topology`] builds entries for DECLARED domains
    ///    only. The `vortex` mirror [`VcsArtifactApp::overlay_leftover_ids_into_vortex`] writes for
    ///    the panels that read that name is not a declared domain of an app like generation3d, so it
    ///    was never checked against anything and carried `shell@solid` through all eight examples.
    ///    A mirror is a PROJECTION of the real domains, so it may only name what a declared domain
    ///    still names after validation.
    /// 2. The leftover cover exists to carry a pick the interaction store has not answered with yet
    ///    ([`VcsArtifactApp::interaction_selection_snapshot`] lays it over an EMPTY store selection).
    ///    A document change empties that store selection legitimately — so the cover papered straight
    ///    over the prune and put the stale ids back on the very next read. A cover may not outlive
    ///    the ids it was covering.
    ///
    /// A document edit that touches nothing selected leaves all three untouched, so an in-flight pick
    /// during an unrelated edit keeps its cover.
    pub(crate) fn interaction_after_document_change_v1(
        validated: &protocol::InteractionState,
        declared_domains: &[String],
        overlay: Option<&protocol::InteractionState>,
        leftover_ids: &[String],
    ) -> (protocol::InteractionState, Option<protocol::InteractionState>, Vec<String>) {
        let declared_live: Vec<String> = validated.selection.iter().filter(|(domain, _)| declared_domains.contains(domain)).flat_map(|(_, selection)| selection.ids.iter().cloned()).collect();
        let mut pruned = validated.clone();
        for (domain, selection) in pruned.selection.iter_mut() {
            if declared_domains.contains(domain) {
                continue;
            }
            selection.ids.retain(|id| declared_live.contains(id));
            if selection.anchor_id.as_ref().is_some_and(|anchor| !selection.ids.contains(anchor)) {
                selection.anchor_id = None;
            }
        }
        for (domain, hover) in pruned.hover.iter_mut() {
            if declared_domains.contains(domain) {
                continue;
            }
            hover.ids.retain(|id| declared_live.contains(id));
        }
        let retired = overlay.map(|overlay| {
            let mut retired = overlay.clone();
            for selection in retired.selection.values_mut() {
                selection.ids.retain(|id| declared_live.contains(id));
                if selection.anchor_id.as_ref().is_some_and(|anchor| !selection.ids.contains(anchor)) {
                    selection.anchor_id = None;
                }
            }
            retired
        });
        (pruned, retired, leftover_ids.iter().filter(|id| declared_live.contains(id)).cloned().collect())
    }

    /// 🕳️ Records one selection loss on a channel the BROWSER actually shows.
    ///
    /// Deliberately not [`crate::plugin_runtime::debug_runtime_line`]: that channel is gated on
    /// `semio_framework_trace::runtime_diagnostics_enabled()`, which reads an environment variable a
    /// jco-transpiled component in a browser tab does not have, so it is off in exactly the place this
    /// defect lives — measured on wasm #48 (`🗑️generated/probe-2026-09-11T19-11-07.md`: zero
    /// `debug_runtime_line` records in 4 000 console lines, against thousands of plain `eprintln!`
    /// ones from the same guest). A lost pick is a defect report, not a trace, and is emitted only
    /// when one actually happened — the same rule the renderer's own permanent
    /// `refreshUi dropped requested body` record follows.
    fn report_interaction_selection_loss(reason: &str, dispatched: &str, validated: &str, readback: &str, topology: &protocol::InteractionTopology) {
        let domains = topology.domains.iter().map(|(domain, topo)| format!("{domain}:{}", topo.ordered.len())).collect::<Vec<_>>().join(",");
        eprintln!("interaction selection lost reason={reason} dispatched={dispatched} validated={validated} readback={readback} domains={domains}");
    }

