    /// 🧬️ Resolves the `codec` answers of the ONE app of the installed bundle that owns `artifact_schema`. This is
    /// the guest half of `world actor`'s `codec` interface: a host that links no Rust codec for this package selects
    /// a document kind by the same `schema` string `store::ArtifactCodec` is keyed by, and the bundle answers from its
    /// own registered apps. An editor is preferred over a viewer because only an editor's snapshot is the kind's
    /// creation authority; an ambiguous schema is refused rather than resolved by order. Nothing is constructed: the
    /// answers are the functions of the owner's type its registration recorded ([`crate::app::ArtifactCodecTableV1`]).
    fn plugin_artifact_codec<PA: PluginApp>(runtime: &PluginRuntime<PA>, artifact_schema: &str) -> Result<crate::app::ArtifactCodecTableV1, Fault> {
        if artifact_schema.is_empty() || artifact_schema.len() > 256 || artifact_schema.chars().any(char::is_control) {
            return Err(plugin_internal_fault("artifact codec schema identity is empty, oversized or control-bearing"));
        }
        if let Some(fault) = runtime.plugin_assembly_error.try_borrow().map_err(|_| plugin_internal_fault("plugin assembly authority busy"))?.clone() {
            return Err(fault);
        }
        let program = runtime.plugin.try_borrow().map_err(|_| plugin_internal_fault("plugin factory authority busy"))?;
        let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
        let definition = artifact_codec_owner(program, artifact_schema)?;
        program.app_codec(&definition.id).ok_or_else(|| plugin_internal_fault("artifact codec owner has no registered codec"))
    }

    /// 🪪️ The apps of `program` that own `artifact_schema`: those whose registered type opens that document
    /// schema — the primary key `store::ArtifactCodec` and the hub's trusted catalog use — and those whose
    /// dialect names it as an ARTIFACT KIND, the identity build tooling with nothing but a compiled
    /// descriptor asks by (it reads the schema back out of `codec.genesis` and asks by schema after that; a
    /// kind `s.<plugin>.<artifact>` and a `DOCUMENT_SCHEMA` never collide). Pure: nothing is constructed.
    pub(crate) fn artifact_codec_candidates<'a, PA: PluginApp>(program: &'a Plugin<PA>, artifact_schema: &'a str) -> impl Iterator<Item = &'a crate::app::AppDefinition> + 'a {
        program.manifest.apps.iter().filter(move |definition| program.app_document_schema(&definition.id) == Some(artifact_schema) || definition.dialect.artifact_kind == artifact_schema)
    }

    /// 🎯️ The ONE app whose codec answers `artifact_schema`: the owning editor — only an editor's snapshot is the
    /// kind's creation authority — else the owning viewer. Two owners of the same role are refused rather than
    /// resolved by order, and no owner is refused; all of it decided on the declarations.
    pub(crate) fn artifact_codec_owner<'a, PA: PluginApp>(program: &'a Plugin<PA>, artifact_schema: &'a str) -> Result<&'a crate::app::AppDefinition, Fault> {
        let (mut editor, mut viewer) = (None, None);
        for definition in artifact_codec_candidates(program, artifact_schema) {
            let slot = if definition.role == semio_framework::AppRole::Editor { &mut editor } else { &mut viewer };
            if slot.replace(definition).is_some() {
                return Err(plugin_internal_fault("artifact codec schema resolves more than one app of the same role"));
            }
        }
        editor.or(viewer).ok_or_else(|| plugin_internal_fault("artifact codec schema is owned by no app of this bundle"))
    }

    /// 🧬️ `codec.pack-schema-hash` — the kind's own 32-byte snapshot-record fingerprint.
    pub async fn plugin_artifact_pack_schema_hash<PA: PluginApp>(runtime: &PluginRuntime<PA>, artifact_schema: &str) -> Result<[u8; 32], Fault> {
        let codec = plugin_artifact_codec(runtime, artifact_schema)?;
        (codec.pack_schema_hash)().ok_or_else(|| plugin_internal_fault("artifact codec schema has no structural record specification"))
    }

    /// 🏛️ `codec.sqlite-schema` names a registered dialect's handwritten relational declaration.
    pub fn plugin_snapshot_sqlite_schema(dialect: &str) -> Result<String, Fault> {
        let dialect = semio_framework::io_schema::ArtifactDialect::parse_coordinate(dialect).map_err(|error| plugin_internal_fault(&error))?;
        semio_framework::io::io_mechanism::native_snapshot_sqlite_schema(&dialect).map_err(|error| plugin_internal_fault(&error.to_string()))
    }

    /// 📤️ `codec.sqlite-export` executes the exact declared native snapshot provider.
    pub async fn plugin_snapshot_sqlite_export(input: crate::sqlite_wire::SnapshotInput) -> Result<crate::sqlite_wire::SnapshotFileResult, Fault> {
        use semio_framework::io_schema::{ArtifactDialect, IoPayload, SQLITE_SNAPSHOT};
        let limits = input.limits.native().map_err(|error| plugin_internal_fault(&error))?;
        let dialect = ArtifactDialect::parse_coordinate(&input.dialect).map_err(|error| plugin_internal_fault(&error))?;
        let encoding = semio_framework::sqlite_snapshot::SnapshotEncoding::parse(&input.encoding).map_err(|error| plugin_internal_fault(&error.to_string()))?;
        let payload = match encoding {
            semio_framework::sqlite_snapshot::SnapshotEncoding::Binary => IoPayload::Binary(input.payload),
            semio_framework::sqlite_snapshot::SnapshotEncoding::Text => IoPayload::Text(String::from_utf8(input.payload).map_err(|error| plugin_internal_fault(&error.to_string()))?),
        };
        let route = semio_framework::io::io_mechanism::io_route(&dialect, &ArtifactDialect::from(SQLITE_SNAPSHOT), 1).await.map_err(|error| plugin_internal_fault(&error.cause.message))?.value;
        let output = match semio_framework::io::io_mechanism::io_run_with_snapshot_control(&route, payload, limits, &mut |_| true).await {
            Ok(output) => output,
            Err(error) => return Ok(crate::sqlite_wire::SnapshotFileResult::Rejected(crate::sqlite_wire::SnapshotRejection { message: error.cause.into_message(), diagnostics: crate::sqlite_wire::encode_diagnostics(&error.diagnostics) })),
        };
        match output.value {
            IoPayload::Binary(bytes) => Ok(crate::sqlite_wire::SnapshotFileResult::Done(crate::sqlite_wire::SnapshotFile { bytes, diagnostics: crate::sqlite_wire::encode_diagnostics(&output.diagnostics) })),
            IoPayload::Text(_) => Err(plugin_internal_fault("semantic SQLite export must produce binary")),
        }
    }

    /// 📥️ `codec.sqlite-import` validates exact dialect and DDL before reconstructing native values.
    pub async fn plugin_snapshot_sqlite_import(input: crate::sqlite_wire::SnapshotInput) -> Result<crate::sqlite_wire::SnapshotPayloadResult, Fault> {
        use semio_framework::io_schema::{ArtifactDialect, IoPayload, SQLITE_SNAPSHOT};
        let limits = input.limits.native().map_err(|error| plugin_internal_fault(&error))?;
        let dialect = ArtifactDialect::parse_coordinate(&input.dialect).map_err(|error| plugin_internal_fault(&error))?;
        let route = semio_framework::io::io_mechanism::io_route(&ArtifactDialect::from(SQLITE_SNAPSHOT), &dialect, 1).await.map_err(|error| plugin_internal_fault(&error.cause.message))?.value;
        let output = match semio_framework::io::io_mechanism::io_run_with_snapshot_control(&route, IoPayload::Binary(input.payload), limits, &mut |_| true).await {
            Ok(output) => output,
            Err(error) => return Ok(crate::sqlite_wire::SnapshotPayloadResult::Rejected(crate::sqlite_wire::SnapshotRejection { message: error.cause.into_message(), diagnostics: crate::sqlite_wire::encode_diagnostics(&error.diagnostics) })),
        };
        let diagnostics = crate::sqlite_wire::encode_diagnostics(&output.diagnostics);
        Ok(crate::sqlite_wire::SnapshotPayloadResult::Done(match output.value {
            IoPayload::Binary(bytes) => crate::sqlite_wire::SnapshotPayload { encoding: "binary".into(), bytes, diagnostics },
            IoPayload::Text(text) => crate::sqlite_wire::SnapshotPayload { encoding: "text".into(), bytes: text.into_bytes(), diagnostics },
        }))
    }

