}

fn arg_schema_name(schema: &ArgSchema) -> &'static str {
    match schema {
        ArgSchema::String { .. } => "text",
        ArgSchema::Number { integer: true, .. } => "integer",
        _ => "other",
    }
}

#[semio_framework_async_macros::async_test]
