//! ⬇️ The `Effect::DownloadMediaExport` encoding law, driven by the language-agnostic fixture
//! `🧫️fixtures/⬇️media-export-encoding/🔣️.json` that `🎠️kernel/🟦️.ts`'s TypeScript twin drives too.
//!
//! The defect this pins: every binary export in the repo reached disk as base64 TEXT under a binary
//! file name, because the renderer dropped `encoding` on the guest→shell hop
//! (ticket 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️io-surface-2026-09-13.md` §7.3).

use super::*;

#[derive(serde::Deserialize)]
struct EncodingCase {
    id: String,
    encoding: Option<String>,
    data: String,
    bytes: Vec<u8>,
}

#[derive(serde::Deserialize)]
struct RefusalCase {
    id: String,
    encoding: Option<String>,
    data: String,
    error: String,
}

#[derive(serde::Deserialize)]
struct EncodingFixture {
    #[serde(rename = "baseEncoding")]
    base_encoding: String,
    #[serde(rename = "textEncoding")]
    text_encoding: String,
    cases: Vec<EncodingCase>,
    refusals: Vec<RefusalCase>,
}

fn fixture() -> EncodingFixture {
    serde_json::from_str(include_str!("../../🧫️fixtures/⬇️media-export-encoding/🔣️.json")).expect("media-export-encoding fixture JSON")
}

/// ⬇️ Every fixture export decodes to exactly the bytes the fixture declares.
#[test]
fn every_fixture_export_decodes_to_its_declared_bytes() {
    let fixture = fixture();
    assert_eq!(fixture.base_encoding, MEDIA_EXPORT_BASE64_ENCODING);
    assert_eq!(fixture.text_encoding, MEDIA_EXPORT_UTF8_ENCODING);
    assert!(fixture.cases.len() >= 8, "fixture must keep driving both lanes: {}", fixture.cases.len());
    for case in &fixture.cases {
        let decoded = media_export_bytes(&case.data, case.encoding.as_deref()).unwrap_or_else(|error| panic!("{} must decode: {error}", case.id));
        assert_eq!(decoded, case.bytes, "{} decoded to the wrong bytes", case.id);
    }
}

/// 📝️ A textual export is its own UTF-8 bytes, whether it leaves `encoding` absent or states
/// `utf-8` — the two spellings a live producer really uses, and they must answer identically.
#[test]
fn textual_exports_are_their_own_utf8_bytes_under_both_spellings() {
    let fixture = fixture();
    let textual: Vec<&EncodingCase> = fixture.cases.iter().filter(|case| case.encoding.as_deref() != Some(MEDIA_EXPORT_BASE64_ENCODING)).collect();
    assert!(textual.len() >= 3, "the fixture must keep both textual spellings");
    assert!(textual.iter().any(|case| case.encoding.is_none()) && textual.iter().any(|case| case.encoding.as_deref() == Some(MEDIA_EXPORT_UTF8_ENCODING)), "both spellings must be driven");
    for case in textual {
        assert_eq!(media_export_bytes(&case.data, None).expect("textual decode"), case.data.as_bytes(), "{}", case.id);
        assert_eq!(media_export_bytes(&case.data, Some(MEDIA_EXPORT_UTF8_ENCODING)).expect("declared textual decode"), case.data.as_bytes(), "{}", case.id);
    }
}

/// 🚨️ The whole point: a base64 export must NOT come back as the base64 text. This is the assertion
/// the broken shells passed, because they saved `data` verbatim.
#[test]
fn base64_exports_are_never_their_own_base64_text() {
    let fixture = fixture();
    let binary: Vec<&EncodingCase> = fixture.cases.iter().filter(|case| case.encoding.as_deref() == Some(MEDIA_EXPORT_BASE64_ENCODING) && !case.bytes.is_empty()).collect();
    assert!(!binary.is_empty(), "the fixture must keep a binary lane");
    for case in binary {
        let decoded = media_export_bytes(&case.data, Some(MEDIA_EXPORT_BASE64_ENCODING)).expect("base64 decode");
        assert_ne!(decoded, case.data.as_bytes(), "{} was saved as its own base64 text", case.id);
        assert_eq!(decoded, case.bytes, "{}", case.id);
    }
}

/// 🚫️ An encoding no shell reads, and malformed base64, are loud — never a silent text save.
#[test]
fn refusals_are_loud_and_typed() {
    for case in fixture().refusals {
        let error = media_export_bytes(&case.data, case.encoding.as_deref()).expect_err(&format!("{} must refuse", case.id));
        match (case.error.as_str(), &error) {
            ("unsupported", MediaExportEncodingError::Unsupported { .. }) => {}
            ("malformed", MediaExportEncodingError::Malformed { .. }) => {}
            (expected, actual) => panic!("{} expected {expected}, got {actual:?}", case.id),
        }
    }
}

/// 🔬️ Third-party oracle: the `base64` crate (a dev-only dependency, never a runtime one) must agree
/// with this contract on every base64 fixture row, in both directions.
#[test]
fn matches_third_party_base64_oracle_on_every_fixture_row() {
    use base64::Engine as _;
    let oracle = base64::engine::general_purpose::STANDARD;
    for case in fixture().cases.iter().filter(|case| case.encoding.as_deref() == Some(MEDIA_EXPORT_BASE64_ENCODING)) {
        assert_eq!(oracle.decode(&case.data).expect("oracle decode"), case.bytes, "oracle disagrees on {}", case.id);
        assert_eq!(oracle.encode(&case.bytes), case.data, "oracle re-encode disagrees on {}", case.id);
        assert_eq!(media_export_bytes(&case.data, Some(MEDIA_EXPORT_BASE64_ENCODING)).expect("ours"), oracle.decode(&case.data).expect("oracle"), "ours disagrees with the oracle on {}", case.id);
    }
}

/// 📦️ The effect carries the envelope the contract reads — the field really is `Option<String>` on
/// the kernel type, and a `Some("base64")` really does reach the bytes.
#[test]
fn the_effect_envelope_feeds_the_contract() {
    for case in fixture().cases {
        let effect = Effect::DownloadMediaExport { filename: "export.bin".into(), mime_type: "application/octet-stream".into(), data: case.data.clone(), encoding: case.encoding.clone() };
        let Effect::DownloadMediaExport { data, encoding, .. } = &effect else { panic!("variant") };
        assert_eq!(media_export_bytes(data, encoding.as_deref()).expect("envelope decode"), case.bytes, "{}", case.id);
    }
}

use super::*;

/// 🧫️ `🧫️fixtures/🧵️video-render-job/🔣️.json` — folded by this law and by its TypeScript twin alike.
fn fixture() -> serde_json::Value {
    serde_json::from_str(include_str!("../../🧫️fixtures/🧵️video-render-job/🔣️.json")).expect("video render job fixture")
}

fn events(value: &serde_json::Value) -> Vec<VideoRenderJobEvent> {
    serde_json::from_value(value.clone()).expect("fixture events decode")
}

/// ⚖️ LAW: every stream folds, event by event, into exactly the declared running rows and last job id; every event also
/// crosses the value codec (the WIT `pack`) unchanged.
#[test]
fn streams_fold_into_the_declared_task_list() {
    let fixture = fixture();
    assert_eq!(fixture["capability"], MEDIA_VIDEO_RENDER_CAPABILITY);
    for stream in fixture["streams"].as_array().expect("streams") {
        let id = stream["id"].as_str().expect("id");
        let events = events(&stream["events"]);
        let ledger = VideoRenderJobLedger::fold(&events).unwrap_or_else(|(index, error)| panic!("{id}: event {index} refused: {error}"));
        assert_eq!(serde_json::to_value(ledger.running()).expect("rows"), stream["running"], "{id}: running rows");
        assert_eq!(ledger.last_job(), stream["lastJob"].as_u64().expect("lastJob"), "{id}: last job");
        for event in &events {
            let value = dsl::ToValue::to_value(event);
            assert_eq!(&<VideoRenderJobEvent as dsl::FromValue>::from_value(value).expect("value round trip"), event, "{id}: value codec");
        }
        assert_eq!(serde_json::to_value(&events).expect("serde"), stream["events"], "{id}: camelCase wire");
    }
}

/// ⚖️ LAW: the last event of each refusal stream is refused with the declared code and leaves the ledger untouched.
#[test]
fn refused_events_leave_the_ledger_untouched() {
    for case in fixture()["refusals"].as_array().expect("refusals") {
        let id = case["id"].as_str().expect("id");
        let events = events(&case["events"]);
        let (last, head) = events.split_last().expect("at least one event");
        let mut ledger = VideoRenderJobLedger::fold(head).unwrap_or_else(|(index, error)| panic!("{id}: head event {index} refused: {error}"));
        let before = ledger.clone();
        let error = ledger.apply(last).expect_err("refused");
        assert_eq!(error.code(), case["error"].as_str().expect("error"), "{id}: {error}");
        assert_eq!(ledger, before, "{id}: a refused event changes nothing");
        assert_eq!(VideoRenderJobLedger::fold(&events).expect_err("the whole log is refused").0, head.len(), "{id}: fold names the refused index");
    }
}

//! 🧾️ The history wire law, driven by the language-agnostic fixture `🧫️fixtures/🧫️history-patch/🔣️.json` that the
//! TypeScript twin (`🧪️tests/🧪️history-patch/🟦️.ts`) validates with Ajv: every valid patch decodes to the same value
//! through serde and through `FromValue`, survives both re-encodings, and folds its rows under the fixture keys; every
//! invalid patch is refused by both decoders.

use super::*;

const FIXTURE: &str = include_str!("../../🧫️fixtures/🧫️history-patch/🔣️.json");

fn cases(section: &str) -> Vec<(String, serde_json::Value, serde_json::Value)> {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE).expect("the history patch fixture is JSON");
    fixture[section].as_array().expect("fixture section").iter().map(|case| (case["id"].as_str().expect("case id").to_string(), case["patch"].clone(), case.get("keys").cloned().unwrap_or(serde_json::Value::Null))).collect()
}

fn value_decode(json: &serde_json::Value) -> Result<HistoryPatch, dsl::ValueError> {
    let value = semio_framework_pack_json::to_dsl_value(&semio_framework_pack_json::parse(&json.to_string(), semio_framework_pack_json::JsonMemberPolicy::Reject).expect("fixture patch is JSON"));
    <HistoryPatch as dsl::FromValue>::from_value(value)
}

#[test]
fn every_valid_patch_decodes_identically_through_serde_and_value_and_round_trips() {
    for (id, json, keys) in cases("valid") {
        let by_serde: HistoryPatch = serde_json::from_value(json.clone()).unwrap_or_else(|error| panic!("{id}: serde refused a valid patch: {error}"));
        let by_value = value_decode(&json).unwrap_or_else(|error| panic!("{id}: FromValue refused a valid patch: {error}"));
        assert_eq!(by_serde, by_value, "{id}: serde and value decode differently");
        let reserialized: HistoryPatch = serde_json::from_value(serde_json::to_value(&by_serde).expect("serde encodes")).expect("serde decodes its own encoding");
        assert_eq!(reserialized, by_serde, "{id}: serde round trip");
        let revalued = <HistoryPatch as dsl::FromValue>::from_value(dsl::ToValue::to_value(&by_value)).expect("value decodes its own encoding");
        assert_eq!(revalued, by_value, "{id}: value round trip");
        let folded: Vec<String> = by_value.upserts.iter().map(HistoryEntry::key).collect();
        let expected: Vec<String> = keys.as_array().expect("keys").iter().map(|key| key.as_str().expect("key").to_string()).collect();
        assert_eq!(folded, expected, "{id}: row keys");
    }
}

#[test]
fn every_invalid_patch_is_refused_by_both_decoders() {
    for (id, json, _) in cases("invalid") {
        assert!(serde_json::from_value::<HistoryPatch>(json.clone()).is_err(), "{id}: serde accepted an invalid patch");
        assert!(value_decode(&json).is_err(), "{id}: FromValue accepted an invalid patch");
    }
}

#[test]
fn an_absent_time_travel_is_omitted_from_both_encodings() {
    let patch = HistoryPatch { cursor: 1, ..HistoryPatch::default() };
    assert!(serde_json::to_value(&patch).expect("serde encodes").get("timeTravel").is_none());
    assert!(dsl::ToValue::to_value(&patch).get("timeTravel").is_none());
}

//! 📤️ The `Effect::RequestFileOpen` import law, driven by the language-agnostic fixture
//! `🧫️fixtures/📤️file-open-import/🔣️.json` that `🎠️kernel/🟦️.ts`'s TypeScript twin drives too.
//!
//! The defects this pins, all measured on 6118 for ticket 26/09/09/PROCEDURAL-3D-END-TO-END:
//!   1. the wgpu door dropped `request-file-open` outright (`unmapped effect … dropped`), so
//!      `Import Document…` reached the guest, produced its effect, and stopped there;
//!   2. the two renderers disagreed about what one import invocation carries — React sent
//!      `{payload, name, chunk, chunkCount}` per chunk, the wgpu shell `{json, payload}` once;
//!   3. an unchunked import asks the fixed guest heap for one contiguous block the size of the whole
//!      file, several times its own per-request ceiling;
//!   4. `chunk`/`chunkCount` are `u32` in the guest, and `FromValue`'s unsigned arm refuses a float —
//!      so the envelope's integers may never widen on a lossy hop.

use super::*;

#[derive(serde::Deserialize)]
struct PayloadRepeat {
    character: String,
    count: usize,
}

#[derive(serde::Deserialize)]
struct ChunkCase {
    id: String,
    #[serde(default)]
    payload: Option<String>,
    #[serde(rename = "payloadRepeat", default)]
    payload_repeat: Option<PayloadRepeat>,
    #[serde(default)]
    chunks: Option<Vec<String>>,
    #[serde(rename = "chunkLengths", default)]
    chunk_lengths: Option<Vec<usize>>,
    #[serde(rename = "chunkByteLengths", default)]
    chunk_byte_lengths: Option<Vec<usize>>,
}

impl ChunkCase {
    fn payload(&self) -> String {
        match (&self.payload, &self.payload_repeat) {
            (Some(text), _) => text.clone(),
            (None, Some(repeat)) => repeat.character.repeat(repeat.count),
            (None, None) => panic!("{} states neither `payload` nor `payloadRepeat`", self.id),
        }
    }
}

#[derive(serde::Deserialize)]
struct FanOut {
    index: usize,
    total: usize,
}

#[derive(serde::Deserialize)]
struct ArgumentChunk {
    payload: String,
    chunk: usize,
    #[serde(rename = "chunkCount")]
    chunk_count: usize,
}

#[derive(serde::Deserialize)]
struct ArgumentCase {
    id: String,
    name: String,
    chunk: ArgumentChunk,
    #[serde(rename = "fanOut")]
    fan_out: Option<FanOut>,
    arguments: serde_json::Map<String, serde_json::Value>,
}

#[derive(serde::Deserialize)]
struct FileOpenImportFixture {
    #[serde(rename = "importChunkBytes")]
    import_chunk_bytes: usize,
    #[serde(rename = "chunkCases")]
    chunk_cases: Vec<ChunkCase>,
    #[serde(rename = "argumentCases")]
    argument_cases: Vec<ArgumentCase>,
}

fn fixture() -> FileOpenImportFixture {
    serde_json::from_str(include_str!("../../🧫️fixtures/📤️file-open-import/🔣️.json")).expect("file-open-import fixture JSON")
}

/// 📏️ The chunk extent is derived from the guest's own contiguous-request ceiling, and the fixture
/// records the same number both twins compute.
#[test]
fn the_chunk_extent_is_half_the_guest_contiguous_ceiling() {
    assert_eq!(IMPORT_CHUNK_BYTES, semio_framework_trace::GUEST_CONTIGUOUS_REQUEST_CEILING_BYTES / 2);
    assert_eq!(fixture().import_chunk_bytes, IMPORT_CHUNK_BYTES);
}

/// 📥️ Every fixture payload slices into exactly the chunks it declares, positioned as its own run.
#[test]
fn every_fixture_payload_slices_into_its_declared_chunks() {
    let fixture = fixture();
    assert!(fixture.chunk_cases.len() >= 6, "fixture rows: {}", fixture.chunk_cases.len());
    for case in &fixture.chunk_cases {
        let payload = case.payload();
        let chunks = import_payload_chunks(&payload);
        if let Some(expected) = &case.chunks {
            assert_eq!(chunks.iter().map(|chunk| chunk.payload.clone()).collect::<Vec<_>>(), *expected, "{}", case.id);
        }
        if let Some(expected) = &case.chunk_lengths {
            assert_eq!(chunks.iter().map(|chunk| chunk.payload.chars().count()).collect::<Vec<_>>(), *expected, "{} character lengths", case.id);
        }
        if let Some(expected) = &case.chunk_byte_lengths {
            assert_eq!(chunks.iter().map(|chunk| chunk.payload.len()).collect::<Vec<_>>(), *expected, "{} byte lengths", case.id);
        }
        for (position, chunk) in chunks.iter().enumerate() {
            assert_eq!(chunk.chunk, position, "{} names its position", case.id);
            assert_eq!(chunk.chunk_count, chunks.len(), "{} names its run length", case.id);
        }
    }
}

/// 🧊️ No chunk may exceed the extent the guest can serve as one contiguous block, and reassembling
/// the run must give the payload back byte for byte — the whole reason the slicing exists.
#[test]
fn no_chunk_exceeds_the_extent_and_the_run_reassembles_exactly() {
    for case in fixture().chunk_cases {
        let payload = case.payload();
        let chunks = import_payload_chunks(&payload);
        assert!(!chunks.is_empty(), "{} must produce at least one chunk", case.id);
        for chunk in &chunks {
            assert!(chunk.payload.len() <= IMPORT_CHUNK_BYTES, "{} chunk {} is {} B", case.id, chunk.chunk, chunk.payload.len());
        }
        assert_eq!(chunks.iter().map(|chunk| chunk.payload.as_str()).collect::<String>(), payload, "{} must reassemble", case.id);
    }
}

/// 🔬️ Third-party oracle: `std`'s own UTF-8 boundary discipline. Every chunk boundary of every
/// fixture payload must be a character boundary of the ORIGINAL string — a slice counted in UTF-16
/// units would land inside a code point on the multibyte rows.
#[test]
fn every_chunk_boundary_is_a_utf8_character_boundary_of_the_payload() {
    for case in fixture().chunk_cases {
        let payload = case.payload();
        let mut cut = 0usize;
        for chunk in import_payload_chunks(&payload) {
            assert!(payload.is_char_boundary(cut), "{} cut {cut} is not a character boundary", case.id);
            assert_eq!(&payload[cut..cut + chunk.payload.len()], chunk.payload, "{} chunk {} is not the payload's own slice", case.id, chunk.chunk);
            cut += chunk.payload.len();
        }
        assert_eq!(cut, payload.len(), "{} must consume the whole payload", case.id);
    }
}

/// 📥️ One chunk's dispatch arguments are exactly the fixture's, with the fan-out present only for a
/// multi-file pick.
#[test]
fn every_chunk_dispatches_its_declared_arguments() {
    let fixture = fixture();
    assert!(fixture.argument_cases.len() >= 3, "fixture rows: {}", fixture.argument_cases.len());
    for case in &fixture.argument_cases {
        let chunk = ImportChunk { payload: case.chunk.payload.clone(), chunk: case.chunk.chunk, chunk_count: case.chunk.chunk_count };
        let arguments = import_chunk_arguments(&case.name, &chunk, case.fan_out.as_ref().map(|fan_out| (fan_out.index, fan_out.total)));
        let DslValue::Object(entries) = &arguments else { panic!("{} must build an object", case.id) };
        assert_eq!(entries.len(), case.arguments.len(), "{} argument count", case.id);
        for (key, expected) in &case.arguments {
            let actual = entries.iter().find(|(name, _)| name == key).map(|(_, value)| value).unwrap_or_else(|| panic!("{} is missing {key}", case.id));
            match expected {
                serde_json::Value::String(text) => assert_eq!(actual, &DslValue::String(text.clone()), "{} {key}", case.id),
                serde_json::Value::Number(number) => {
                    let DslValue::Number(actual_number) = actual else { panic!("{} {key} must be a number", case.id) };
                    assert!(actual_number.is_integer(), "{} {key} widened onto a float, which the guest's `u32` decode refuses", case.id);
                    assert_eq!(actual_number.as_u64(), number.as_u64(), "{} {key}", case.id);
                }
                other => panic!("{} {key} has an unsupported fixture shape {other:?}", case.id),
            }
        }
        assert_eq!(case.fan_out.is_some(), case.arguments.contains_key(IMPORT_ARGUMENT_INDEX), "{} fan-out presence", case.id);
    }
}

/// 🚨️ The envelope's positions are exact unsigned integers. A float here is the shape that took every
/// wgpu dispatch down once the view state first carried a `u64`.
#[test]
fn the_chunk_envelope_never_widens_its_integers_onto_floats() {
    let chunk = ImportChunk { payload: "x".into(), chunk: 2, chunk_count: 5 };
    let DslValue::Object(entries) = import_chunk_arguments("a.stl", &chunk, Some((1, 3))) else { panic!("object") };
    for key in [IMPORT_ARGUMENT_CHUNK, IMPORT_ARGUMENT_CHUNK_COUNT, IMPORT_ARGUMENT_INDEX, IMPORT_ARGUMENT_TOTAL] {
        let (_, value) = entries.iter().find(|(name, _)| name == key).unwrap_or_else(|| panic!("missing {key}"));
        let DslValue::Number(number) = value else { panic!("{key} must be a number") };
        assert!(number.is_integer(), "{key} must stay an exact integer");
        assert_eq!(<u32 as dsl::FromValue>::from_value(value.clone()).unwrap_or_else(|error| panic!("{key} must decode as the guest's own u32: {error}")), match key {
            IMPORT_ARGUMENT_CHUNK => 2,
            IMPORT_ARGUMENT_CHUNK_COUNT => 5,
            IMPORT_ARGUMENT_INDEX => 1,
            _ => 3,
        });
    }
}

/// 📦️ The effect really carries the envelope the shells read — `read_as` is optional, `multiple` is
/// not, and `import_action` is the verb a shell re-dispatches once per chunk.
#[test]
fn the_effect_envelope_names_the_verb_a_shell_redispatches() {
    let effect = Effect::RequestFileOpen { req: RequestId(131), accept: ".stl".into(), read_as: Some("dataUrl".into()), import_action: "importDocument".into(), multiple: false, args: None };
    let Effect::RequestFileOpen { req, accept, read_as, import_action, multiple, .. } = &effect else { panic!("variant") };
    assert_eq!(req.0, 131);
    assert_eq!(accept, ".stl");
    assert_eq!(read_as.as_deref(), Some("dataUrl"));
    assert_eq!(import_action, "importDocument");
    assert!(!multiple);
}

/// 🌉️ The friendly JSON each renderer door produces is exactly what this crate parses back into an
/// `Effect` — the seam the wgpu bridge crosses as `InvocationResult.requested_effects` text.
#[test]
fn every_fixture_friendly_effect_parses_back_into_the_kernel_effect() {
    #[derive(serde::Deserialize)]
    struct WireCase {
        id: String,
        friendly: serde_json::Value,
    }
    #[derive(serde::Deserialize)]
    struct WireFixture {
        #[serde(rename = "wireCases")]
        wire_cases: Vec<WireCase>,
    }
    let fixture: WireFixture = serde_json::from_str(include_str!("../../🧫️fixtures/📤️file-open-import/🔣️.json")).expect("fixture JSON");
    assert!(fixture.wire_cases.len() >= 4, "fixture rows: {}", fixture.wire_cases.len());
    for case in fixture.wire_cases {
        let effect: Effect = serde_json::from_value(case.friendly.clone()).unwrap_or_else(|error| panic!("{} must parse: {error}", case.id));
        let Effect::RequestFileOpen { accept, import_action, .. } = &effect else { panic!("{} must be a RequestFileOpen", case.id) };
        let expected = case.friendly.get("requestFileOpen").expect("friendly shape");
        assert_eq!(accept, expected.get("accept").and_then(serde_json::Value::as_str).unwrap_or_default(), "{}", case.id);
        assert_eq!(import_action, expected.get("importAction").and_then(serde_json::Value::as_str).unwrap_or_default(), "{}", case.id);
        assert_eq!(serde_json::to_value(&effect).unwrap()["requestFileOpen"]["args"], expected["args"], "{}: retained invocation arguments", case.id);
    }
}

//#region 📥️ImportStaging
#[derive(serde::Deserialize)]
struct StagingRun {
    name: String,
    #[serde(default)]
    payload: Option<String>,
    #[serde(rename = "payloadRepeat", default)]
    payload_repeat: Option<PayloadRepeat>,
    #[serde(rename = "fanOut", default)]
    fan_out: Option<FanOut>,
}

impl StagingRun {
    fn payload(&self) -> String {
        match (&self.payload, &self.payload_repeat) {
            (Some(text), _) => text.clone(),
            (None, Some(repeat)) => repeat.character.repeat(repeat.count),
            (None, None) => panic!("staging run {} states neither `payload` nor `payloadRepeat`", self.name),
        }
    }
}

#[derive(serde::Deserialize)]
struct StagingSend {
    run: usize,
    chunk: usize,
    #[serde(rename = "chunkCount", default)]
    chunk_count: Option<usize>,
    #[serde(rename = "payloadRepeat", default)]
    payload_repeat: Option<PayloadRepeat>,
}

#[derive(serde::Deserialize)]
struct StagingCase {
    id: String,
    runs: Vec<StagingRun>,
    #[serde(default)]
    extra: serde_json::Map<String, serde_json::Value>,
    sends: Vec<StagingSend>,
    outcomes: Vec<String>,
    #[serde(rename = "openRunsAfter")]
    open_runs_after: usize,
}

#[derive(serde::Deserialize)]
struct StagingFixture {
    #[serde(rename = "stagingCases")]
    staging_cases: Vec<StagingCase>,
}

/// ⚖️ LAW: every staging case of the language-agnostic fixture — a chunk sequence exactly as a shell dispatches it
/// ([`import_chunk_arguments`]) — reassembles or refuses exactly as stated; a whole file reaches the app as
/// `payload` + `name` (+ fan-out and every other argument) byte for byte, never with its chunk envelope; and the
/// staging keeps no run it should not (memory bound: at most [`IMPORT_STAGING_RUNS`] open runs).
#[test]
fn every_staging_case_reassembles_or_refuses_exactly_as_the_fixture_states() {
    let fixture: StagingFixture = serde_json::from_str(include_str!("../../🧫️fixtures/📤️file-open-import/🔣️.json")).expect("file-open-import fixture JSON");
    assert!(fixture.staging_cases.len() >= 9, "fixture rows: {}", fixture.staging_cases.len());
    for case in &fixture.staging_cases {
        assert_eq!(case.sends.len(), case.outcomes.len(), "{} states one outcome per send", case.id);
        let payloads: Vec<String> = case.runs.iter().map(StagingRun::payload).collect();
        let chunks: Vec<Vec<ImportChunk>> = payloads.iter().map(|payload| import_payload_chunks(payload)).collect();
        let mut staging = ImportStaging::default();
        for (send, expected) in case.sends.iter().zip(&case.outcomes) {
            let run = &case.runs[send.run];
            let derived = &chunks[send.run][send.chunk.min(chunks[send.run].len() - 1)];
            let chunk = ImportChunk {
                payload: send.payload_repeat.as_ref().map_or_else(|| derived.payload.clone(), |repeat| repeat.character.repeat(repeat.count)),
                chunk: send.chunk,
                chunk_count: send.chunk_count.unwrap_or(derived.chunk_count),
            };
            let DslValue::Object(mut entries) = import_chunk_arguments(&run.name, &chunk, run.fan_out.as_ref().map(|fan_out| (fan_out.index, fan_out.total))) else { panic!("{} must build an object", case.id) };
            for (key, value) in &case.extra {
                entries.push((key.clone(), DslValue::String(value.as_str().unwrap_or_else(|| panic!("{} extra {key} must be text", case.id)).to_string())));
            }
            let outcome = staging.admit_args(Some(&DslValue::Object(entries)));
            let actual = match &outcome {
                Ok(ImportArguments::NotAnImport) => "not-an-import".to_string(),
                Ok(ImportArguments::Staged { next_chunk, chunk_count }) => format!("staged:{next_chunk}/{chunk_count}"),
                Ok(ImportArguments::Whole(_)) => format!("whole:{}", send.run),
                Err(refusal) => format!("refused:{}", refusal.code()),
            };
            assert_eq!(&actual, expected, "{} send run {} chunk {}", case.id, send.run, send.chunk);
            if let Ok(ImportArguments::Whole(DslValue::Object(arguments))) = outcome {
                let get = |key: &str| arguments.iter().find(|(name, _)| name == key).map(|(_, value)| value.clone());
                assert_eq!(get(IMPORT_ARGUMENT_PAYLOAD), Some(DslValue::String(payloads[send.run].clone())), "{} reassembles run {} byte for byte", case.id, send.run);
                assert_eq!(get(IMPORT_ARGUMENT_NAME), Some(DslValue::String(run.name.clone())), "{} names the file", case.id);
                assert!(get(IMPORT_ARGUMENT_CHUNK).is_none() && get(IMPORT_ARGUMENT_CHUNK_COUNT).is_none(), "{} the chunk envelope never reaches the app", case.id);
                assert_eq!(get(IMPORT_ARGUMENT_INDEX).and_then(|value| value.as_u64()), run.fan_out.as_ref().map(|fan_out| fan_out.index as u64), "{} keeps the multi-file position", case.id);
                for (key, value) in &case.extra {
                    assert_eq!(get(key), value.as_str().map(|text| DslValue::String(text.to_string())), "{} keeps {key}", case.id);
                }
            }
        }
        assert_eq!(staging.open_runs().len(), case.open_runs_after, "{} open runs after its last send", case.id);
        assert!(staging.open_runs().len() <= IMPORT_STAGING_RUNS, "{} holds at most the run slots", case.id);
    }
}

/// ⚖️ LAW: arguments that carry no chunk envelope are no import — every ordinary action passes the staging untouched.
#[test]
fn arguments_without_a_chunk_envelope_are_not_an_import() {
    let mut staging = ImportStaging::default();
    assert_eq!(staging.admit_args(None), Ok(ImportArguments::NotAnImport));
    assert_eq!(staging.admit_args(Some(&DslValue::object([("value".to_string(), DslValue::String("x".into()))]))), Ok(ImportArguments::NotAnImport));
    assert_eq!(staging.admit_args(Some(&DslValue::String("x".into()))), Ok(ImportArguments::NotAnImport));
}

/// ⚖️ LAW: a cancel drops every open run, and the staged bytes of a run never exceed its byte authority.
#[test]
fn cancel_drops_every_open_run_and_a_run_stays_within_its_byte_authority() {
    let payload = "é".repeat(40_000);
    let chunks = import_payload_chunks(&payload);
    let mut staging = ImportStaging::default();
    assert_eq!(staging.admit_args(Some(&import_chunk_arguments("a.json", &chunks[0], None))), Ok(ImportArguments::Staged { next_chunk: 1, chunk_count: 3 }));
    let (_, _, _, bytes) = staging.open_runs()[0].clone();
    assert!(bytes <= IMPORT_STAGING_MAXIMUM_BYTES);
    assert_eq!(bytes, chunks[0].payload.len());
    staging.cancel_all();
    assert!(staging.open_runs().is_empty());
    assert_eq!(staging.admit_args(Some(&import_chunk_arguments("a.json", &chunks[1], None))), Err(ImportStagingRefusal::Gap));
}
