#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RetainedValueRole {
    Count,
    FieldId,
    Integer,
    Unsigned,
    Enum,
    Symbol,
    Chunk,
    StringLength,
    BytesLength,
    TableRows,
    TableField,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RetainedValueContainer {
    Record,
    Tuple,
    List,
    Statements,
    Map,
    ChunkedBytes,
    Table,
    PackedF64,
    PackedVarint,
    Wire,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RetainedValueToken {
    Tag { offset: u64, value: u8 },
    Begin { kind: RetainedValueContainer, count: u64 },
    Unsigned { role: RetainedValueRole, value: u64 },
    Signed(i64),
    F64(u64),
    StringChar(char),
    Byte(u8),
    WirePresence(u8),
    WireNodePresence(u8),
    WireLabelPresence(u8),
