use crate::test_allocation::observe;

#[test]
fn sqlite_snapshot_native_encoding_borrowed_object_sort_keeps_payload_allocations_bounded() {
    let fixture: serde_json::Value = serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
    let bytes = fixture["payloadBytes"].as_u64().unwrap() as usize;
    let depth = fixture["depth"].as_u64().unwrap() as usize;
    let wide = fixture["unsigned"].as_str().unwrap().parse::<u64>().unwrap();
    let bits = u64::from_str_radix(fixture["binary64Bits"].as_str().unwrap(), 16).unwrap();
    let mut value = DslValue::Object(vec![("zPayload".into(), DslValue::String("x".repeat(bytes))), ("wide".into(), DslValue::uint(wide)), ("exceptional".into(), DslValue::Number(Number::Float(f64::from_bits(bits))))]);
    for _ in 0..depth { value = DslValue::Object(vec![("z".into(), DslValue::Bool(true)), ("a".into(), value)]); }
    let spec = RecordSpec::new(None, RecordLayout::Lines, vec![FieldSpec::new(1, "value", Shape::Value)]);
    let mut record = RecordValue::default(); record.fields.insert(1, FieldValue::Value(value));
    let (text, allocated) = observe(|| print(&record, &spec, JoinMode::Document));
    assert!(allocated <= bytes * fixture["allocationMultiplier"].as_u64().unwrap() as usize, "printing allocated {allocated} bytes for a {bytes}-byte payload at depth {depth}");
    assert!(text.find("a=").unwrap() < text.find("z=").unwrap());
    let restored = parse(&text, &spec, &ParseOptions { limits: Limits { max_bytes: bytes * 2, ..Limits::default() }, mode: SourceMode::Document }).unwrap();
    let FieldValue::Value(node) = restored.get(1).unwrap() else { panic!("owned value"); }; let mut node = node;
    for _ in 0..depth { node = node.get("a").unwrap(); }
    assert_eq!(node.get("wide").unwrap().as_u64(), Some(wide));
    assert_eq!(node.get("exceptional").unwrap().as_f64().unwrap().to_bits(), bits);
    assert_eq!(node.get("zPayload").unwrap().as_str().unwrap().len(), bytes);
    let output = std::process::Command::new("bun").args(["-e", "import {Database} from 'bun:sqlite';const db=new Database(':memory:');db.run('CREATE TABLE keys(value TEXT)');for(const key of ['zPayload','wide','exceptional'])db.run('INSERT INTO keys VALUES(?)',[key]);await Bun.write(Bun.stdout,JSON.stringify(db.query('SELECT value FROM keys ORDER BY value COLLATE BINARY').all().map(row=>row.value)));db.close();"]).output().unwrap();
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let ordered: Vec<String> = serde_json::from_slice(&output.stdout).unwrap();
    let positions = ordered.iter().map(|key| text.find(&format!("{key}=")).unwrap()).collect::<Vec<_>>();
    assert!(positions.windows(2).all(|pair| pair[0] < pair[1]));
    assert!(parse("value={ a=", &spec, &ParseOptions::default()).is_err());
}

//! 🔢️ Exact IEEE words across owned DSL, pack and field-width boundaries.
use crate::os_dsl::{self,DslField,FieldSpec,FieldValue,JoinMode,Number,ParseOptions,RecordLayout,RecordSpec,RecordValue,Shape,DslValue};
use crate::os_pack::{self,EncodeOptions,DecodeOptions};
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn words64()->Vec<u64>{corpus()["binary64Bits"].as_array().unwrap().iter().map(|value|u64::from_str_radix(value.as_str().unwrap(),16).unwrap()).collect()}
fn words32()->Vec<u32>{corpus()["binary32Bits"].as_array().unwrap().iter().map(|value|u32::from_str_radix(value.as_str().unwrap(),16).unwrap()).collect()}
fn float(value:&FieldValue)->f64{match value{FieldValue::Float(value)=>*value,_=>panic!("expected owned float")}}
fn spec()->RecordSpec{RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"value",Shape::Float),FieldSpec::new(2,"values",Shape::List(Box::new(Shape::Float)))])}
fn record(words:&[u64])->RecordValue{let mut record=RecordValue::default();record.fields.insert(1,FieldValue::Float(f64::from_bits(words[0])));record.fields.insert(2,FieldValue::List(words.iter().map(|word|FieldValue::Float(f64::from_bits(*word))).collect()));record}
fn assert_record(value:&RecordValue,words:&[u64]){assert_eq!(float(value.get(1).unwrap()).to_bits(),words[0]);let FieldValue::List(values)=value.get(2).unwrap()else{panic!("expected float list")};assert_eq!(values.iter().map(|value|float(value).to_bits()).collect::<Vec<_>>(),words);}
#[test]
fn ieee_payload_native_literal_words_are_exact_at_both_widths(){let data=corpus();for word in words64(){let value=f64::from_bits(word);let text=semio_framework_dsl::format_f64(value);assert_eq!(semio_framework_dsl::parse_f64(&text).unwrap().to_bits(),word);if value.is_nan(){assert_eq!(text,format!("{}{:016x}",data["binary64NanPrefix"].as_str().unwrap(),word));}}for word in words32(){let value=f32::from_bits(word);let text=semio_framework_dsl::format_f32(value);assert_eq!(semio_framework_dsl::parse_f32(&text).unwrap().to_bits(),word);if value.is_nan(){assert_eq!(text,format!("{}{:08x}",data["binary32NanPrefix"].as_str().unwrap(),word));}}for text in data["invalid64"].as_array().unwrap(){assert!(semio_framework_dsl::parse_f64(text.as_str().unwrap()).is_err());}for text in data["invalid32"].as_array().unwrap(){assert!(semio_framework_dsl::parse_f32(text.as_str().unwrap()).is_err());}}
#[test]
fn ieee_payload_scalar_and_packed_lists_preserve_every_word(){let words=words64();for &word in &words{let mut rotated=words.clone();rotated[0]=word;let input=record(&rotated);let bytes=os_pack::encode_document(&spec(),&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_document(&bytes,&spec(),&DecodeOptions::default()).unwrap();assert_record(&restored,&rotated);let body=os_pack::encode_record_body(&spec(),&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_record_body(&body,&spec(),&DecodeOptions::default()).unwrap();assert_record(&restored,&rotated);}}
#[test]
fn ieee_payload_dsl_scalar_and_numeric_list_preserve_every_word(){let words=words64();for &word in &words{let mut rotated=words.clone();rotated[0]=word;let input=record(&rotated);let text=os_dsl::print(&input,&spec(),JoinMode::Document);assert_record(&os_dsl::parse(&text,&spec(),&ParseOptions::default()).unwrap(),&rotated);}}
#[test]
fn ieee_payload_generic_value_preserves_every_word(){let spec=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(1,"value",Shape::Value)]);for word in words64(){let mut input=RecordValue::default();input.fields.insert(1,FieldValue::Value(DslValue::Number(Number::Float(f64::from_bits(word)))));let bytes=os_pack::encode_document(&spec,&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_document(&bytes,&spec,&DecodeOptions::default()).unwrap();let FieldValue::Value(DslValue::Number(Number::Float(value)))=restored.get(1).unwrap()else{panic!("expected generic float")};assert_eq!(value.to_bits(),word);let text=os_dsl::print(&input,&spec,JoinMode::Document);let restored=os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap();let FieldValue::Value(DslValue::Number(Number::Float(value)))=restored.get(1).unwrap()else{panic!("expected generic float")};assert_eq!(value.to_bits(),word);}}
#[test]
fn ieee_payload_binary32_field_conversion_preserves_signaling_payloads(){for word in words32(){let value=f32::from_bits(word);let encoded=<f32 as DslField>::to_value(&value);assert_eq!(<f32 as DslField>::from_value(&encoded).unwrap().to_bits(),word);let spec=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(1,"value",<f32 as DslField>::shape())]);let mut input=RecordValue::default();input.fields.insert(1,encoded);let bytes=os_pack::encode_document(&spec,&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_document(&bytes,&spec,&DecodeOptions::default()).unwrap();assert_eq!(<f32 as DslField>::from_value(restored.get(1).unwrap()).unwrap().to_bits(),word);let text=os_dsl::print(&input,&spec,JoinMode::Document);let restored=os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap();assert_eq!(<f32 as DslField>::from_value(restored.get(1).unwrap()).unwrap().to_bits(),word);}}

fn oracle(body:&[u8],words:&[u64]){use std::{io::Write,process::{Command,Stdio}};let expected=serde_json::to_string(&words.iter().map(|word|format!("{word:016x}")).collect::<Vec<_>>()).unwrap();let script=r#"import assert from 'node:assert/strict';import{Database}from'bun:sqlite';const words=__WORDS__.map(value=>BigInt('0x'+value));const bytes=new Uint8Array(await Bun.stdin.arrayBuffer()),view=new DataView(bytes.buffer);let offset=0;function integer(){let value=0,shift=0;for(;;){const byte=bytes[offset++];assert.ok(byte!==undefined);value+=(byte&127)*2**shift;if(!(byte&128))return value;shift+=7;assert.ok(shift<53)}}function word(expected){assert.equal(view.getBigUint64(offset,true),expected);offset+=8}assert.equal(integer(),0);const count=integer();if(count===2){assert.equal(integer(),1);assert.equal(bytes[offset++],5);word(words[0]);assert.equal(integer(),2);assert.equal(bytes[offset++],21);assert.equal(integer(),words.length);for(const expected of words)word(expected)}else{assert.equal(count,1);assert.equal(integer(),1);assert.equal(bytes[offset++],20);assert.equal(integer(),words.length);assert.equal(integer(),1);assert.equal(integer(),1);assert.equal(bytes[offset++],0);assert.equal(bytes[offset++],4);for(const expected of words)word(expected)}assert.equal(offset,bytes.length);const db=new Database(':memory:');db.run('CREATE TABLE exact_word(ordinal INTEGER PRIMARY KEY,word BLOB NOT NULL CHECK(length(word)=8))');for(let index=0;index<words.length;index++){const raw=new Uint8Array(8);new DataView(raw.buffer).setBigUint64(0,words[index],true);db.run('INSERT INTO exact_word VALUES(?,?)',index,raw)}assert.equal(db.query('PRAGMA integrity_check').get().integrity_check,'ok');for(const row of db.query('SELECT ordinal,word FROM exact_word ORDER BY ordinal').all()){assert.equal(new DataView(row.word.buffer,row.word.byteOffset,row.word.byteLength).getBigUint64(0,true),words[row.ordinal])}db.close();await Bun.write(Bun.stdout,bytes);"#.replace("__WORDS__",&expected);let mut child=Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(body).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(output.stdout,body);}
fn row_spec()->RecordSpec{RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(1,"value",Shape::Float)])}
fn row_spec_controlled<C:os_dsl::NativeSchemaControl>(control:&mut C)->Result<RecordSpec,semio_framework_value::ValueError>{control.scoped_stage(|control|{control.begin_stage(1)?;let mut fields=control.allocate_vec(1)?;fields.push(os_dsl::schema::producer::field(1,"value",Shape::Float,control)?);control.step()?;os_dsl::schema::producer::record(None,RecordLayout::Inline,fields,control)})}
fn row_spec_producer()->os_dsl::RecordSpecProducer{os_dsl::RecordSpecProducer{ordinary:row_spec,decoding:|control|row_spec_controlled(control),encoding:|control|row_spec_controlled(control)}}
#[test]
fn ieee_payload_actual_native_pack_bytes_agree_with_independent_dataview_and_sqlite(){let words=words64();oracle(&os_pack::encode_record_body(&spec(),&record(&words),&EncodeOptions::default()).unwrap(),&words);}
#[test]
fn ieee_payload_table_columns_preserve_all_words_in_binary_and_text(){let words=words64();let spec=RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"rows",Shape::Table(row_spec_producer()))]);let mut input=RecordValue::default();input.fields.insert(1,FieldValue::List(words.iter().map(|word|{let mut row=RecordValue::default();row.fields.insert(1,FieldValue::Float(f64::from_bits(*word)));FieldValue::Record(row)}).collect()));let body=os_pack::encode_record_body(&spec,&input,&EncodeOptions::default()).unwrap();oracle(&body,&words);let(restored,_)=os_pack::decode_record_body(&body,&spec,&DecodeOptions::default()).unwrap();let text=os_dsl::print(&input,&spec,JoinMode::Document);for restored in [restored,os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap()]{let FieldValue::List(rows)=restored.get(1).unwrap()else{panic!("expected table")};assert_eq!(rows.iter().map(|row|{let FieldValue::Record(row)=row else{panic!("expected row")};float(row.get(1).unwrap()).to_bits()}).collect::<Vec<_>>(),words);}}
#[test]
fn ieee_payload_coordinates_and_glued_units_preserve_words_and_reject_incompatible_dimensions(){let spec=RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"position",Shape::Coord(3)),FieldSpec::new(2,"quantity",Shape::Quantity(semio_framework_dsl::unit_by_symbol("GPa").unwrap()))]);for word in words64(){let mut input=RecordValue::default();input.fields.insert(1,FieldValue::Tuple(vec![FieldValue::Float(f64::from_bits(word)),FieldValue::Float(-0.0),FieldValue::Float(1.25)]));input.fields.insert(2,FieldValue::Float(f64::from_bits(word)));let text=os_dsl::print(&input,&spec,JoinMode::Document);let restored=os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap();assert_eq!(float(restored.get(2).unwrap()).to_bits(),word);let FieldValue::Tuple(position)=restored.get(1).unwrap()else{panic!("expected coordinate")};assert_eq!(float(&position[0]).to_bits(),word);assert_eq!(float(&position[1]).to_bits(),(-0.0_f64).to_bits());if f64::from_bits(word).is_nan(){let compatible=text.replace("GPa","MPa");assert_eq!(float(os_dsl::parse(&compatible,&spec,&ParseOptions::default()).unwrap().get(2).unwrap()).to_bits(),word);assert!(os_dsl::parse(&text.replace("GPa","m"),&spec,&ParseOptions::default()).is_err());}}}
fn witness_view(word:&u64)->Result<os_pack::ScalarRecordView<'_>,&'static str>{Ok(os_pack::ScalarRecordView{ordinal:0,fields:[Some(os_pack::ScalarRecordField::F64(f64::from_bits(*word))),None,None]})}
#[test]
fn ieee_payload_scalar_witness_accepts_each_exact_word_and_rejects_changed_payload(){use std::sync::Arc;for word in words64(){let root=Arc::new(word);let mut witness=os_pack::ScalarRecordWireWitness::new(root.clone(),witness_view);let mut bytes=vec![1,0,0,1,0,5];bytes.extend(word.to_le_bytes());let mut offset=0;let mut complete=false;for _ in 0..128{match witness.advance(bytes.get(offset).copied()).unwrap(){os_pack::ScalarRecordWireStep::Consumed{..}=>offset+=1,os_pack::ScalarRecordWireStep::Complete=>{complete=true;break;},os_pack::ScalarRecordWireStep::Progress{..}=>{}}}assert!(complete);assert_eq!(offset,bytes.len());witness.begin_close();assert!(Arc::ptr_eq(&witness.take_root().unwrap(),&root));assert!(witness.terminal_is_empty());let mut witness=os_pack::ScalarRecordWireWitness::new(root.clone(),witness_view);bytes[6]^=1;let mut offset=0;let mut failed=false;for _ in 0..128{match witness.advance(bytes.get(offset).copied()){Err(_)=>{failed=true;break;},Ok(os_pack::ScalarRecordWireStep::Consumed{..})=>offset+=1,Ok(os_pack::ScalarRecordWireStep::Complete)=>break,Ok(os_pack::ScalarRecordWireStep::Progress{..})=>{}}}assert!(failed);witness.begin_close();assert!(Arc::ptr_eq(&witness.take_root().unwrap(),&root));assert!(witness.terminal_is_empty());}}

//! 🧩️ Derived pack-schema identity for snapshots that compose children and links: the hash is pinned,
//! structure-sensitive down to the nested `ArtifactLink`/`LinkPin` records, cross-checked with `blake3`
//! over the canonical graph bytes, and the derived codec round-trips byte-exactly.
use super::*;

#[derive(Clone, Debug, PartialEq, crate::os_dsl::DslRecord)]
#[dsl(extension = "composed")]
struct ComposedSnapshot {
    schema: String,
    document: ArtifactChild<()>,
    parts: Vec<ArtifactChild<()>>,
    cover: Option<ArtifactLink>,
    links: Vec<ArtifactLink>,
}

#[derive(Clone, Debug, PartialEq, crate::os_dsl::DslRecord)]
#[dsl(extension = "composed")]
struct ComposedWithoutLinks {
    schema: String,
    document: ArtifactChild<()>,
    parts: Vec<ArtifactChild<()>>,
    cover: Option<ArtifactLink>,
}

#[derive(Clone, Debug, PartialEq, crate::os_dsl::DslRecord)]
#[dsl(extension = "composed")]
struct ComposedRenamedChild {
    schema: String,
    model: ArtifactChild<()>,
    parts: Vec<ArtifactChild<()>>,
    cover: Option<ArtifactLink>,
    links: Vec<ArtifactLink>,
}

fn fixture() -> serde_json::Value {
    serde_json::from_str(include_str!("../../🧫️fixtures/🧩️composed-pack-schema/🔣️.json")).expect("composed pack schema fixture")
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn child(row: &serde_json::Value) -> ArtifactChild<()> {
    ArtifactChild::new(row["childId"].as_str().unwrap().into(), crate::os_io::ArtifactRef::parse_uri(row["target"].as_str().unwrap()).unwrap())
}

fn link(row: &serde_json::Value) -> ArtifactLink {
    let pin = match row["pin"]["kind"].as_str().unwrap() {
        "head" => LinkPin::Head,
        "checkpoint" => LinkPin::Checkpoint { id: row["pin"]["id"].as_str().unwrap().into() },
        "snapshot" => LinkPin::Snapshot { blob: BlobRef { hash: row["pin"]["hash"].as_str().unwrap().into(), size: row["pin"]["size"].as_u64().unwrap(), media_type: row["pin"]["mediaType"].as_str().unwrap().into() } },
        other => panic!("unknown pin kind {other}"),
    };
    ArtifactLink { target: crate::os_io::ArtifactRef::parse_uri(row["target"].as_str().unwrap()).unwrap(), pin, role: row["role"].as_str().unwrap().into() }
}

fn snapshot(row: &serde_json::Value) -> ComposedSnapshot {
    ComposedSnapshot {
        schema: row["schema"].as_str().unwrap().into(),
        document: child(&row["document"]),
        parts: row["parts"].as_array().unwrap().iter().map(child).collect(),
        cover: (!row["cover"].is_null()).then(|| link(&row["cover"])),
        links: row["links"].as_array().unwrap().iter().map(link).collect(),
    }
}

fn graph_json(spec: &crate::os_dsl::RecordSpec) -> serde_json::Value {
    serde_json::from_str(&semio_framework_pack_json::to_string(&crate::os_pack::PackSchemaGraph::of(spec).to_json())).expect("graph json")
}

fn renamed_role_link_spec() -> crate::os_dsl::RecordSpec {
    let mut spec = artifact_link_spec();
    spec.fields.iter_mut().find(|field| field.key == "role").expect("link role field").key = "purpose".into();
    spec
}

fn renamed_role_link_controlled<C: crate::os_dsl::NativeSchemaControl>(control: &mut C) -> Result<crate::os_dsl::RecordSpec, semio_framework_value::ValueError> {
    let mut spec = artifact_link_spec_controlled(control)?;
    let field = spec.fields.iter_mut().find(|field| field.key == "role").ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "link role field"))?;
    field.key = control.copy_text("purpose")?;
    Ok(spec)
}
fn renamed_role_link_producer() -> crate::os_dsl::RecordSpecProducer {
    crate::os_dsl::RecordSpecProducer { ordinary: renamed_role_link_spec, decoding: |control| renamed_role_link_controlled(control), encoding: |control| renamed_role_link_controlled(control) }
}

fn with_link_spec(link: crate::os_dsl::RecordSpecProducer) -> crate::os_dsl::RecordSpec {
    let mut spec = ComposedSnapshot::__dsl_spec();
    for field in &mut spec.fields {
        field.shape = match (field.key.as_str(), &field.shape) {
            ("cover", crate::os_dsl::Shape::Record(_)) => crate::os_dsl::Shape::Record(link),
            ("links", crate::os_dsl::Shape::List(_)) => crate::os_dsl::Shape::List(Box::new(crate::os_dsl::Shape::Record(link))),
            _ => continue,
        };
    }
    spec
}

#[test]
fn derived_graph_matches_the_language_agnostic_fixture() {
    let fixture = fixture();
    assert_eq!(graph_json(&ComposedSnapshot::__dsl_spec()), fixture["graph"]);
    let child_keys: Vec<String> = artifact_child_spec().fields.iter().map(|field| field.key.to_string()).collect();
    assert_eq!(serde_json::json!(child_keys), fixture["childFields"]);
    let link_keys: Vec<String> = artifact_link_spec().fields.iter().map(|field| field.key.to_string()).collect();
    assert_eq!(serde_json::json!(link_keys), fixture["linkFields"]);
}

#[test]
fn pack_schema_hash_is_pinned_and_matches_an_independent_blake3() {
    let fixture = fixture();
    let spec = ComposedSnapshot::__dsl_spec();
    let canonical = crate::os_pack::PackSchemaGraph::of(&spec).canonical_bytes();
    assert_eq!(hex(&canonical), fixture["canonicalHex"].as_str().unwrap());
    let expected = fixture["schemaHash"].as_str().unwrap();
    assert_eq!(hex(&crate::os_pack::schema_hash(&spec)), expected);
    assert_eq!(blake3::hash(&canonical).to_hex().to_string(), expected);
}

#[test]
fn pack_schema_hash_differs_when_the_structure_differs() {
    let fixture = fixture();
    let composed = crate::os_pack::schema_hash(&ComposedSnapshot::__dsl_spec());
    let without_links = crate::os_pack::schema_hash(&ComposedWithoutLinks::__dsl_spec());
    let renamed_child = crate::os_pack::schema_hash(&ComposedRenamedChild::__dsl_spec());
    let renamed_link_role = crate::os_pack::schema_hash(&with_link_spec(renamed_role_link_producer()));
    assert_eq!(crate::os_pack::schema_hash(&with_link_spec(artifact_link_spec_producer())), composed);
    assert_ne!(composed, without_links);
    assert_ne!(composed, renamed_child);
    assert_ne!(composed, renamed_link_role);
    assert_ne!(without_links, renamed_child);
    assert_eq!(hex(&without_links), fixture["withoutLinksSchemaHash"].as_str().unwrap());
    assert_eq!(hex(&renamed_child), fixture["renamedChildSchemaHash"].as_str().unwrap());
    assert_eq!(hex(&renamed_link_role), fixture["renamedLinkRoleSchemaHash"].as_str().unwrap());
}

#[test]
fn derived_codec_round_trips_composed_children_and_links_byte_exactly() {
    let fixture = fixture();
    for row in fixture["documents"].as_array().unwrap() {
        let document = snapshot(&row["snapshot"]);
        let spec = ComposedSnapshot::__dsl_spec();
        let bytes = crate::os_pack::encode_document(&spec, &document.__dsl_to_record(), &PackEncodeOptions::default()).expect("encode composed snapshot");
        assert_eq!(hex(&bytes), row["packHex"].as_str().unwrap(), "{}", row["name"]);
        let (record, report) = crate::os_pack::decode_document(&bytes, &spec, &PackDecodeOptions::default()).expect("decode composed snapshot");
        assert!(report.unknown_field_ids.is_empty() && !report.schema_drift);
        let decoded = ComposedSnapshot::__dsl_from_record(&record).expect("record to snapshot");
        assert_eq!(decoded, document);
        assert_eq!(crate::os_pack::encode_document(&spec, &decoded.__dsl_to_record(), &PackEncodeOptions::default()).expect("re-encode"), bytes);
        assert!(crate::os_pack::decode_document(&bytes, &ComposedWithoutLinks::__dsl_spec(), &PackDecodeOptions::default()).expect("narrow decode").1.schema_drift);
    }
}

//! 🌳️ Language-neutral borrowed-map, lifetime, and worker replay laws.

use super::*;
use std::sync::atomic::{AtomicUsize, Ordering};

//#region 🪪️LifetimeOracle
#[derive(Default, Debug)]
pub(super) struct MapLifetime {
    pub(super) active_iterators: AtomicUsize,
    pub(super) iterator_drops: AtomicUsize,
    pub(super) root_drops: AtomicUsize,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(untagged)]
pub(super) enum MapValue {
    Text(String),
    Array(Vec<MapValue>),
    Object(BTreeMap<String, MapValue>),
}

#[derive(Debug, Serialize, Deserialize, ToValue, FromValue)]
#[value(retire_with = "std::mem::drop")]
pub(super) enum MapMutation {
    ReplaceMap {
        map: BTreeMap<String, MapValue>,
        #[serde(skip)]
        #[value(skip)]
        lifetime: Arc<MapLifetime>,
        #[serde(skip)]
        #[value(skip)]
        tracked: bool,
    },
}

impl ToValue for MapValue {
    fn to_value(&self) -> DslValue {
        match self {
            Self::Text(value) => value.to_value(),
            Self::Array(value) => value.to_value(),
            Self::Object(value) => value.to_value(),
        }
    }
}

impl FromValue for MapValue {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        match value {
            DslValue::String(value) => Ok(Self::Text(value)),
            DslValue::Array(value) => value.into_iter().map(Self::from_value).collect::<Result<_, _>>().map(Self::Array),
            DslValue::Object(value) => value.into_iter().map(|(key, value)| Ok((key, Self::from_value(value)?))).collect::<Result<_, ValueError>>().map(Self::Object),
            _ => Err(ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "map fixture requires text, array, or object")),
        }
    }
}

impl Drop for MapMutation {
    fn drop(&mut self) {
        let Self::ReplaceMap { lifetime, tracked, .. } = self;
        if *tracked {
            assert_eq!(lifetime.active_iterators.load(Ordering::SeqCst), 0);
            lifetime.root_drops.fetch_add(1, Ordering::SeqCst);
        }
    }
}

struct MapIterator<'a> {
    entries: std::collections::btree_map::Iter<'a, String, MapValue>,
    lifetime: &'a MapLifetime,
}
impl<'a> Iterator for MapIterator<'a> {
    type Item = (&'a str, ArtifactCanonicalJsonValue<'a>);
    fn next(&mut self) -> Option<Self::Item> {
        self.entries.next().map(|(key, value)| (key.as_str(), map_value(value, self.lifetime)))
    }
}
impl Drop for MapIterator<'_> {
    fn drop(&mut self) {
        assert_eq!(self.lifetime.root_drops.load(Ordering::SeqCst), 0);
        self.lifetime.active_iterators.fetch_sub(1, Ordering::SeqCst);
        self.lifetime.iterator_drops.fetch_add(1, Ordering::SeqCst);
    }
}
//#endregion 🪪️LifetimeOracle

//#region 🧬️TypedTraversal
fn map_object<'a>(map: &'a BTreeMap<String, MapValue>, lifetime: &'a MapLifetime) -> ArtifactCanonicalJsonValue<'a> {
    lifetime.active_iterators.fetch_add(1, Ordering::SeqCst);
    ArtifactCanonicalJsonValue::Object(ArtifactCanonicalJsonObject::new(MapIterator { entries: map.iter(), lifetime }))
}

fn map_value<'a>(value: &'a MapValue, lifetime: &'a MapLifetime) -> ArtifactCanonicalJsonValue<'a> {
    match value {
        MapValue::Text(text) => ArtifactCanonicalJsonValue::Scalar(ArtifactCanonicalJsonNode::String(text)),
        MapValue::Array(values) => ArtifactCanonicalJsonValue::Array(ArtifactCanonicalJsonArray::new(values.iter().map(move |value| map_value(value, lifetime)))),
        MapValue::Object(map) => map_object(map, lifetime),
    }
}

impl ArtifactCanonicalJson for MapMutation {
    fn canonical_json_borrowed_root(&self) -> Result<Option<ArtifactCanonicalJsonValue<'_>>, String> {
        let Self::ReplaceMap { map, lifetime, .. } = self;
        let fields = ArtifactCanonicalJsonValue::Object(ArtifactCanonicalJsonObject::new([("map", map_object(map, lifetime))].into_iter()));
        Ok(Some(ArtifactCanonicalJsonValue::Object(ArtifactCanonicalJsonObject::new([("ReplaceMap", fields)].into_iter()))))
    }
}

struct IndexedDepth(usize);
impl ArtifactCanonicalJson for IndexedDepth {
    fn canonical_json_node(&self, path: &[usize]) -> Result<ArtifactCanonicalJsonNode<'_>, String> {
        Ok(if path.len() == self.0 { ArtifactCanonicalJsonNode::Null } else { ArtifactCanonicalJsonNode::Array(1) })
    }
}
//#endregion 🧬️TypedTraversal

//#region 🧹️OwnedRetirement
struct MapRetirement {
    owner: Option<MapMutation>,
    nodes: Vec<MapValue>,
    active: Option<Vec<u8>>,
}
impl ErasedSnapshotRetirement for MapRetirement {
    fn close_step(&mut self, items: usize, bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if items == 0 || bytes == 0 {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        if let Some(active) = self.active.as_mut() {
            let released_bytes = active.len().min(bytes);
            active.truncate(active.len() - released_bytes);
            if active.is_empty() {
                self.active = None;
            }
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes });
        }
        if let Some(node) = self.nodes.last_mut() {
            match node {
                MapValue::Text(text) => {
                    self.active = Some(std::mem::take(text).into_bytes());
                    self.nodes.pop();
                }
                MapValue::Array(values) => {
                    if let Some(value) = values.pop() {
                        self.nodes.push(value);
                    } else {
                        self.nodes.pop();
                    }
                }
                MapValue::Object(map) => {
                    if let Some((key, value)) = map.pop_first() {
                        self.active = Some(key.into_bytes());
                        self.nodes.push(value);
                    } else {
                        self.nodes.pop();
                    }
                }
            }
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.owner.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }
    fn terminal_is_empty(&self) -> bool {
        self.owner.is_none() && self.nodes.is_empty() && self.active.is_none()
    }
}

pub(super) struct MapRetirementFactory;
impl ArtifactOwnedValueRetirementFactory<MapMutation> for MapRetirementFactory {
    fn retire_owned(&self, mut value: MapMutation) -> Box<dyn ErasedSnapshotRetirement> {
        let MapMutation::ReplaceMap { map, lifetime, .. } = &mut value;
        assert_eq!(lifetime.active_iterators.load(Ordering::SeqCst), 0);
        let mut nodes = Vec::with_capacity(ARTIFACT_CANONICAL_JSON_DEPTH * 2);
        nodes.push(MapValue::Object(std::mem::take(map)));
        Box::new(MapRetirement { owner: Some(value), nodes, active: None })
    }
}
//#endregion 🧹️OwnedRetirement

