        const node = { name: `npm:${name}@${version}`, type: "npm", data: { packageName: name, version } };
        externalNodes[`npm:${name}`] = node;
        externalNodes[node.name] = node;
        const manifest = join(dirname(absolute), "node_modules", name, "package.json");
