    if (!plans.has(tests)) {
      try { plans.set(tests, nativePreparation(nativeRoot, workspaceRoot, contracts, tests, cache, closures)); }
      catch (error) {
        if (error.code !== "NATIVE_INPUT_ADMISSION") throw error;
        const admission = "native-input-admission";
