//! 🧪️ Actual retained parser syntax and owner lifecycle are distinct machine causes.
use crate::codec::*;
use semio_framework_value::ValueRefusalKind;

#[cfg(feature="deflate")]
fn close_authority_cursor(cursor:&mut DeflateRetainedCursor){
 for _ in 0..8{if cursor.close_step(8,usize::MAX)==RetainedInflateCloseStep::Complete{return}}
 panic!("bounded retained authority fixture failed to close")
}

#[cfg(feature="deflate")]
#[test]
fn actual_retained_deflate_syntax_lifecycle_and_requested_ceiling_are_distinct(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../⚠️error/🧫️fixtures/🧭️cause/📡️codec/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){
  let mut grammar=DeflateRetainedCursor::try_new(0,0,0).unwrap();
  let mut terminal=None;
  for byte in row["stored"].as_array().unwrap(){
   grammar.admit_byte(u8::try_from(byte.as_u64().unwrap()).unwrap()).unwrap();
   for _ in 0..64{
    match grammar.grant(false){Ok(DeflateRetainedStep::NeedInput)=>{},Ok(DeflateRetainedStep::Complete)=>break,Ok(DeflateRetainedStep::Byte(_))=>panic!("empty grammar corpus produced a byte"),Err(error)=>{terminal=Some(error);break}}
    if grammar.can_admit(){break}
   }
   if terminal.is_some(){break}
  }
  if terminal.is_none(){
   let mut complete=false;
   for _ in 0..64{match grammar.grant(true){Ok(DeflateRetainedStep::Complete)=>{complete=true;break},Ok(DeflateRetainedStep::NeedInput)=>{},Ok(DeflateRetainedStep::Byte(_))=>panic!("empty grammar corpus produced a byte"),Err(error)=>{terminal=Some(error);break}}}
   assert!(complete||terminal.is_some(),"bounded grammar fixture did not terminate");
  }
  close_authority_cursor(&mut grammar);
  assert_eq!(terminal.and_then(|error|error.refusal_kind().map(ValueRefusalKind::as_str)),row["expectedKind"].as_str());
 }
 let mut lifecycle=DeflateRetainedCursor::try_new(0,0,0).unwrap();
 let reset=lifecycle.reset(0,0);
 close_authority_cursor(&mut lifecycle);
 assert_eq!(reset.unwrap_err().refusal_kind(),Some(ValueRefusalKind::InvariantViolated));
 let mut syntax=DeflateRetainedCursor::try_new(0,0,0).unwrap();
 let admitted=syntax.admit_byte(7);
 let refusal=syntax.grant(true);
 let repeated=syntax.grant(true);
 close_authority_cursor(&mut syntax);
 assert!(admitted.is_ok());
 let refusal=refusal.unwrap_err();
 assert_eq!(refusal.refusal_kind(),Some(ValueRefusalKind::InvalidValue));
 assert_eq!(repeated.unwrap_err(),refusal);
 let ceiling=match DeflateRetainedCursor::try_new(1,0,0){Ok(mut cursor)=>{close_authority_cursor(&mut cursor);panic!("declared retained ceiling accepted")},Err(error)=>error};
 assert_eq!(ceiling.refusal_kind(),Some(ValueRefusalKind::OwnershipLimit));
 eprintln!("[DEBUG] Pack retained actual syntax/lifecycle/ceiling producers remained distinct");
}

//! 🧪️ Actual scheduler cancellation origins, without timing or source-text checks.
use super::*;
use semio_framework_value::ValueRefusalKind;
use std::sync::atomic::AtomicUsize;

struct AuthoritySource{reads:Arc<AtomicUsize>}
impl AsyncPackSource for AuthoritySource{
 fn len(&self)->u64{1}
 async fn read_at(&self,_:u64,_:usize)->Result<Vec<u8>,PackError>{self.reads.fetch_add(1,Ordering::SeqCst);std::future::pending().await}
}

#[test]
fn actual_scheduler_pre_cancel_and_pending_read_keep_canceled_authority(){
 let reads=Arc::new(AtomicUsize::new(0));
 let scheduler=ReadScheduler::new(AuthoritySource{reads:reads.clone()});
 let request=ReadRequest{range:ByteRange{offset:0,len:1},priority:LoadPriority::Critical};
 let canceled=CancellationToken::new();canceled.cancel();
 let refusal=semio_framework_async::block_on(scheduler.read(request,&canceled)).unwrap_err();
 assert_eq!(refusal.refusal_kind(),Some(ValueRefusalKind::Canceled));
 assert_eq!(reads.load(Ordering::SeqCst),0);
 let token=CancellationToken::new();
 let mut pending=Box::pin(scheduler.read(request,&token));
 let mut context=Context::from_waker(Waker::noop());
 assert!(pending.as_mut().poll(&mut context).is_pending());
 assert!(pending.as_mut().poll(&mut context).is_pending());
 assert_eq!(reads.load(Ordering::SeqCst),1);
 token.cancel();
 let refusal=semio_framework_async::block_on(pending).unwrap_err();
 assert_eq!(refusal.refusal_kind(),Some(ValueRefusalKind::Canceled));
 assert!(matches!(refusal,PackError::ValueRefusal(_)));
 eprintln!("[DEBUG] Pack scheduler both observed token producers retained Canceled");
}

//! 🧪️ Actual retry behavior is governed by explicitly injected provider policy.
use super::*;
use semio_framework_pack_error::PackRetryDisposition;
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::sync::atomic::AtomicUsize;

struct PolicyTransport{attempts:Arc<AtomicUsize>,retry:PackRetryDisposition}
impl RangeTransport for PolicyTransport{
 async fn fetch_range(&self,_:RangeRequest)->Result<RangeResponse,PackError>{
  self.attempts.fetch_add(1,Ordering::SeqCst);
  Err(PackError::Io{error:ValueError::new(ValueRefusalKind::WorkLimit,"same intentionally misleading permanent cancellation prose"),retry:self.retry})
 }
}

#[test]
fn actual_http_retries_only_explicit_transport_disposition(){
 for(retry,expected_attempts)in[(PackRetryDisposition::Never,1),(PackRetryDisposition::Transient,3)]{
  let attempts=Arc::new(AtomicUsize::new(0));
  let pool=Arc::new(WorkerPool::new(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative,3)));
  let runtime=RetryRuntime::native(pool.clone());
  let source=HttpPackSource::with_retry_policy("https://example.test/authority.pack".into(),PolicyTransport{attempts:attempts.clone(),retry},RetryPolicy{max_retries:2,initial_backoff:Duration::ZERO,max_backoff:Duration::ZERO},runtime);
  let result=semio_framework_async::block_on(source.read_at(0,1));
  pool.shutdown();
  let refusal=result.unwrap_err();
  assert_eq!(refusal.refusal_kind(),Some(ValueRefusalKind::WorkLimit));
  assert_eq!(attempts.load(Ordering::SeqCst),expected_attempts);
  assert!(matches!(refusal,PackError::Io{retry:actual,..}if actual==retry));
 }
 eprintln!("[DEBUG] Pack HTTP identical cause/prose followed distinct explicit retry policy");
}

