    expect(scale).toContain('"--target", "wasm32-wasip2", "--profile", "wasm-dev"');
  });

  it("never substitutes a first-found development artifact for publication identity", () => {
    const root = getWorkspaceRoot();
    const wasmTarget = join(cargoTargetDirectory(root), "wasm32-wasip2");
    const release = join(wasmTarget, "wasm-release", "fixture.wasm");
    const available = new Map([
      [join(wasmTarget, "wasm-dev", "fixture.wasm"), "dev-hash"],
      [join(wasmTarget, "debug", "fixture.wasm"), "stale-hash"],
      [release, "release-hash"],
    ]);
    expect(publicationWasmPath(root, "fixture.wasm")).toBe(release);
    expect(available.get(publicationWasmPath(root, "fixture.wasm"))).toBe("release-hash");
    available.delete(release);
    expect(available.get(publicationWasmPath(root, "fixture.wasm"))).toBeUndefined();
  });
});

type RenderedLaunch = {
  readonly configurations: readonly { name?: string; command?: string }[];
  readonly compounds?: readonly { name: string; configurations: readonly string[] }[];
  readonly inputs?: readonly { id: string; options?: readonly string[] }[];
};

/** ♻️ Renders `.vscode/launch.json` once for the whole block (seed + playground registry + every declared project target) —
 * the discovery walks over the workspace cost seconds, and every assertion below reads the same output. */
let renderedLaunch: Promise<{ readonly text: string; readonly launch: RenderedLaunch; readonly projects: readonly { readonly project: string; readonly path: string; readonly targets: readonly string[] }[] }> | undefined;
const renderLaunch = () => (renderedLaunch ??= (async () => {
  const repoRoot = getWorkspaceRoot();
  const { generatePlaygroundRegistry } = await import("../../🎮️playground/🔎️discovery/🟦️.ts");
  const { declaredProjectTargets, generateLaunchJson } = await import("../../🚀️launch/🟦️.ts");
  const projects = declaredProjectTargets(repoRoot);
  const text = generateLaunchJson(repoRoot, generatePlaygroundRegistry(repoRoot), projects);
  return { text, launch: Bun.JSONC.parse(text) as RenderedLaunch, projects };
})());
const launchOutput = async (): Promise<RenderedLaunch> => (await renderLaunch()).launch;

describe("launch configuration identity", () => {
  it("gives every configuration a unique name and keeps the user slot out of the collapse", async () => {
    const { devLaunchNameSuffix } = await import("../../🚀️launch/🏷️name-prefix/🟦️.ts");
    expect(devLaunchNameSuffix("🛠️dev🖥️s👤️2⚛️react")).toBe("👤️2⚛️react");
    expect(devLaunchNameSuffix("🛠️dev🖥️s⚛️react")).toBe("⚛️react");
    const launch = await launchOutput();
    const counts = new Map<string, number>();
    for (const entry of launch.configurations) counts.set(String(entry.name), (counts.get(String(entry.name)) ?? 0) + 1);
    expect([...counts].filter(([, count]) => count > 1).map(([name]) => name)).toEqual([]);
  });

  it("resolves every compound member to a real configuration", async () => {
    const launch = await launchOutput();
    const names = new Set(launch.configurations.map((entry) => String(entry.name)));
    const broken = (launch.compounds ?? []).flatMap((compound) => compound.configurations.filter((member) => !names.has(member)).map((member) => `${compound.name} -> ${member}`));
    expect(broken).toEqual([]);
    expect((launch.compounds ?? []).length).toBeGreaterThan(0);
  });

  it("registers a launch row for every canonical root lifecycle command", async () => {
    const launch = await launchOutput();
    const commands = new Set(launch.configurations.map((entry) => String(entry.command ?? "")));
    const generator = JSON.parse(readFileSync(new URL("../../🚀️launch/🧫️fixtures/🏭️generate/🔣️.json", import.meta.url), "utf8"));
    for (const command of ["setup", "start", "dev", "generate", "lint", "format", "test", "build", "publish"]) {
      const route = command === "generate" ? generator.target : `workspace:${command}`;
      expect([...commands].some((row) => row === `bun nx run ${route}` || row.startsWith(`bun nx run ${route} `)), command).toBe(true);
    }
  });
});

describe("declared project targets", () => {
  it("registers every declared project target as a launch row or through its family's project picker", async () => {
    const { launch, projects } = await renderLaunch();
    const runnable = new Set<string>();
    const pickers = new Map((launch.inputs ?? []).map((input) => [input.id, input.options ?? []]));
    for (const entry of launch.configurations) {
      const command = String(entry.command ?? "");
      for (const match of command.matchAll(/nx run ([^\s:$]+):(\S+)/gu)) runnable.add(`${match[1]}:${match[2]}`);
      for (const match of command.matchAll(/nx run \$\{input:([^}]+)\}:(\S+)/gu)) for (const project of pickers.get(match[1]!) ?? []) runnable.add(`${project}:${match[2]}`);
    }
    const missing = projects.flatMap((project) => project.targets.map((target) => `${project.project}:${target}`)).filter((pair) => !runnable.has(pair));
    expect(projects.length).toBeGreaterThan(100);
    expect(missing).toEqual([]);
  });

  it("gives every family picker the exact projects that declare its target", async () => {
    const { launch, projects } = await renderLaunch();
    for (const input of (launch.inputs ?? []).filter((entry) => entry.id.startsWith("projectTarget."))) {
      const row = launch.configurations.find((entry) => String(entry.command ?? "").includes(`\${input:${input.id}}:`));
      const target = /\}:(\S+)$/u.exec(String(row?.command ?? ""))?.[1];
      expect(target, input.id).toBeDefined();
      expect([...(input.options ?? [])]).toEqual(projects.filter((project) => project.targets.includes(target!)).map((project) => project.project).sort());
    }
  });

  it("declares every launch-projected project manifest as a registry catalog content input", async () => {
    const { projects } = await renderLaunch();
    const { loadCatalogTaxonomy, registryCatalogInputPaths, registryCatalogInputView } = await import("../../../../../../🦑️repo/🔨️modules/📚️library/🔍️discovery/🟦️.ts");
    const root = getWorkspaceRoot(), taxonomy = loadCatalogTaxonomy(), base = registryCatalogInputView(root, taxonomy);
    const manifests = projects.map((project) => (project.path ? `${project.path}/📋️project.json` : "📋️project.json"));
    const reachable = new Set(manifests.flatMap((manifest) => manifest.split("/").map((_, index, segments) => segments.slice(0, index + 1).join("/"))));
    const inputs = new Set(registryCatalogInputPaths(root, taxonomy, {
      kind: (path) => base.kind(path),
      readText: (path) => base.readText(path),
      entries: (path) => base.entries(path).filter((entry) => reachable.has(path ? `${path}/${entry.name}` : entry.name)),
    }));
    expect(manifests.length).toBeGreaterThan(100);
    expect(manifests.filter((manifest) => !inputs.has(manifest))).toEqual([]);
  });

  it("stays loadable by an independent JSONC reader and is byte-identical to the committed launch.json", async () => {
    const { text } = await renderLaunch();
    const ts = await import("typescript");
    const parsed = ts.parseConfigFileTextToJson(".vscode/launch.json", text);
    expect(parsed.error).toBeUndefined();
    expect(parsed.config).toEqual(Bun.JSONC.parse(text));
    expect(readFileSync(join(getWorkspaceRoot(), ".vscode/launch.json"), "utf8")).toBe(text);
  });
});

